window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0036", [{"word":"aggregate","ipa_uk":"/ˈæɡrɪɡət/","ipa_us":"/ˈæɡrɪɡət/","definition_zh":"合计；聚集；集合体；总数；合计的；聚合而成的；骨料","definition_en":"to gather separate units into one body or figure; the total or mass so formed; a material made of loose fragments; or, as an adjective, combined into a single whole","core_image":"把散在四处的羊一头头赶进同一个圈，再把这个圈当作一个数来数","scene":"工地上的自卸卡车把碎石和河砂倒进料斗，这些骨料和水泥、水一起被搅成混凝土。On the site, a tipper truck pours crushed stone and river sand into the hopper, and the aggregate is then mixed with cement and water to make concrete.","sceneCN":"这里 aggregate 是「骨料」（第 3 个义项：混凝土中的碎石、砂砾）；句意：工地上，自卸卡车把碎石和河砂倒进料斗，这些骨料随后与水泥、水混合制成混凝土。场景要点：自卸卡车、碎石堆、河砂、料斗、水泥袋、转动的搅拌机。","pos":[{"tag":"n.","zh":"总数；合计；集合体；骨料"},{"tag":"adj.","zh":"合计的；聚合而成的"},{"tag":"vt.","zh":"合计；把……聚成一体"},{"tag":"vi.","zh":"聚集成团；汇合"}],"collocations":[{"phrase":"in the aggregate","zh":"总体上；作为整体来看"},{"phrase":"on aggregate","zh":"按两回合总比分（英式体育）"},{"phrase":"aggregate demand","zh":"总需求（经济学）"},{"phrase":"aggregate score","zh":"总分；合计得分"},{"phrase":"aggregate data","zh":"汇总数据"},{"phrase":"an aggregate of","zh":"……的集合体；……的总和"},{"phrase":"lightweight aggregate","zh":"轻质骨料"}],"forms":[{"label":"三单（he/she/it）","form":"aggregates"},{"label":"过去式（已经发生）","form":"aggregated"},{"label":"过去分词（完成／被动）","form":"aggregated"},{"label":"现在分词（进行体）","form":"aggregating"},{"label":"名词复数","form":"aggregates"}],"derivatives":[{"word":"aggregation","pos":"n.","zh":"聚集；聚合；集合体；数据汇总"},{"word":"aggregator","pos":"n.","zh":"汇总者；聚合器；内容聚合平台"},{"word":"aggregative","pos":"adj.","zh":"聚集的；聚合性的"},{"word":"disaggregate","pos":"v.","zh":"分解；拆分（汇总数据）"},{"word":"disaggregation","pos":"n.","zh":"分解；拆分"}],"senses":[{"no":"01","title":"Add the parts into one figure","titleCN":"把各部分加成一个数","definition":"to add separate amounts or results together and state them as a single total","definitionCN":"把分开的数额或结果相加，并用一个总数来表述","example":"The auditor aggregated the four quarterly reports into one annual figure.","exampleCN":"审计员把四份季度报告合计成一个年度数字。","why":"The Latin verb meant bring together into a flock. Numbers can be treated as animals driven into one pen: once they stand in the same enclosure they can be counted as one herd.","whyCN":"拉丁动词本义是“赶成一群”。数字也可以当作被赶进同一个圈里的牲畜：它们站进同一个围栏后，就能当作一群来数。"},{"no":"02","title":"A total made of separate amounts","titleCN":"由若干数额合成的总数","definition":"a total number or amount formed by adding smaller amounts, especially when the parts are still known","definitionCN":"由较小数额相加而成的总数，尤指各部分仍可追溯时","example":"The aggregate of the five county totals was larger than the state forecast.","exampleCN":"五个县总数合起来，超过了州里的预测。","why":"Once the addition is finished, the pen itself holds a herd. The noun names the sum as a thing rather than the act of adding it up.","whyCN":"加法做完之后，圈里就装着一群牲畜了。名词把这个和当作一个东西来命名，而不是指相加的动作。"},{"no":"03","title":"Loose fragments used to make concrete","titleCN":"用来做混凝土的骨料","definition":"crushed stone, gravel, or sand mixed with cement and water to form concrete","definitionCN":"与水泥、水混合制成混凝土的碎石、砾石或砂","example":"The mix was one part cement to three parts aggregate.","exampleCN":"配比是一份水泥对三份骨料。","why":"In building, the fragments are literally gathered into a binder. They keep their separate identity inside the concrete, which is the flock image carried into stone.","whyCN":"在建筑中，这些碎块确实被聚进一个胶结物里。它们在混凝土内部保持各自的独立身份，正是“羊群”意象搬到了石头上。"},{"no":"04","title":"Combined into one figure","titleCN":"合并成一个数字的","definition":"of a figure, score, or measure, formed by combining several items rather than shown separately","definitionCN":"指数字、得分或指标由若干项目合并而成，而非分列显示","example":"Aggregate demand fell for the third quarter in a row.","exampleCN":"总需求连续第三个季度下降。","why":"As an adjective the word stops naming the act and describes the result: the figure is of the gathered kind, one number standing for many.","whyCN":"作形容词时，这个词不再命名动作，而是描述结果：这个数字属于“被聚拢起来”的那一类，一个数字代表许多个。"},{"no":"05","title":"Made of clustered parts, not fused","titleCN":"由簇生部分构成而非熔合的","definition":"of a fruit, rock, or crystal, composed of separate units clustered together but not chemically united","definitionCN":"指果实、岩石或晶体由彼此簇集但未化学融合的独立单元组成","example":"A raspberry is an aggregate fruit: many small drupelets share one receptacle.","exampleCN":"覆盆子是聚合果：许多小核果共享一个花托。","why":"Here the flock is visible in the object itself. The parts remain distinct, so the adjective describes structure rather than arithmetic.","whyCN":"在这里，羊群直接出现在物体本身。各部分仍保持区别，所以这个形容词描述的是结构，而不是算术。"},{"no":"06","title":"Gather separate things into one body","titleCN":"把分开的事物聚成一个整体","definition":"to bring separate people, groups, or things together into a single organization or mass","definitionCN":"把分开的人、群体或事物聚进同一个组织或团块","example":"The cooperative aggregated smallholders who had once sold to rival buyers.","exampleCN":"这个合作社把原先卖给不同收购商的小农聚合到一起。","why":"This returns to the literal Latin image with human beings as the flock: independent units are driven into one social enclosure without losing their identity.","whyCN":"这里回到拉丁语的字面意象，只是羊群换成了人：独立的单位被赶进同一个社会围栏，但并不失去各自的身份。"},{"no":"07","title":"Come together by itself into clumps","titleCN":"自行聚集成团","definition":"of particles, cells, or animals, to clump or gather without an outside agent","definitionCN":"指颗粒、细胞或动物在没有外力驱赶的情况下自行结团、聚集","example":"Dust particles aggregate around the charged plate.","exampleCN":"尘埃颗粒在带电极板周围聚集。","why":"The intransitive use, recorded from 1855, drops the herdsman. The units now do the driving themselves, but the shape of the result is the same pen.","whyCN":"不及物用法记录于 1855 年，它去掉了牧羊人。现在是被聚的单位自己在驱赶自己，但结果的形状仍是同一个圈。"},{"no":"08","title":"The combined score across two legs","titleCN":"两回合的总比分","definition":"the combined score of two matches, used to decide a tie when each side has won one","definitionCN":"两场比赛的合计比分，用于在两队各胜一场时决定胜负","example":"They lost the second leg 2–1 but advanced 4–3 on aggregate.","exampleCN":"他们第二回合 2 比 1 落败，却以两回合 4 比 3 的总比分晋级。","why":"A two-leg tie is arithmetic performed on a flock: the goals of both nights are penned together, and only the total walks out.","whyCN":"两回合制就是把算术做在一群牲畜上：两晚的进球被关进同一个圈，最后只有总数走出来。"},{"no":"09","title":"Considered as a whole, not in parts","titleCN":"作为整体而非逐项来看","definition":"considered as a whole rather than as separate members, chiefly in the phrase in the aggregate","definitionCN":"把事物当作一个整体来看，而不是逐个成员来看，主要用于短语 in the aggregate","example":"In the aggregate, small farms produce a surprising share of the world's food.","exampleCN":"从总体上看，小农场生产的粮食占全球比例高得出人意料。","why":"When you look at the pen from a distance you no longer see individual animals, only one moving mass. The phrase fixes that viewpoint as a distinct sense.","whyCN":"从远处看这个圈时，你不再看见一头头牲畜，只看见一团在移动的整体。这个短语把这种视角固定成一个独立义项。"}],"etymology":{"intro":{"en":"Aggregate entered English around 1400 as the past participle of Latin aggregare, 'bring together in a flock'. The chain is ad- 'to' + gregare 'gather into a flock' + -atus, the participle ending; English then made the participle an adjective, the adjective a noun, and much later a verb. The greg- inside it is grex 'flock', which also gives gregarious, congregate, segregate and egregious. It has nothing to do with aggravate, whose root is gravis 'heavy'.","cn":"aggregate 约在 1400 年进入英语，形式是拉丁语 aggregare“赶成一群”的过去分词。链条是 ad-“向”+ gregare“赶成一群”+ -atus（过去分词词尾）；英语先把分词用作形容词，再把形容词用作名词，很久以后才用作动词。其中的 greg- 就是 grex“群、畜群”，同根词还有 gregarious、congregate、segregate、egregious。它与 aggravate 无关，后者的词根是 gravis“重”。"},"items":[{"era":"c. 1400","en":"First recorded as an adjective meaning 'associated, united', borrowed from Latin aggregatus, the past participle of aggregare.","cn":"最早记录为形容词，意为“联合的、结合在一起的”，借自拉丁语 aggregatus，即 aggregare 的过去分词。"},{"era":"LATIN","en":"Aggregare means 'add to a flock, lead to a flock, bring together in a flock', figuratively 'attach, join, include, collect'. It is ad- 'to' plus gregare 'collect into a flock'.","cn":"aggregare 意为“加到群里、赶到群里、聚成一群”，引申为“附上、连接、包括、收集”。它由 ad-“向”加 gregare“赶成一群”构成。"},{"era":"LATIN / PIE","en":"Gregare comes from grex (genitive gregis) 'a flock, herd', traced to PIE *ger- 'to gather'. The same root yields gregarious, congregate, segregate and egregious, and perhaps Greek agora 'assembly'.","cn":"gregare 出自 grex（属格 gregis）“群、畜群”，可追溯到原始印欧语 *ger-“收集”。同一词根产生 gregarious、congregate、segregate、egregious，可能还有希腊语 agora“集会”。"},{"era":"EARLY 15c","en":"The noun appears as a noun use of the neuter adjective aggregatum, 'a number of persons or things regarded as a unit'. The arithmetic sense is therefore as old as the word in English.","cn":"名词义来自中性形容词 aggregatum 的名词化，意为“被视为一个单位的一群人或物”。因此算术义与这个词进入英语的历史一样古老。"},{"era":"1855 / 20c","en":"The intransitive 'come together in a sum or mass' is recorded from 1855. Technical uses multiply later: aggregate demand in economics, aggregate as the stone and sand in concrete, aggregate fruit in botany.","cn":"不及物的“聚合成一个总数或团块”记录于 1855 年。技术用法后来大量增加：经济学的 aggregate demand、混凝土中作为石砂的 aggregate、植物学的 aggregate fruit。"},{"era":"LOOK-ALIKE, NOT COGNATE","en":"Aggravate is ad- + gravis 'heavy', from PIE *gwere- 'heavy'; its core is 'make heavier', not 'gather'. The shared ag- is only the assimilated form of ad-, so the two words resemble each other at the front and nowhere else.","cn":"aggravate 是 ad- 加 gravis“重”（原始印欧语 *gwere-“重”），核心是“使更重”，不是“聚集”。相同的 ag- 只是 ad- 的同化形式，所以这两个词只有词头相像，其余部分毫无关系。"}]},"similar":{"note":{"en":"The first group isolates the traps: a root that only looks the same, two same-root words with opposite prefixes, and the derived noun. The second group compares the words learners use when they mean a plain total, with no image of units gathered into a body.","cn":"第一组隔离陷阱：一个只是长得像的词根、两个同根但前缀相反的词，以及派生名词。第二组比较学习者在想说“单纯的总数”时最常替换的词，它们都没有“把单位聚成一体”的意象。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"aggravate","ipa":"/ˈæɡrəveɪt/","tag":"different root","definition":"to make a bad situation worse, or to annoy someone. Its root is gravis 'heavy', so the ag- matches aggregate only by the assimilation of ad-.","definitionCN":"使坏情况更糟，或惹恼某人。它的词根是 gravis“重”，ag- 只是 ad- 的同化形式，与 aggregate 仅词头相同。"},{"word":"congregate","ipa":"/ˈkɒŋɡrɪɡeɪt/","tag":"same root, con-","definition":"of people or animals, to come together in a crowd. It shares grex 'flock', but con- 'together' describes the assembled body rather than the movement toward it.","definitionCN":"指人或动物聚集成群。它共享 grex“群”，但 con-“一起”描述的是聚成之后的群体，而不是聚拢的方向。"},{"word":"segregate","ipa":"/ˈsiːɡrɪɡeɪt/","tag":"same root, se-","definition":"to set one group apart from the rest. It shares grex too, but se- 'apart' reverses the direction: out of the flock, not into it.","definitionCN":"把某一群体与其余分开。它同样共享 grex，但 se-“分开”把方向反过来：是离开羊群，而不是进入羊群。"},{"word":"aggregation","ipa":"/ˌæɡrɪˈɡeɪʃn/","tag":"derived noun","definition":"the act or result of gathering separate things. It is aggregate plus -ation, so it names the process or the collection, not the total number itself.","definitionCN":"把分开的事物聚集起来的行为或结果。它是 aggregate 加 -ation，命名过程或集合物，而不是总数本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"total","ipa":"/ˈtəʊtl/","tag":"plain arithmetic","definition":"the complete amount after everything has been added. It is a bare arithmetic word with no picture of separate units gathered into a body.","definitionCN":"所有项目相加后的完整数额。它是纯算术词，没有“独立的单位被聚成一个整体”的画面。"},{"word":"sum","ipa":"/sʌm/","tag":"result of addition","definition":"the number obtained by adding two or more amounts. It is countable and mathematical; aggregate can also be a material or a gathered body.","definitionCN":"两个或更多数额相加所得的数字。它可数、偏数学；而 aggregate 还可以指材料或聚成的实体。"},{"word":"collective","ipa":"/kəˈlektɪv/","tag":"shared by a group","definition":"belonging to or done by a group as a whole. It describes ownership or action, not a computed figure.","definitionCN":"属于一个群体或由群体整体执行的。它描述所有权或行动，而不是算出来的数字。"},{"word":"cumulative","ipa":"/ˈkjuːmjələtɪv/","tag":"adding over time","definition":"growing by repeated addition over time. It stresses the process and the time axis, while aggregate stresses the single resulting whole.","definitionCN":"随着时间反复累加而增长。它强调过程与时间轴，而 aggregate 强调最终形成的单一整体。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: ad- 'to' plus greg- 'flock', the grex family, the aggravate trap, the two fixed phrases that split two senses, and the regular suffix chain.","cn":"只用真实成分与真实同族词：ad-“向”加 greg-“群”、grex 词族、aggravate 陷阱、区分两个义项的两条固定短语，以及规则的词缀链。"},"normal":[{"en":"ad- means 'to' and greg- means 'flock': aggregate is literally 'drive to the flock', so gathering and totalling are one motion.","cn":"ad- 意为“向”，greg- 意为“群”：aggregate 字面上就是“赶向羊群”，所以“聚集”和“合计”是同一个动作。"},{"en":"Grex, gregis is Latin for 'flock'; the same greg- runs through gregarious, congregate, segregate and egregious.","cn":"grex、gregis 是拉丁语“群”；同一个 greg- 贯穿 gregarious、congregate、segregate、egregious。"},{"en":"The front of aggravate looks identical, but its root is gravis 'heavy': aggravate makes things heavier, aggregate makes them one.","cn":"aggravate 的词头看起来一模一样，但它的词根是 gravis“重”：aggravate 让东西更重，aggregate 让东西成为一个。"},{"en":"Two phrases split two senses: in the aggregate means 'considered as a whole'; on aggregate means 'on the combined score of two legs'.","cn":"两条短语区分两个义项：in the aggregate 意为“从整体看”；on aggregate 意为“按两回合的总比分”。"},{"en":"The suffixes are regular: -ation makes the process noun, -or the agent, -ive the adjective, and dis- reverses the whole operation.","cn":"后缀很规则：-ation 构成过程名词，-or 构成施动者，-ive 构成形容词，dis- 把整个操作反过来。"}],"abstract":[{"en":"Sheep scattered across a hillside are driven through one gate; the pen, not the hill, is what you count.","cn":"散在山坡上的羊被赶过同一道门；你要数的是圈里的羊，而不是整面山坡。"},{"en":"Gravel and sand keep their own edges inside concrete; a mass can be one thing without its parts melting together.","cn":"砾石和砂在混凝土里仍保有自己的棱角；一个整体可以由未熔合的部分组成。"},{"en":"A column of figures on separate lines becomes a single number at the bottom; that bottom line is the aggregate.","cn":"分行排列的一列数字，在底部变成一个单独的数字；那条底线就是 aggregate。"}]},"examples":[{"en":"The three regional totals were aggregated into a single national figure.","cn":"三个地区的总数被合计成一个全国数字。"},{"en":"Crushed granite is used as aggregate in roads and buildings.","cn":"碎花岗岩被用作道路和建筑中的骨料。"},{"en":"In the aggregate, the surveys suggest a slow recovery of the reef.","cn":"从总体上看，这些调查显示珊瑚礁正在缓慢恢复。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿格雷盖特」——阿格雷把散开的羊“赶”进一个盖好的羊圈，一“合”就成一群 → aggregate 聚集；合计（只借音，不表词源）","word":"aggregate"},"root":"拉丁 aggregare「赶成一群、聚拢」，由 ad-「向」+ gregare「赶成一群」构成，后者出自 grex/gregis「群、畜群」；核心是「把散开的个体赶进同一个圈，再当作一个整体」。与 aggravate（gravis「重」）只是前缀形似，词根不同。","sensesIntro":{"en":"Nine senses of aggregate keep one picture: separate units are driven into a single enclosure. What changes is what you watch — the driving (the verbs), the pen (the totals), or the way the parts sit inside it (the material and botanical senses).","cn":"aggregate 的九个义项共用一个画面：分开的单位被赶进同一个围栏。变化的是你盯着什么看——赶的动作（动词义）、装好的圈（总数义），还是部分在圈里的排列方式（材料与植物义）。"},"semanticMap":{"core":{"en":"CORE IMAGE: many separate animals driven through one gate into a single pen.","cn":"核心意象：许多分开的牲畜被赶过同一道门，关进同一个圈。"},"chain":["MANY SEPARATE UNITS","DRIVEN THROUGH ONE GATE","COUNTED AS ONE HERD","A TOTAL, NOT THE PARTS","PARTS STILL VISIBLE INSIDE","ONE WORD FOR BOTH"],"branches":[{"senses":"01 · 02","en":"ARITHMETIC: drive the amounts into one pen, then name either the counting or the total that stands in it.","cn":"算术：把各笔数额赶进同一个圈，然后命名数这个的动作，或命名圈里那个总数。"},{"senses":"03 · 05","en":"MATERIAL STRUCTURE: fragments gathered but not fused — the stone and sand in concrete, the drupelets of an aggregate fruit, the units of an aggregate rock.","cn":"材料结构：碎块被聚在一起却未熔合——混凝土里的石砂、聚合果的小核果、聚合岩的单元。"},{"senses":"04","en":"ADJECTIVAL FIGURE: one combined number or measure standing for many separate items, as in aggregate demand or an aggregate score.","cn":"形容词性的数字：一个合并后的数字或指标代表许多分开的项目，如总需求或总分。"},{"senses":"06 · 07","en":"THE VERBS: the transitive act of driving units together, and the intransitive act of units clumping by themselves.","cn":"动词义：及物地把他者驱赶聚拢，以及不及物地由单位自行结成团。"},{"senses":"08 · 09","en":"THE TOTAL VIEW: a two-leg score read as one figure, and a society or dataset regarded as a whole rather than member by member.","cn":"整体视角：把两回合比分读成一个数字，以及把社会或数据集当作整体而非逐个成员来看。"}]},"affixes":{"intro":{"en":"Aggregate is a Latin participle that English turned into three parts of speech. The Latin core is ad- 'to' + greg- 'flock' + -atus; English added no new prefix, but built a family with -ation, -or, -ive and dis-.","cn":"aggregate 是一个拉丁语分词，英语把它用成了三种词性。拉丁内核是 ad-“向”+ greg-“群”+ -atus；英语没有另加前缀，但用 -ation、-or、-ive 和 dis- 建起了一个词族。"},"latinIntro":{"en":"The Latin family is grex 'flock', gregare 'to gather into a flock', and aggregare 'to bring to a flock'. The same grex underlies congregare, segregare and the adjective egregius.","cn":"拉丁词族包括 grex“群”、gregare“赶成一群”、aggregare“聚到群里”。同一个 grex 也是 congregare、segregare 和形容词 egregius 的基础。"},"items":[{"word":"aggregate","structure":"ad- (to) + greg- (flock) + -ate (Latin participle ending)","meaning":"to drive into one flock, hence to gather or total","meaningCN":"赶成一群，因而表示聚集、合计（ad- 向 + greg- 群 + -ate 分词词尾）","example":"They aggregated the village records into one ledger.","exampleCN":"他们把各村的记录汇总成一本账。"},{"word":"aggregation","structure":"aggregate + -ation (process or result noun)","meaning":"the act or result of gathering into a whole","meaningCN":"聚集成整体的动作或结果（-ation 过程／结果名词）","example":"The aggregation of the data took a week.","exampleCN":"数据汇总花了一周。"},{"word":"aggregator","structure":"aggregate + -or (one who or that which does)","meaning":"a person or program that collects things from many sources","meaningCN":"从多处收集内容的个人或程序；聚合器（-or 施动者）","example":"The news aggregator pulls headlines from fifty sites.","exampleCN":"这个新闻聚合器从五十个网站抓取标题。"},{"word":"aggregative","structure":"aggregate + -ive (adjective of tendency)","meaning":"tending to gather things into a mass","meaningCN":"倾向于把事物聚成一体的（-ive 倾向形容词）","example":"The study describes the aggregative behaviour of the cells.","exampleCN":"这项研究描述了细胞的聚集行为。"},{"word":"disaggregate","structure":"dis- (apart, reverse) + aggregate","meaning":"to break a total back into its parts","meaningCN":"把汇总数拆回各组成部分（dis- 反向 + aggregate）","example":"The agency disaggregates the national figure by region.","exampleCN":"该机构把全国数字按地区拆分。"},{"word":"gregarious","structure":"greg- (flock) + -ous (full of, given to)","meaning":"fond of company; living in herds","meaningCN":"爱群居的；成群生活的（greg- 群 + -ous 充满）","example":"Locusts become gregarious when their numbers rise.","exampleCN":"蝗虫数量增加时会变得群居。"},{"word":"congregate","structure":"con- (together) + greg- (flock) + -ate","meaning":"to come together into a crowd","meaningCN":"聚集成群（con- 一起 + greg- 群 + -ate）","example":"The birds congregate on the mudflats at low tide.","exampleCN":"退潮时鸟群聚集在泥滩上。"},{"word":"segregate","structure":"se- (apart) + greg- (flock) + -ate","meaning":"to separate one group from the rest","meaningCN":"把某群体与其余分开（se- 分开 + greg- 群 + -ate）","example":"The plant segregates the two ores by density.","exampleCN":"工厂按密度把两种矿石分开。"},{"word":"egregious","structure":"e- (out of) + greg- (flock) + -ious","meaning":"standing out from the flock, hence conspicuously bad","meaningCN":"从群中突出，因而指显眼地糟糕（e- 出 + greg- 群 + -ious）","example":"The report called the error egregious.","exampleCN":"报告称这个错误极其严重。"},{"word":"grex","structure":"Latin noun, genitive gregis","meaning":"flock, herd; the source of the whole greg- family","meaningCN":"群、畜群；整个 greg- 词族的源头","example":"The Latin word grex, 'flock', survives inside aggregate.","exampleCN":"拉丁词 grex“群”仍活在 aggregate 里面。"}],"latinEntries":[{"word":"aggregare","structure":"ad- (to) + gregare (gather into a flock)","meaning":"to bring to a flock, attach, collect","meaningCN":"赶到群里；附加；收集"},{"word":"gregare","structure":"from grex, gregis (flock)","meaning":"to collect into a flock","meaningCN":"赶成一群"},{"word":"grex","structure":"Latin noun, genitive gregis; from PIE *ger- 'to gather'","meaning":"flock, herd","meaningCN":"群；畜群"}]}},{"word":"aggregation","ipa_uk":"/ˌæɡrɪˈɡeɪʃn/","ipa_us":"/ˌæɡrɪˈɡeɪʃən/","definition_zh":"聚集；聚合；集合体；聚集物；（血小板）凝集；数据汇总；内容聚合；土壤团聚","definition_en":"the act of gathering separate units into one body, the body so formed, or a technical instance of such gathering in medicine, biology, data, economics, computing, or soil science","core_image":"把散在场地上的木箱一个个码进同一间仓库：码的过程和码好的那一堆，都叫同一个名字","scene":"离心后的血样被送进分析仪，血小板凝集的曲线在屏幕上一点点抬起来。After the blood sample is spun, platelet aggregation appears as a rising curve on the analyser screen.","sceneCN":"这里 aggregation 是「（血小板）凝集」（第 4 个义项：血细胞或颗粒在体内聚结）；句意：血样离心后，血小板凝集在分析仪屏幕上呈现为一条上升的曲线。场景要点：离心管、血浆分层、分析仪屏幕、上升的曲线、检验标签。","pos":[{"tag":"n.","zh":"聚集；聚合；集合体；聚集物；汇总"}],"collocations":[{"phrase":"platelet aggregation","zh":"血小板凝集"},{"phrase":"data aggregation","zh":"数据汇总；数据聚合"},{"phrase":"news aggregation","zh":"新闻聚合"},{"phrase":"an aggregation of","zh":"……的集合体；一群……"},{"phrase":"aggregation of individuals","zh":"个体的聚集"},{"phrase":"soil aggregation","zh":"土壤团聚"},{"phrase":"aggregation problem","zh":"加总问题（经济学）"}],"forms":[{"label":"名词复数","form":"aggregations"}],"derivatives":[{"word":"aggregate","pos":"v./n./adj.","zh":"聚集；合计；总数；合计的"},{"word":"aggregative","pos":"adj.","zh":"聚集的；聚合性的"},{"word":"aggregator","pos":"n.","zh":"汇总者；聚合器"},{"word":"disaggregation","pos":"n.","zh":"分解；拆分"}],"senses":[{"no":"01","title":"The act of bringing separate things together","titleCN":"把分开的事物聚拢的动作","definition":"the act of collecting separate people, things, or amounts into one group or total","definitionCN":"把分开的人、事物或数额收集进一个群体或总数的动作","example":"The aggregation of the six village registers took two months.","exampleCN":"把六个村的登记册汇总起来花了两个月。","why":"The -ation suffix names an action, not a thing: it is the herdsman's work of driving animals through the gate, seen as a process.","whyCN":"-ation 后缀命名的是动作，不是物件：它是牧人把牲畜赶过门去的那份劳作，被看成一个过程。"},{"no":"02","title":"The body that results from gathering","titleCN":"聚拢之后形成的整体","definition":"the group or mass that results from such collecting, viewed as a single body","definitionCN":"由这种收集形成并被当作单一整体的群体或团块","example":"The federation began as an aggregation of independent guilds.","exampleCN":"这个联合会最初是若干独立行会的集合体。","why":"Latin action nouns in -atio could name both the act and its result, and English kept both. Once the gate closes, the pen full of animals is itself an aggregation.","whyCN":"拉丁语以 -atio 结尾的动作名词既可指动作也可指结果，英语把两者都保留了。门一关上，装满牲畜的圈本身就是 an aggregation。"},{"no":"03","title":"A loose, unorganized mass","titleCN":"松散无序的一堆","definition":"a heap or crowd of things gathered without order or system, a sense recorded from the 1560s","definitionCN":"未经秩序或体系整理而堆聚起来的一堆物或一群人，此义记录于 16 世纪 60 年代","example":"The attic held an aggregation of broken chairs, lamps, and boxes.","exampleCN":"阁楼里堆着一堆坏椅子、台灯和箱子。","why":"If nothing sorts the units, the pen shows only a random heap. The word then stresses the absence of structure rather than the fact of gathering.","whyCN":"如果没有东西来整理这些单位，圈里就只剩随机的一堆。此时这个词强调的不是“聚拢”这件事，而是“没有结构”。"},{"no":"04","title":"Clotting or clumping inside the body","titleCN":"体内的凝集","definition":"the clumping together of blood cells, platelets, or other particles in the body","definitionCN":"血细胞、血小板或其他颗粒在体内聚结成团","example":"Platelet aggregation is the first step in sealing a cut vessel.","exampleCN":"血小板凝集是封住破损血管的第一步。","why":"Medicine borrowed the image at the cellular scale: cells are the flock, and they gather at a wound. The earliest English use, in the early 15th century, was already medical — the formation of a pustule.","whyCN":"医学把这个意象借到细胞尺度：细胞是羊群，在伤口处聚拢。英语最早的用法在 15 世纪早期，已经是医学义——脓疱的形成。"},{"no":"05","title":"Animals gathered at one place","titleCN":"动物在同一地点集群","definition":"a temporary gathering of animals, especially birds or insects, at one place","definitionCN":"动物尤其是鸟类或昆虫在同一地点的临时聚集","example":"An aggregation of gulls followed the trawler for its discards.","exampleCN":"一群海鸥跟着拖网渔船，等着被丢弃的杂鱼。","why":"Here the flock is literal again. The word is preferred over herd or flock when the gathering is temporary and the animals are not a permanent social unit.","whyCN":"这里“群”又回到字面。当聚集是临时的、动物并非永久社会单位时，人们更愿意用这个词而不是 herd 或 flock。"},{"no":"06","title":"Combining data into totals","titleCN":"把数据合成总数","definition":"the process of combining data from many sources into a single set or summary","definitionCN":"把来自许多来源的数据合并成一个数据集或摘要的过程","example":"The dashboard performs nightly aggregation of sales records from 400 stores.","exampleCN":"仪表盘每晚对 400 家门店的销售记录做一次汇总。","why":"Data are treated as countable units. The process sense of the suffix is applied to records, and the result is a total that can be queried.","whyCN":"数据被当作可数的单位。后缀的“过程”义被用到记录上，产物就是一个可以查询的总数。"},{"no":"07","title":"Gathering content from many sites","titleCN":"从多处网站汇集内容","definition":"the automatic collection of news, links, or other content from many sites into one feed","definitionCN":"把新闻、链接或其他内容从许多网站自动收集进同一个信息流","example":"The site is a news aggregator; its value lies in aggregation, not in reporting.","exampleCN":"这个网站是新闻聚合器；它的价值在于聚合，而不在于采写。","why":"The flock now consists of pages scattered across the web. Software plays the herdsman, and the feed is the pen the reader visits.","whyCN":"现在这群“牲畜”是散落在网络上的页面。软件扮演牧人，信息流就是读者走进的那个圈。"},{"no":"08","title":"A combined economic measure","titleCN":"合并而成的经济指标","definition":"a total measure built by adding individual economic units, such as a definition of the money supply","definitionCN":"把单个经济单位相加而构成的总体指标，例如对货币供应量的某种界定","example":"The M2 aggregation combines currency, demand deposits, and small time deposits.","exampleCN":"M2 这一总量指标把通货、活期存款和小额定期存款合并在一起。","why":"Economics must speak of millions of households at once, so it aggregates them into one number. The technical noun names one defined total, such as M2, and its plural names the several totals that are defined.","whyCN":"经济学必须一次性谈论数百万家庭，于是把他们聚合成一个数字。这个技术性名词命名一个被定义的总量（如 M2），其复数则命名被定义出来的若干总量。"},{"no":"09","title":"Clumping of soil or mineral particles","titleCN":"土壤或矿物颗粒的团聚","definition":"the binding of fine soil or mineral particles into larger clumps","definitionCN":"细小的土壤或矿物颗粒结合成较大的团粒","example":"Organic matter improves soil structure by promoting aggregation of clay particles.","exampleCN":"有机质促进黏土颗粒团聚，从而改善土壤结构。","why":"At the smallest scale the flock is a cloud of particles. The same gathering produces a clump you can hold, so the word moves from counting to physical structure.","whyCN":"在最小尺度上，羊群是一团颗粒。同一种聚拢产生了可以拿在手里的团粒，于是这个词从“计数”走到了“物理结构”。"}],"etymology":{"intro":{"en":"Aggregation is not a fresh English coinage: it came whole from Medieval Latin aggregatio, the action noun of aggregare. The chain is aggregare 'drive to a flock' → aggregatio 'a driving to a flock' → English aggregation. The suffix -ation (< Latin -ationem) names an action and, by metonymy, its result, which is why the word can mean both 'the gathering' and 'the thing gathered'.","cn":"aggregation 不是英语后来新造的词：它整体来自中世纪拉丁语 aggregatio，即 aggregare 的动作名词。链条是 aggregare“赶成一群”→ aggregatio“赶成一群这件事”→ 英语 aggregation。后缀 -ation（< 拉丁 -ationem）命名动作，并由转喻兼指结果，所以这个词既能指“聚集”这件事，也能指“被聚起来的东西”。"},"items":[{"era":"early 15c","en":"First recorded in English as aggregacioun, in medicine (Chauliac), meaning 'formation of a pustule'. The technical medical use is therefore the oldest, not a modern borrowing.","cn":"英语最早记录为 aggregacioun，出现在医学著作（肖利亚克）中，意为“脓疱的形成”。因此医学技术义是最古老的，而不是现代才借入的。"},{"era":"MEDIEVAL LATIN","en":"From Medieval Latin aggregationem (nominative aggregatio), a noun of action from the past-participle stem of Latin aggregare 'collect, bring together'.","cn":"来自中世纪拉丁语 aggregationem（主格 aggregatio），是由拉丁语 aggregare“收集、聚拢”的过去分词词干构成的动作名词。"},{"era":"LATIN","en":"Aggregare is ad- 'to' + gregare 'collect into a flock', from grex (genitive gregis) 'flock'. The -ation element is the Latin -ationem, the same action-noun suffix seen in congregation and segregation.","cn":"aggregare 是 ad-“向”+ gregare“赶成一群”，后者出自 grex（属格 gregis）“群”。-ation 成分就是拉丁语 -ationem，与 congregation、segregation 中看到的动作名词后缀相同。"},{"era":"1540s–1560s","en":"The sense 'a combined whole' is recorded from the 1540s, and 'the act of collecting in an unorganized mass' from the 1560s. English thus records the product sense before the general process sense.","cn":"“合并成的整体”义记录于 16 世纪 40 年代，“无组织地收集成一堆的动作”义记录于 16 世纪 60 年代。也就是说，英语先记录了产物义，后记录了一般过程义。"},{"era":"19c–20c","en":"Technical compounds multiply: platelet aggregation in medicine, aggregation in statistics and economics, news aggregation and link aggregation in computing, soil aggregation in agronomy.","cn":"技术复合词大量增加：医学的血小板凝集、统计与经济学的加总、计算机的新闻聚合与链路聚合、农学的土壤团聚。"},{"era":"LOOK-ALIKE, DIFFERENT PREFIX","en":"Congregation and segregation share the grex root but not the prefix: con- means 'together', se- means 'apart', while ag- is ad- 'to'. Aggravation looks close because of ag- and -ation, but its root is gravis 'heavy'. An identical suffix never guarantees an identical root.","cn":"congregation 与 segregation 共享 grex 词根但前缀不同：con- 意为“一起”，se- 意为“分开”，而 ag- 是 ad-“向”。aggravation 因为 ag- 和 -ation 看起来很近，但它的词根是 gravis“重”。后缀相同绝不等于词根相同。"}]},"similar":{"note":{"en":"The first group separates the base word, the agent noun, a same-root religious noun, and a look-alike from a different root. The second group compares nouns for groups and heaps, each with a different emphasis on selection, time, technical use, or spatial closeness.","cn":"第一组区分基础词、施动者名词、同根的宗教名词，以及另一个词根的形近词。第二组比较表示“群体／堆集”的名词，它们分别在挑选、时间、技术用法、空间紧密度上各有侧重。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"aggregate","ipa":"/ˈæɡrɪɡət/","tag":"base word","definition":"the verb, noun, and adjective from which aggregation is formed. The noun adds -ation and names the process or result; the base names the act or the total.","definitionCN":"aggregation 由它构成的那个动词、名词和形容词。名词加 -ation 后指过程或结果；基础词则指动作或总数。"},{"word":"aggregator","ipa":"/ˈæɡrɪɡeɪtə/","tag":"agent noun","definition":"a person, program, or site that gathers things. The -or marks the doer, while -ation marks the deed.","definitionCN":"收集事物的个人、程序或网站。-or 标记施动者，而 -ation 标记行为。"},{"word":"congregation","ipa":"/ˌkɒŋɡrɪˈɡeɪʃn/","tag":"same flock, con-","definition":"a group assembled, especially for worship. It shares grex, but con- 'together' describes the assembled body rather than the act of driving units to it.","definitionCN":"聚集起来的人群，尤指宗教会众。它共享 grex，但 con-“一起”描述的是聚成的群体，而不是把单位赶向它的动作。"},{"word":"aggravation","ipa":"/ˌæɡrəˈveɪʃn/","tag":"different root","definition":"the act of making something worse or more annoying. It comes from gravis 'heavy'; only the -ation ending and the ag- front match.","definitionCN":"使事情更糟或更烦人的行为。它来自 gravis“重”；与 aggregation 相同的只有 -ation 词尾和 ag- 词头。"}]},{"heading":"NEAR MEANING","entries":[{"word":"collection","ipa":"/kəˈlekʃn/","tag":"selected and kept","definition":"a group of things gathered, often chosen and kept because they are wanted. It implies selection and curation, not just a total.","definitionCN":"收集起来的一组东西，常因需要而被挑选并保存。它含“挑选与整理”的意思，不只是加总。"},{"word":"accumulation","ipa":"/ˌækjuːmjəˈleɪʃn/","tag":"piled up over time","definition":"a mass formed by gradual piling up over time. It stresses duration and quantity, not the grouping of units into one body.","definitionCN":"随着时间逐渐堆积形成的量。它强调持续与数量，而不是把单位聚成一个整体。"},{"word":"assemblage","ipa":"/əˈsemblɑːʒ/","tag":"technical set","definition":"a set of things or people considered together, used in art, archaeology, and ecology. It is formal and usually implies a deliberately defined set for analysis.","definitionCN":"被放在一起考虑的一组物或人，用于艺术、考古与生态学。它较正式，通常暗示为分析而刻意界定的一组。"},{"word":"cluster","ipa":"/ˈklʌstə/","tag":"close together","definition":"a small group of similar things positioned close together. It stresses spatial proximity and usually fewer, tighter units than an aggregation.","definitionCN":"位置靠近的一小组相似事物。它强调空间邻近，通常比 aggregation 包含更少、更紧密的单位。"}]}]},"mnemonics":{"normalIntro":{"en":"Real pieces: aggregate plus -ation, the grex family, the three prefixes that change the direction of gathering, the medical first use, and the modern technical compounds.","cn":"真实成分：aggregate 加 -ation、grex 词族、改变聚拢方向的三个前缀、最早的医学用法，以及现代技术复合词。"},"normal":[{"en":"-ation turns the verb aggregate into a noun for the process and, by metonymy, for the result — gathering and the gathered body.","cn":"-ation 把动词 aggregate 变成名词，既指过程，又通过转喻指结果——聚集这件事和被聚成的东西。"},{"en":"The grex family points in three directions: ad- 'to' gathers into a flock, con- 'together' assembles a crowd, se- 'apart' separates from the flock.","cn":"grex 词族指向三个方向：ad-“向”赶进群，con-“一起”聚成众，se-“分开”离群。"},{"en":"The oldest English record is medical: a pustule forming. Platelet aggregation is the same image at the scale of cells.","cn":"英语最早的记录是医学的：脓疱形成。血小板凝集就是同一意象在细胞尺度上的重演。"},{"en":"Modern compounds show the range: data aggregation, news aggregation, monetary aggregation, soil aggregation.","cn":"现代复合词展示了范围：数据汇总、新闻聚合、货币总量、土壤团聚。"},{"en":"Aggravation is not a relative: its root is gravis 'heavy'. Only the suffix and the assimilated prefix coincide.","cn":"aggravation 不是亲戚：它的词根是 gravis“重”。相同的只有后缀和同化后的前缀。"}],"abstract":[{"en":"Boxes scattered on a warehouse floor are stacked into one bay; the stacking and the stack share a name.","cn":"散在仓库地上的箱子被码进同一个货位；码的动作和码好的那一堆共用一个名字。"},{"en":"A crowd at a shrine, cells at a wound, pages pulled into one feed: the same gate, three different scales.","cn":"神庙前的人群、伤口处的细胞、被拉进同一个信息流的页面：同一道门，三种不同尺度。"},{"en":"If the boxes are thrown rather than stacked, the result is still an aggregation — but the word then means a heap without order.","cn":"如果箱子是扔进去而不是码好的，结果仍是一个 aggregation——但此时这个词指没有秩序的一堆。"}]},"examples":[{"en":"The report is an aggregation of data from twelve regional offices.","cn":"这份报告汇总了十二个地区办事处的数据。"},{"en":"Platelet aggregation is one of the first steps in blood clotting.","cn":"血小板凝集是血液凝固的最初步骤之一。"},{"en":"An aggregation of seabirds formed around the trawler.","cn":"一群海鸟在拖网渔船周围聚集起来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿格瑞给神」——阿格瑞把散落的供品“给”拢到神前，堆成一堆 → aggregation 聚集；集合体（只借音，不表词源）","word":"aggregation"},"root":"由 aggregate 加 -ation 构成：aggregate 出自拉丁 aggregare（ad-「向」+ gregare「赶成一群」，源于 grex「群」），-ation 出自拉丁 -ationem，是动作名词后缀；核心是「聚拢的动作，以及聚拢后的那一堆」。与 congregation（con-「一起」）、segregation（se-「分开」）同根不同前缀。","sensesIntro":{"en":"Nine senses of aggregation all name the same event at different moments: the driving in, the pen now full, the heap left unsorted, or the same clumping seen in blood, birds, databases, money, and soil. The suffix lets the word denote both the deed and its product.","cn":"aggregation 的九个义项都在命名同一件事的不同时刻：赶进去的过程、装满的圈、没整理的一堆，或同一聚结在血液、鸟群、数据库、货币与土壤中的重演。后缀让这个词同时指行为与产物。"},"semanticMap":{"core":{"en":"CORE IMAGE: separate units pass through one gate and remain together as a body.","cn":"核心意象：分开的单位通过同一道门，之后作为一个整体留在一起。"},"chain":["MANY SCATTERED UNITS","BROUGHT THROUGH ONE GATE","THE ACT NAMED BY -ATION","THE PEN NOW FULL","THE SAME SHAPE AT OTHER SCALES","PROCESS AND PRODUCT IN ONE WORD"],"branches":[{"senses":"01 · 02","en":"THE GENERAL PAIR: one sense names the work of gathering, the other names the body that stands gathered afterwards.","cn":"一般性的一对：一个义项命名聚拢的劳作，另一个命名聚拢后立在那里的整体。"},{"senses":"03","en":"WITHOUT ORDER: when nothing sorts the units, the same word shifts from 'gathered' to 'heaped at random'.","cn":"没有秩序：当没有东西整理单位时，同一个词从“被聚拢”滑向“被胡乱堆着”。"},{"senses":"04 · 05","en":"LIVING BODIES: platelets clump at a wound and birds gather at a trawler; the flock image is applied to cells and to temporary animal crowds.","cn":"活体：血小板在伤口处聚结，鸟群在渔船边聚集；羊群意象被用到细胞和临时动物群上。"},{"senses":"06 · 08","en":"NUMBERS: records are combined into a queryable total, and whole economies are reduced to monetary aggregates.","cn":"数字：记录被合并成可查询的总数，整个经济被压缩成货币总量指标。"},{"senses":"07 · 09","en":"THE SMALLEST AND LARGEST SCALES: software gathers pages into a feed, while clay particles bind into clumps in the soil.","cn":"最小与最大的尺度：软件把页面聚成信息流，黏土颗粒则在土壤中结成团粒。"}]},"affixes":{"intro":{"en":"Aggregation is a textbook -ation noun: a Latin action noun borrowed whole, then used in English for both the process and the product. Its base is aggregate, whose Latin core is ad- 'to' + greg- 'flock'; every related form in English keeps that flock somewhere in its history.","cn":"aggregation 是典型的 -ation 名词：整体借入的拉丁动作名词，在英语里同时指过程与产物。它的基础词是 aggregate，拉丁内核为 ad-“向”+ greg-“群”；英语中每一个相关形式都在某处保留着这个“群”。"},"latinIntro":{"en":"The Latin layer is aggregare 'bring to a flock', gregare 'gather into a flock', grex 'flock', and the action suffix -atio (-ationem). The suffix is shared with congregation and segregation, which use the same grex with different prefixes.","cn":"拉丁层包括 aggregare“聚到群里”、gregare“赶成一群”、grex“群”，以及动作名词后缀 -atio（-ationem）。这个后缀与 congregation、segregation 共用，后两者用同一个 grex 配不同前缀。"},"items":[{"word":"aggregation","structure":"aggregate + -ation (Latin -ationem, action noun)","meaning":"the act or result of gathering into a whole","meaningCN":"聚集成整体的动作或结果（-ation 动作名词后缀）","example":"The aggregation of the census returns took months.","exampleCN":"人口普查表的汇总花了几个月。"},{"word":"aggregate","structure":"ad- (to) + greg- (flock) + -ate","meaning":"to gather into one body; the body or total so formed","meaningCN":"聚成一体；聚成的整体或总数（ad- 向 + greg- 群）","example":"The particles aggregate in still water.","exampleCN":"颗粒在静水中聚集。"},{"word":"aggregator","structure":"aggregate + -or (agent noun)","meaning":"one that gathers, especially a feed or site","meaningCN":"聚合者；聚合器（-or 施动者）","example":"The aggregator collects headlines every ten minutes.","exampleCN":"这个聚合器每十分钟收集一次标题。"},{"word":"aggregative","structure":"aggregate + -ive (adjective)","meaning":"having a tendency to gather","meaningCN":"有聚集倾向的（-ive 形容词）","example":"The ants show aggregative behaviour around sugar.","exampleCN":"蚂蚁在糖周围表现出聚集行为。"},{"word":"disaggregation","structure":"dis- (reverse) + aggregation","meaning":"the breaking of a total into its parts","meaningCN":"把总数拆回各部分；分解（dis- 反向 + aggregation）","example":"Disaggregation of the figure revealed wide regional gaps.","exampleCN":"把这个数字拆开之后，暴露出很大的地区差异。"},{"word":"congregation","structure":"con- (together) + greg- (flock) + -ation","meaning":"an assembled crowd, especially for worship","meaningCN":"聚在一起的群体，尤指宗教会众（con- 一起 + greg- 群）","example":"The congregation filled the old church by seven.","exampleCN":"七点前会众就坐满了那座老教堂。"},{"word":"segregation","structure":"se- (apart) + greg- (flock) + -ation","meaning":"the separation of one group from the rest","meaningCN":"把某群体与其余分开；隔离（se- 分开 + greg- 群）","example":"Segregation of the two waste streams cut disposal costs.","exampleCN":"把两股废物流分开，降低了处置成本。"},{"word":"gregarious","structure":"greg- (flock) + -ous (given to)","meaning":"fond of company, living in groups","meaningCN":"群居的；爱交际的（greg- 群 + -ous）","example":"Sheep are gregarious and panic when isolated.","exampleCN":"羊是群居动物，被隔离时会惊慌。"},{"word":"egregious","structure":"e- (out of) + greg- (flock) + -ious","meaning":"standing out from the flock, hence shockingly bad","meaningCN":"从群中突出，因而指极其糟糕（e- 出 + greg- 群）","example":"The omission was egregious, not merely careless.","exampleCN":"这个遗漏是极其严重的，不只是粗心。"},{"word":"grex","structure":"Latin noun, genitive gregis","meaning":"flock, herd","meaningCN":"群；畜群","example":"Latin grex gives English both aggregate and egregious.","exampleCN":"拉丁语 grex 给了英语 aggregate 和 egregious。"}],"latinEntries":[{"word":"aggregatio","structure":"aggregare + -tio (action noun)","meaning":"a bringing together, a collecting","meaningCN":"聚拢；收集（动作名词）"},{"word":"aggregare","structure":"ad- (to) + gregare (gather into a flock)","meaning":"to bring to a flock, collect","meaningCN":"赶到群里；收集"},{"word":"grex","structure":"Latin noun, genitive gregis","meaning":"flock, herd","meaningCN":"群；畜群"}]}},{"word":"agricultural","ipa_uk":"/ˌæɡrɪˈkʌltʃərəl/","ipa_us":"/ˌæɡrɪˈkʌltʃərəl/","definition_zh":"农业的；农用的；农耕的；农学的；农村经济的","definition_en":"relating to agriculture, to the cultivation of land and the raising of crops and livestock, or to the industries, policies, and sciences built around it","core_image":"一块被犁开的田地向四周铺开，所有与它有关的人、机器、政策和论文都围着这块田转","scene":"农学院的试验田里，学生给不同品种的小麦挂牌、量株高。In the test field, students label different wheat varieties and measure their height as part of an agricultural study.","sceneCN":"这里 agricultural 是「农学的、农业科研的」（第 8 个义项：农业科学与研究）；句意：在试验田里，学生给不同品种的小麦挂牌、量株高，这是一项农业研究。场景要点：试验田、划分的小区、品种标牌、卷尺、记录本、取土钻。","pos":[{"tag":"adj.","zh":"农业的；农用的；农耕的；农学的"}],"collocations":[{"phrase":"agricultural land","zh":"农用地；耕地"},{"phrase":"agricultural produce","zh":"农产品"},{"phrase":"agricultural policy","zh":"农业政策"},{"phrase":"agricultural machinery","zh":"农业机械"},{"phrase":"agricultural labour","zh":"农业劳动力"},{"phrase":"agricultural runoff","zh":"农业径流；农田退水"},{"phrase":"agricultural science","zh":"农业科学；农学"}],"forms":[{"label":"比较级（更农业化的）","form":"more agricultural"}],"derivatives":[{"word":"agriculturally","pos":"adv.","zh":"在农业方面；从农业角度"},{"word":"agriculturalist","pos":"n.","zh":"农学家；农业经营者"},{"word":"non-agricultural","pos":"adj.","zh":"非农业的"},{"word":"agriculture","pos":"n.","zh":"农业；农学；农艺"}],"senses":[{"no":"01","title":"Of farming as work","titleCN":"农业劳动的","definition":"relating to the work of cultivating land and raising crops or livestock","definitionCN":"与耕种土地、种植作物或饲养牲畜的劳动有关","example":"Agricultural workers in the valley earn less than half the county average.","exampleCN":"这个山谷里的农业工人收入不到全县平均水平的一半。","why":"-al turns the noun agriculture into a bare relational adjective: it adds no content, only the frame 'pertaining to'. The first domain it covers is the people who do the work.","whyCN":"-al 把名词 agriculture 变成纯关系形容词：它不添加内容，只加“与……有关”的框架。它覆盖的第一个领域就是做这份劳动的人。"},{"no":"02","title":"Of land that is farmed","titleCN":"农用的土地","definition":"relating to land used for crops or pasture rather than for building","definitionCN":"与用于种作物或放牧、而非用于建筑的土地有关","example":"The county protects agricultural land from subdivision.","exampleCN":"该县保护农用地，不让它被分割成宅地。","why":"Land is the object agriculture acts on. An agricultural field is not a field that farms; it is a field marked by the purpose farming gives it.","whyCN":"土地是农业作用的对象。an agricultural field 不是“会种地的田”，而是被农业赋予用途、因而带上标记的田。"},{"no":"03","title":"Of farm produce","titleCN":"农产的","definition":"relating to crops, livestock, and raw products that come from farms","definitionCN":"与来自农场的作物、牲畜及初级产品有关","example":"Agricultural exports rose after the grain tariff was lifted.","exampleCN":"粮食关税取消后，农产品出口上升。","why":"The adjective moves from the work to what the work yields. Produce is agricultural because it leaves the field, not because it stays in it.","whyCN":"形容词从“劳动”移到了“劳动产出”。产品之所以是 agricultural，是因为它从田里出来，而不是因为它留在田里。"},{"no":"04","title":"Of an economy based on farming","titleCN":"以农业为经济基础的","definition":"relating to an economy, society, or region whose wealth comes mainly from farming","definitionCN":"与财富主要来自农业的经济体、社会或地区有关","example":"The country shifted from an agricultural economy to one built on light industry.","exampleCN":"这个国家从农业经济转向以轻工业为基础的经济。","why":"When a whole economy is described, farming becomes its base rather than one activity inside it. The relational suffix now points to a structural share of output and employment.","whyCN":"当描述整个经济体时，农业成了它的基础，而不只是其中的一项活动。关系后缀此时指向产出与就业中的结构性份额。"},{"no":"05","title":"Of government policy and support","titleCN":"农业政策的","definition":"relating to state policy, subsidies, and regulation concerning farming","definitionCN":"与国家针对农业的政策、补贴和监管有关","example":"Agricultural subsidies account for a third of the ministry's budget.","exampleCN":"农业补贴占该部预算的三分之一。","why":"Modern states treat farming as a sector to be governed. The adjective attaches to the institutions that steer it, so it no longer describes soil or crops but budgets and rules.","whyCN":"现代国家把农业当作需要治理的部门。形容词附着在操纵它的机构上，于是它描述的不再是土壤或作物，而是预算与规则。"},{"no":"06","title":"Of machinery and inputs","titleCN":"农用机械与投入品的","definition":"relating to machines, tools, and chemicals used in farming","definitionCN":"与农业中使用的机械、工具和化学品有关","example":"Agricultural machinery has grown heavier, and with it soil compaction.","exampleCN":"农业机械越来越重，土壤压实也随之加重。","why":"Inputs are agricultural by destination: a tractor is not a farm, but its whole working life is spent inside farming. The adjective labels function, not ownership.","whyCN":"投入品是因“去向”而成为 agricultural 的：拖拉机本身不是农场，但它整个工作寿命都在农业内部度过。形容词标记的是功能，而不是所有权。"},{"no":"07","title":"Of the farming calendar","titleCN":"农时的","definition":"relating to the seasonal cycle of ploughing, sowing, and harvesting","definitionCN":"与犁地、播种、收获的季节周期有关","example":"The irrigation schedule follows the agricultural calendar, not the fiscal year.","exampleCN":"灌溉安排遵循农时，而不是财政年度。","why":"Farming is bound to seasons. The adjective can mark time itself, because the year in a farming district is divided by tasks rather than by months.","whyCN":"农业受季节约束。这个形容词可以标记时间本身，因为在农业区，一年是按农活而不是按月份划分的。"},{"no":"08","title":"Of the science of farming","titleCN":"农学的","definition":"relating to the scientific study, teaching, or extension of farming","definitionCN":"与农业的科学研究、教学或推广有关","example":"The agricultural station tests new wheat varieties against local rust strains.","exampleCN":"农业试验站用当地锈病小种来测试新的小麦品种。","why":"Once farming is studied, it acquires a discipline. The adjective then describes research and teaching, the places where agriculture is examined rather than practised.","whyCN":"农业一旦被研究，就获得了一门学科。形容词于是描述研究与教学，也就是“被考察”而非“被实践”的农业所在的场所。"},{"no":"09","title":"Of farming's environmental effects","titleCN":"农业环境影响的","definition":"relating to the environmental impact of farming, especially runoff and pollution","definitionCN":"与农业的环境影响有关，尤指径流与污染","example":"Agricultural runoff is the largest source of nitrogen in the bay.","exampleCN":"农业径流是该海湾最大的氮来源。","why":"The effects leave the farm with water and air. The adjective follows them downstream, describing what farming does to places that are not farms at all.","whyCN":"影响随水和空气离开农场。形容词跟着它们向下游走，描述农业对那些根本不是农场的地方做了什么。"}],"etymology":{"intro":{"en":"Agricultural is a transparent derivative, but a late one: it is agriculture + -al, first recorded in 1766. The chain behind it is ager 'field' + cultura 'cultivation' → agricultura → agriculture → agricultural. The suffix adds nothing but the relation 'pertaining to', so all nine senses are simply the domains that agriculture touches. It is not related to agrarian as a word, although both descend from ager by different routes.","cn":"agricultural 是一个透明的派生词，但出现得很晚：它是 agriculture 加 -al，最早记录于 1766 年。背后的链条是 ager“田地”+ cultura“耕作”→ agricultura → agriculture → agricultural。后缀除了“与……有关”之外不添加任何意义，所以九个义项只是农业所触及的不同领域。它与 agrarian 并非同一个词，尽管两者经由不同路径都出自 ager。"},"items":[{"era":"1766","en":"First recorded as 'of or pertaining to, or engaged in, agriculture', formed in English from agriculture + -al (1). Agriculturally and agriculturalist follow as regular derivatives.","cn":"最早记录为“与农业有关的，或从事农业的”，由英语内部用 agriculture 加 -al（第 1 类）构成。agriculturally 与 agriculturalist 作为规则派生词随后出现。"},{"era":"mid-15c","en":"Agriculture itself is recorded from the mid-15th century meaning 'tillage, cultivation of large areas of land to provide food'. Its original use in English was figurative, of God.","cn":"agriculture 本身记录于 15 世纪中期，意为“耕种、为供给食物而耕作大片土地”。它在英语中的最初用法是比喻性的，用于上帝。"},{"era":"LATE LATIN","en":"From Late Latin agricultura 'cultivation of the land', a contraction of agri cultura, literally 'cultivation of a field'. Latin could express the same idea with two separate words before they fused.","cn":"来自晚期拉丁语 agricultura“耕种土地”，是 agri cultura 的缩合形式，字面为“田地的耕作”。在融合成一个词之前，拉丁语本可以用两个分开的词表达同一意思。"},{"era":"LATIN","en":"Agri is the genitive of ager 'field', from PIE *agro- 'field'. Cultura 'cultivation' comes from colere 'to till, cultivate, inhabit', the verb also behind culture, whose sense widened from tending land to tending mind.","cn":"agri 是 ager“田地”的属格，出自原始印欧语 *agro-“田地”。cultura“耕作”来自 colere“耕种、栽培、居住”，这个动词也是 culture 的来源，其词义从照料土地扩展到了照料心智。"},{"era":"LATIN / ENGLISH","en":"The same ager gives agrarian through Latin agrarius: agrarian is recorded from the 1610s as 'relating to the land', with 'cultivated land' by 1792. Agrarian concerns land and its ownership; agricultural concerns the practice and industry of farming.","cn":"同一个 ager 经由拉丁语 agrarius 给出 agrarian：agrarian 于 17 世纪 10 年代记录为“与土地有关的”，1792 年出现“耕地”义。agrarian 关注土地及其所有权；agricultural 关注耕作的实践与产业。"},{"era":"-AL / MODERN ENGLISH","en":"-al comes from Latin -alis 'of, like, related to', entering English through French or directly. It converts a noun into a relational adjective without adding a new idea, so agricultural never means 'more farming' or 'like a farm' by itself; the context supplies which part of farming is meant.","cn":"-al 来自拉丁语 -alis“属于、像、与……有关”，经法语或直接进入英语。它把名词转成关系形容词，不添加新概念，所以 agricultural 本身从不表示“更农业”或“像农场”；是哪一部分农业，由语境提供。"}]},"similar":{"note":{"en":"The first group contains the base noun, the same-root land word with a different suffix, the adverb, and a different branch of cultivation. The second group compares adjectives for farming, countryside, ploughable land, and grazing, which overlap in use but not in meaning.","cn":"第一组包括基础名词、同根但后缀不同的土地词、副词，以及“耕作”的另一支。第二组比较农业、乡村、可耕地、放牧四类形容词，它们用法有重叠，意义并不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"agriculture","ipa":"/ˈæɡrɪkʌltʃə/","tag":"base noun","definition":"the practice or science of farming. It names the activity itself, while agricultural only says 'relating to it'.","definitionCN":"农耕的实践或科学。它命名活动本身，而 agricultural 只表示“与之有关”。"},{"word":"agrarian","ipa":"/əˈɡreəriən/","tag":"same ager, different suffix","definition":"relating to land, especially its ownership and distribution. It comes from Latin agrarius, also from ager, but it is about land as property, not about farming as an industry.","definitionCN":"与土地有关，尤指土地所有权与分配。它来自拉丁语 agrarius，同样出自 ager，但讲的是作为财产的土地，而不是作为产业的农业。"},{"word":"agriculturally","ipa":"/ˌæɡrɪˈkʌltʃərəli/","tag":"derived adverb","definition":"in an agricultural way, or from the point of view of agriculture. The -ly marks manner or viewpoint, not a new sense.","definitionCN":"以农业的方式，或从农业角度看。-ly 标记方式或视角，不产生新义。"},{"word":"horticultural","ipa":"/ˌhɔːtɪˈkʌltʃərəl/","tag":"garden, not field","definition":"relating to the cultivation of gardens, orchards, and ornamental plants. It shares cultura but its first element is hortus 'garden', not ager 'field'.","definitionCN":"与花园、果园和观赏植物的栽培有关。它共享 cultura，但第一个成分是 hortus“花园”，不是 ager“田地”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"farming","ipa":"/ˈfɑːmɪŋ/","tag":"plain activity","definition":"the activity of growing crops or raising animals, used in everyday speech. Agricultural is its formal adjective, at home in policy, economics, and science.","definitionCN":"种植作物或饲养动物的活动，用于日常口语。agricultural 是它的正式形容词，常见于政策、经济与科学语境。"},{"word":"rural","ipa":"/ˈrʊərəl/","tag":"countryside","definition":"relating to the countryside and its population. A rural road or school has nothing to do with crops; the word is about where people live, not what they grow.","definitionCN":"与乡村及其人口有关。一条 rural road 或一所 rural school 与作物无关；这个词讲人住在哪里，而不是种什么。"},{"word":"arable","ipa":"/ˈærəbl/","tag":"ploughable land","definition":"of land, suitable for ploughing and growing crops. It excludes pasture, orchards, and land used only for livestock, so it is narrower than agricultural land.","definitionCN":"指土地可犁、可种作物。它排除牧场、果园和只用于放牧的土地，因此比 agricultural land 窄。"},{"word":"pastoral","ipa":"/ˈpɑːstərəl/","tag":"grazing and idyll","definition":"relating to sheep and cattle grazing, or to an idealized country life in literature. It is about herds and shepherds, not about crops or farm policy.","definitionCN":"与牛羊放牧有关，或在文学中指理想化的乡村生活。它讲的是畜群与牧人，不是作物或农业政策。"}]}]},"mnemonics":{"normalIntro":{"en":"Real pieces: ager 'field' + cultura 'cultivation', the -al that only means 'pertaining to', the agrarian branch from the same ager, and seven collocations that each fix one domain.","cn":"真实成分：ager“田地”+ cultura“耕作”、只表示“与……有关”的 -al、同出 ager 的 agrarian 分支，以及七条各自锁定一个领域的搭配。"},"normal":[{"en":"ager is 'field' and cultura is 'cultivation': agriculture is literally field-tending, and agricultural adds only 'relating to'.","cn":"ager 是“田地”，cultura 是“耕作”：agriculture 字面上就是照料田地，agricultural 只再加上“与……有关”。"},{"en":"-al adds no new idea. Whatever part of farming the noun in front of you names is the part agricultural points to.","cn":"-al 不添加新概念。你面前那个名词指的是农业的哪一部分，agricultural 就指向哪一部分。"},{"en":"The same ager gives agrarian through agrarius: agrarian is about land and ownership, agricultural about farming as a practice and industry.","cn":"同一个 ager 经由 agrarius 给出 agrarian：agrarian 讲土地与所有权，agricultural 讲作为实践与产业的农业。"},{"en":"Collocations mark the domains: agricultural land, produce, policy, machinery, labour, runoff, science.","cn":"搭配标记领域：农用地、农产品、农业政策、农业机械、农业劳动力、农业径流、农业科学。"},{"en":"Agriculture first appears in English in a figurative use of God; the modern farming sense is attested from about 1600.","cn":"agriculture 在英语中最早以比喻方式用于上帝；现代“耕作农业”义约在 1600 年得到确认。"}],"abstract":[{"en":"A ploughed field is the centre; people, tractors, subsidies, and research stations are drawn around it like lines of force.","cn":"一块犁过的田是中心；人、拖拉机、补贴和试验站像磁力线一样围绕它排开。"},{"en":"The suffix is a spotlight, not a paintbrush: it does not colour the noun, it only points at it from the angle of agriculture.","cn":"这个后缀是聚光灯，不是画笔：它不给名词上色，只是从农业的角度指向它。"},{"en":"Water leaving a field carries the field's chemistry with it; the adjective follows the water downstream.","cn":"离开田地的水带走了田里的化学物质；这个形容词就跟着水走到下游。"}]},"examples":[{"en":"Agricultural land in the delta is losing topsoil faster than it forms.","cn":"三角洲的农用地流失表土的速度快于表土形成。"},{"en":"The ministry cut agricultural subsidies for the largest farms.","cn":"该部削减了对最大农场的农业补贴。"},{"en":"Nitrogen from agricultural runoff feeds algal blooms far offshore.","cn":"农业径流带来的氮养活了远海的水华。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿格瑞靠它」——阿格瑞一家靠它吃饭：种地、养猪、卖粮，全是 agricultural 农业的（只借音，不表词源）","word":"agricultural"},"root":"拉丁 agricultura「耕种土地」，由 agri（ager「田地」的属格）+ cultura「耕作」构成，再加形容词后缀 -al「与……有关的」；核心是「与田地耕作有关」。同出 ager 的 agrarian 走 agrarius 另一条路，二者不是同一个词。","sensesIntro":{"en":"Nine senses of agricultural are not nine meanings in the dictionary sense; they are the domains the single relation 'pertaining to agriculture' can point at — the workers, the land, the produce, the economy, the policy, the machines, the calendar, the science, and the pollution that leaves the farm.","cn":"agricultural 的九个义项并非九个独立词典义，而是“与农业有关”这一关系所能指向的领域——劳动者、土地、农产品、经济、政策、机械、农时、农学，以及离开农场的污染。"},"semanticMap":{"core":{"en":"CORE IMAGE: one ploughed field at the centre, with everything agriculture touches arranged around it.","cn":"核心意象：一块犁过的田在中央，农业所触及的一切围绕它排开。"},"chain":["AGER, A FIELD","CULTURA, TENDING IT","AGRICULTURA, FIELD-TENDING","AGRICULTURE, THE PRACTICE","-AL, PERTAINING TO","NINE DOMAINS AROUND THE FIELD"],"branches":[{"senses":"01 · 02","en":"WORK AND GROUND: the people who do the labour and the land that receives it are the first things the relation points at.","cn":"劳动与土地：做这份劳动的人，以及承接劳动的地，是这一关系最先指向的东西。"},{"senses":"03 · 04","en":"OUTPUT AND STRUCTURE: what leaves the farm as produce, and what an entire economy owes to farming.","cn":"产出与结构：作为农产品离开农场的东西，以及整个经济体欠农业的那一份。"},{"senses":"05 · 06","en":"STEERING AND INPUTS: the state that governs farming from above, and the machines and chemicals that enter it from outside.","cn":"操控与投入：从上方治理农业的国家，以及从外部进入农业的机械与化学品。"},{"senses":"07","en":"TIME: the farming year, divided by ploughing, sowing, and harvest rather than by the calendar of offices.","cn":"时间：农事年，按犁地、播种、收获来划分，而不是按机关的日历划分。"},{"senses":"08 · 09","en":"KNOWLEDGE AND CONSEQUENCE: the science that studies farming, and the runoff that carries its effects beyond the farm.","cn":"知识与后果：研究农业的科学，以及把农业影响带出农场之外的径流。"}]},"affixes":{"intro":{"en":"Agricultural is the clearest case in this batch of a suffix doing only one job: -al changes a noun into a relational adjective and adds nothing else. The interest lies in the base, agriculture, which fuses two Latin words — ager 'field' and cultura 'cultivation' — into one noun.","cn":"agricultural 是本批中最清楚地体现“后缀只做一件事”的词：-al 把名词变成关系形容词，别的什么都不加。有意思的是基础词 agriculture，它把两个拉丁词——ager“田地”和 cultura“耕作”——融合成一个名词。"},"latinIntro":{"en":"The Latin layer is ager 'field', cultura 'cultivation' (from colere 'to till'), their fusion in agricultura, and the adjective suffix -alis. Agrarius, also from ager, gives the separate English word agrarian.","cn":"拉丁层包括 ager“田地”、cultura“耕作”（出自 colere“耕种”）、二者融合成的 agricultura，以及形容词后缀 -alis。同样出自 ager 的 agrarius 则给出另一个英语词 agrarian。"},"items":[{"word":"agricultural","structure":"agriculture + -al (Latin -alis, pertaining to)","meaning":"relating to agriculture","meaningCN":"与农业有关的（-al 关系形容词后缀）","example":"The region's agricultural output doubled in a decade.","exampleCN":"该地区的农业产量十年间翻了一番。"},{"word":"agriculture","structure":"agri- (field) + culture (cultivation)","meaning":"the practice of cultivating land and raising food","meaningCN":"耕种土地、生产食物的实践（agri- 田地 + culture 耕作）","example":"Agriculture employs half the population here.","exampleCN":"农业雇佣了这里一半的人口。"},{"word":"agriculturally","structure":"agricultural + -ly (manner adverb)","meaning":"from an agricultural point of view","meaningCN":"从农业角度；在农业方面（-ly 方式副词）","example":"The valley is agriculturally rich but industrially poor.","exampleCN":"这个山谷农业富庶，工业贫弱。"},{"word":"agriculturalist","structure":"agricultural + -ist (person concerned with)","meaning":"a person who studies or practises agriculture","meaningCN":"研究或从事农业的人；农学家（-ist 从业者）","example":"The agriculturalist advised the cooperative on seed choice.","exampleCN":"这位农学家就选种给合作社提了建议。"},{"word":"agrarian","structure":"Latin agrarius (from ager 'field') + -ian","meaning":"relating to land, especially its ownership","meaningCN":"与土地有关的，尤指土地所有权（同出 ager）","example":"The party's programme was agrarian rather than industrial.","exampleCN":"该党的纲领是土地纲领，而非工业纲领。"},{"word":"agronomy","structure":"Greek agro- (field) + -nomy (management, ordering)","meaning":"the science of crop production and soil management","meaningCN":"农学；作物生产与土壤管理科学（agro- 田地 + -nomy 管理）","example":"Agronomy applies soil chemistry to field practice.","exampleCN":"农学把土壤化学应用到田间实践。"},{"word":"horticulture","structure":"horti- (garden) + culture (cultivation)","meaning":"the cultivation of gardens and ornamental plants","meaningCN":"园艺；花园与观赏植物栽培（horti- 花园 + culture 耕作）","example":"Horticulture began with walled gardens, not open fields.","exampleCN":"园艺始于围起来的园子，而不是开阔的田地。"},{"word":"culture","structure":"Latin cultura (tending, cultivation), from colere","meaning":"the tending of land, and later the tending of mind","meaningCN":"对土地的照料，后来扩展到对心智的培养","example":"The word culture moved from soil to mind.","exampleCN":"culture 这个词从土壤走到了心智。"},{"word":"cultivate","structure":"cultur- (tending) + -ate (verb)","meaning":"to prepare and work land for crops","meaningCN":"耕作；开垦（cultur- 照料 + -ate 动词）","example":"They cultivate rice on terraces cut into the slope.","exampleCN":"他们在坡地上开出的梯田里种稻。"},{"word":"non-agricultural","structure":"non- (not) + agricultural","meaning":"not connected with farming","meaningCN":"非农业的（non- 否定 + agricultural）","example":"Non-agricultural jobs absorbed the surplus labour.","exampleCN":"非农业岗位吸收了剩余劳动力。"}],"latinEntries":[{"word":"agricultura","structure":"agri (of a field) + cultura (cultivation)","meaning":"cultivation of the land","meaningCN":"耕种土地"},{"word":"ager","structure":"Latin noun, genitive agri; PIE *agro- 'field'","meaning":"field, land","meaningCN":"田地；土地"},{"word":"cultura","structure":"from colere 'to till, cultivate, inhabit'","meaning":"tending, cultivation","meaningCN":"照料；耕作"},{"word":"-alis","structure":"Latin adjective suffix","meaning":"of, relating to","meaningCN":"属于……的；与……有关的"}]}},{"word":"alteration","ipa_uk":"/ˌɔːltəˈreɪʃn/","ipa_us":"/ˌɔːltəˈreɪʃən/","definition_zh":"改变；改动；变更；修改；改做（衣服）；蚀变；变音","definition_en":"the act or result of making something different in part, so that it remains recognisable, whether in appearance, structure, text, tissue, rock, or a musical note","core_image":"同一个人换了一件外套：还是他，但轮廓、颜色和旁人的第一眼都变了","scene":"裁缝把大衣的腰线收进去两厘米，肩线因此看起来更挺。The tailor takes in the waist of the coat by two centimetres, and that small alteration makes the shoulder line look sharper.","sceneCN":"这里 alteration 是「衣服改做」（第 3 个义项：按顾客尺寸修改成衣）；句意：裁缝把大衣腰线收进两厘米，这一小小的改做让肩线显得更挺。场景要点：试衣镜、别针、粉笔线、缝纫机、改衣单、挂在架上的大衣。","pos":[{"tag":"n.","zh":"改变；改动；变更；修改；改做"}],"collocations":[{"phrase":"make an alteration","zh":"做一处改动"},{"phrase":"alteration to","zh":"对……的改动"},{"phrase":"structural alteration","zh":"结构改造"},{"phrase":"clothing alterations","zh":"衣服改做"},{"phrase":"alteration in","zh":"在……方面的变化"},{"phrase":"genetic alteration","zh":"基因改变"},{"phrase":"material alteration","zh":"实质性变更（法律）"}],"forms":[{"label":"名词复数","form":"alterations"}],"derivatives":[{"word":"alter","pos":"v.","zh":"改变；改动；修改"},{"word":"altered","pos":"adj.","zh":"改变了的；改动过的"},{"word":"alterable","pos":"adj.","zh":"可改变的；可改动的"},{"word":"inalterable","pos":"adj.","zh":"不可改变的；不可改动的"}],"senses":[{"no":"01","title":"The act of making something different","titleCN":"使某物变得不同的动作","definition":"the act of changing something in some respect without replacing it","definitionCN":"在某个方面改变某物而不替换它的动作","example":"Any alteration to the wiring must be inspected before the power is restored.","exampleCN":"电线的任何改动都必须在恢复供电前接受检查。","why":"Alteration comes from alter, 'the other of two'. The act sets one state beside another and moves the thing toward the second, so the noun names the crossing, not a new creation.","whyCN":"alteration 出自 alter“两者中的另一个”。这个动作把一个状态摆在另一个状态旁边，并让事物朝第二个状态移动，所以名词命名的是“跨越”，而不是“造出新东西”。"},{"no":"02","title":"A change in appearance or character","titleCN":"外貌或性质上的变化","definition":"a change in the character, appearance, or condition of something, recorded from the 1530s","definitionCN":"某物在性质、外貌或状况上的变化，此义记录于 16 世纪 30 年代","example":"Neighbours noticed an alteration in the old house: shutters gone, roof retiled.","exampleCN":"邻居们注意到那座老房子的变化：百叶窗没了，屋顶换了瓦。","why":"The -ation noun also names the result. What is left after the crossing is the thing itself, but now carrying the marks of the other state.","whyCN":"-ation 名词也命名结果。跨越之后留下的仍是那件东西本身，只是带上了另一个状态的痕迹。"},{"no":"03","title":"A garment taken in or let out","titleCN":"衣服的改做","definition":"the work of adjusting a ready-made garment to a customer's measurements, a sense recorded from 1901","definitionCN":"按顾客尺寸调整成衣的活儿，此义记录于 1901 年","example":"The alterations cost almost as much as the jacket itself.","exampleCN":"改衣服的钱几乎和夹克本身一样多。","why":"Clothes are the most intimate thing that can be 'made other' while staying the same object. Tailoring turns the abstract act into a paid service with a plural noun.","whyCN":"衣服是最贴身、又能在保持同一件物品的前提下被“做成另一个样子”的东西。裁缝业把这个抽象动作变成一项收费服务，并常用复数名词。"},{"no":"04","title":"A structural change to a building","titleCN":"建筑的结构改造","definition":"a change to the fabric, layout, or fittings of a building","definitionCN":"对建筑物的结构、布局或固定设施所作的改动","example":"The tenant made structural alterations without the owner's consent.","exampleCN":"租户未经业主同意就做了结构改造。","why":"A building survives small changes; that is exactly what alteration means. Add a wall or move a door and the house is still the same house, but another version of it.","whyCN":"建筑能在小改动后继续存在，这正是 alteration 的意思。加一堵墙或移一扇门，房子仍是同一座房子，但成了它的另一个版本。"},{"no":"05","title":"A change to a text or record","titleCN":"文稿或记录的改动","definition":"a change made to a document, manuscript, or record, often one that matters legally","definitionCN":"对文件、手稿或记录所作的改动，通常指具有法律意义的改动","example":"The clerk found three alterations in the ledger, all in the same hand.","exampleCN":"职员在账本里发现三处改动，笔迹都相同。","why":"Writing fixes a state so it can be compared later. An alteration is visible precisely because the earlier version left a trace, and that trace is what makes the change provable.","whyCN":"书写把某个状态固定下来，以便日后比较。改动之所以可见，正是因为早先的版本留下了痕迹，而这条痕迹让改动可以被证明。"},{"no":"06","title":"A change in cells or body chemistry","titleCN":"细胞或体内化学的改变","definition":"a change in the structure or activity of cells, tissue, or body chemistry","definitionCN":"细胞、组织或体内化学的结构或活动发生变化","example":"Chronic stress produces lasting alterations in how the immune system responds.","exampleCN":"长期压力会使免疫系统的反应方式发生持久改变。","why":"Living tissue is a state that can shift without becoming something else. Medicine uses the word for changes that are measurable but leave the organ identifiable.","whyCN":"活组织是一种可以移动却不会变成他物的状态。医学用这个词指那些可测量、但仍让器官保持可辨识的改变。"},{"no":"07","title":"Rock reworked by heat, water, or pressure","titleCN":"岩石受热、水或压力作用而蚀变","definition":"the chemical or mineral change of rock through heat, water, or pressure","definitionCN":"岩石在热、水或压力作用下发生的化学或矿物变化","example":"Hydrothermal alteration turned the volcanic ash into a soft white clay.","exampleCN":"热液蚀变把火山灰变成了柔软的白黏土。","why":"Geology needs a word for change in place: the rock is not replaced, it is reworked. The original minerals give way to others while the body of rock keeps its shape.","whyCN":"地质学需要一个表示“在原地改变”的词：岩石不是被替换，而是被重新改造。原来的矿物让位给别的矿物，岩体却保持原来的形状。"},{"no":"08","title":"A change that affects legal validity","titleCN":"影响法律效力的变更","definition":"in law, a change to a document or term that is significant enough to affect rights or obligations","definitionCN":"在法律上，对文件或条款作出的、足以影响权利或义务的变更","example":"A material alteration voids the cheque; a smudge does not.","exampleCN":"实质性变更会使支票失效；一点污渍则不会。","why":"Law must separate change that matters from change that does not. Alteration becomes a threshold concept: the same word now measures whether the 'other' state has crossed into a legally different thing.","whyCN":"法律必须把“要紧的改动”和“不要紧的改动”分开。alteration 于是成了一个门槛概念：同一个词现在衡量的是，那“另一个”状态是否已经跨进法律上不同的东西。"},{"no":"09","title":"A chromatic change to a note","titleCN":"乐音的变音","definition":"in music, the raising or lowering of a note away from the prevailing key","definitionCN":"在音乐中把某个音升高或降低，使其偏离当前调性","example":"The passage depends on an alteration of the fourth degree, which lifts the whole phrase.","exampleCN":"这一乐段靠第四级的变音把整句托了起来。","why":"A note stays the same note but is moved to a neighbouring pitch. Music theory picked up the word for exactly that: another version of the same degree, not a new note.","whyCN":"音符仍是同一个音符，只是被移到相邻的音高。音乐理论正是用这个词指这件事：同一音级的另一个版本，而不是一个新音符。"}],"etymology":{"intro":{"en":"Alteration is an action noun built in Latin and borrowed whole: alter 'the other of two' → alterare 'make other, change' → alteratio 'a changing' → English alteration. Its core is not addition but substitution of one state for another. The look-alike altar is a different word altogether, from Latin altare and influenced by altus 'high', not from alter.","cn":"alteration 是拉丁语中构成、整体借入的动作名词：alter“两者中的另一个”→ alterare“使成为另一个、改变”→ alteratio“改变”→ 英语 alteration。它的核心不是添加，而是用一个状态替换另一个。形近词 altar 完全是另一个词，来自拉丁语 altare，并受 altus“高”影响，不出自 alter。"},"items":[{"era":"late 14c","en":"First recorded as alteracioun, 'change, transformation, action of altering', from Old French alteracion (14c.) and directly from Medieval Latin alterationem (nominative alteratio).","cn":"最早记录为 alteracioun，意为“改变、转变、改动的动作”，来自古法语 alteracion（14 世纪），并直接来自中世纪拉丁语 alterationem（主格 alteratio）。"},{"era":"MEDIEVAL LATIN","en":"Alteratio is a noun of action from the past-participle stem of Late Latin alterare 'to change'. The -ation element is Latin -ationem, the same action-noun suffix as in aggregation and congregation.","cn":"alteratio 是由晚期拉丁语 alterare“改变”的过去分词词干构成的动作名词。-ation 成分就是拉丁语 -ationem，与 aggregation、congregation 中的动作名词后缀相同。"},{"era":"LATIN","en":"Alterare comes from Latin alter 'the other (of the two)', reconstructed as PIE *al- 'beyond' plus the comparative suffix -ter, as in other. The root means 'the other one', not 'more'.","cn":"alterare 出自拉丁语 alter“两者中的另一个”，可重构为原始印欧语 *al-“在……之外”加比较级后缀 -ter，如同 other。这个词根的意思是“另一个”，不是“更多”。"},{"era":"PIE","en":"The *al- root also gives alien, alias, altruism and ultimate, and through a variant *an-tero- it gives English other. The comparative shape explains why alter always implies exactly two states to choose between.","cn":"这个 *al- 词根还给出 alien、alias、altruism、ultimate，并经变体 *an-tero- 给出英语 other。比较级形态解释了为什么 alter 总暗示恰好有两个状态可供选择。"},{"era":"1530s / 1901","en":"The sense 'change in character or appearance' is recorded from the 1530s, and 'change in ready-made clothes to suit a customer' from 1901. Legal material alteration and geological alteration develop later as technical thresholds.","cn":"“性质或外貌的变化”义记录于 16 世纪 30 年代，“按顾客要求修改成衣”义记录于 1901 年。法律的 material alteration 与地质的 alteration 后来才作为技术门槛发展出来。"},{"era":"LOOK-ALIKE, DIFFERENT ROOT","en":"Altar comes from Latin altare (perhaps originally 'burnt offerings'), influenced by altus 'high'; it is a place, not a change. Alternation is a real relative, but through alternus 'by turns', and it means taking turns, not becoming different.","cn":"altar 来自拉丁语 altare（也许原指“燔祭”），并受 altus“高”影响；它是一个场所，不是一种改变。alternation 确实是亲戚，但经由 alternus“轮流”，意思是“交替”，不是“变得不同”。"}]},"similar":{"note":{"en":"The first group is built from the traps that surround this word: its own base verb, a near-homophone from another root, and two same-family nouns that mean turning, not changing. The second group compares words for change by how large, deliberate, corrective, or formal the change is.","cn":"第一组围绕这个词的陷阱展开：它自己的基础动词、另一个词根的近音词，以及两个同族但表示“轮换”而非“改变”的名词。第二组按变化的幅度、故意程度、修正性和正式程度比较几个“改变”词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"alter","ipa":"/ˈɔːltə/","tag":"base verb","definition":"to change something in part. It is the verb behind alteration, and it keeps the sense of moving a thing toward its other state.","definitionCN":"部分地改变某物。它是 alteration 背后的动词，保留着“把事物移向它的另一个状态”的意思。"},{"word":"altar","ipa":"/ˈɔːltə/","tag":"different root","definition":"a raised table for sacrifice or worship. It comes from Latin altare, influenced by altus 'high', and has no connection with alter or with change.","definitionCN":"用于献祭或礼拜的高台。它来自拉丁语 altare，并受 altus“高”影响，与 alter 或“改变”毫无关系。"},{"word":"alternation","ipa":"/ˌɔːltəˈneɪʃn/","tag":"same family, different noun","definition":"the process of two things following one another by turns, as night and day. It comes through alternus 'by turns' and means rotation, not transformation.","definitionCN":"两件事依次轮流的过程，如昼夜交替。它经由 alternus“轮流”而来，意思是轮换，而不是转变。"},{"word":"altercation","ipa":"/ˌɔːltəˈkeɪʃn/","tag":"same root, different outcome","definition":"a noisy dispute. It comes from Latin altercari 'to dispute', generally connected with alter 'other': two sides trade words as one 'other' against the other, without changing any object.","definitionCN":"吵闹的争执。它来自拉丁语 altercari“争执”，与 alter“另一个”相关：双方作为彼此的“另一个”交换言辞，并不改变任何对象。"}]},{"heading":"NEAR MEANING","entries":[{"word":"change","ipa":"/tʃeɪndʒ/","tag":"widest word","definition":"the widest term for anything becoming different, including complete replacement. Alteration is narrower: the thing stays identifiable through the change.","definitionCN":"表示任何事物变得不同的最宽泛的词，包括彻底替换。alteration 更窄：事物在改变过程中仍保持可辨识。"},{"word":"modification","ipa":"/ˌmɒdɪfɪˈkeɪʃn/","tag":"deliberate adjustment","definition":"a deliberate, usually small change made to improve or adapt something. It implies a purpose and a design behind the change.","definitionCN":"为改进或适配某物而故意做出的、通常较小的改变。它暗示改动背后有目的与设计。"},{"word":"adjustment","ipa":"/əˈdʒʌstmənt/","tag":"corrective fit","definition":"a small change made so that something fits, aligns, or works properly. It is corrective and often precise, unlike alteration, which can be arbitrary.","definitionCN":"为使某物契合、对齐或正常运转而作的小改动。它具有修正性且常常精确，而 alteration 可以是任意的。"},{"word":"amendment","ipa":"/əˈmendmənt/","tag":"formal textual change","definition":"a formal change to a text, law, or contract, made through a defined procedure. It is institutional, while alteration can be informal or even unauthorized.","definitionCN":"通过既定程序对文本、法律或合同作的正式修改。它是制度性的，而 alteration 可以是非正式的，甚至未经授权的。"}]}]},"mnemonics":{"normalIntro":{"en":"Real pieces: alter 'the other of two', the -ation action noun, the altar trap, the alternation contrast, and the domain collocations that split the technical senses.","cn":"真实成分：alter“两者中的另一个”、-ation 动作名词、altar 陷阱、alternation 对照，以及拆分技术义项的领域搭配。"},"normal":[{"en":"alter means 'the other of two': to alter is to move a thing toward its other state, so alteration is a crossing, not an addition.","cn":"alter 意为“两者中的另一个”：改动就是把事物移向它的另一个状态，所以 alteration 是一次跨越，不是一次添加。"},{"en":"-ation names both the act and its result, which is why alteration can be 'the changing' and 'the changed feature'.","cn":"-ation 同时命名动作和结果，所以 alteration 既可以指“改”这件事，也可以指“被改出来的那处不同”。"},{"en":"The near-homophone altar comes from altare and altus 'high'; a raised table is not a change.","cn":"近音词 altar 来自 altare 与 altus“高”；一张高起的台子不是一种改变。"},{"en":"Alternation is a relative but means taking turns, like night and day; alteration means becoming other, like a renovated house.","cn":"alternation 是亲戚，但意思是轮流，如昼夜；alteration 意思是变成另一个样子，如翻修过的房子。"},{"en":"Collocations mark the domains: structural alteration, clothing alterations, genetic alteration, material alteration.","cn":"搭配标记领域：结构改造、服装改做、基因改变、实质性变更。"}],"abstract":[{"en":"Same person, new coat: the outline and colour change, the identity does not. That is alteration rather than replacement.","cn":"同一个人，换了外套：轮廓与颜色变了，身份没变。这就是 alteration，而不是替换。"},{"en":"A house with a new doorway is still the same address; a house torn down is not. The word lives in that difference.","cn":"加了一道门的房子还是同一个地址；被拆掉的房子就不是了。这个词就活在这个差别里。"},{"en":"Rock heated by hot water keeps its shape and loses its old minerals; change can happen in place, without anything being added.","cn":"被热水加热的岩石保持形状，却失去了旧矿物；改变可以在原地发生，不需要添加任何东西。"}]},"examples":[{"en":"The landlord's consent is required for any alteration to the façade.","cn":"对临街立面作任何改动都需要房东同意。"},{"en":"She spent more on alterations than on the dress.","cn":"她花在改衣服上的钱比买裙子还多。"},{"en":"Hot water circulating through the basalt caused a slow alteration of its minerals.","cn":"循环穿过玄武岩的热水使其矿物发生了缓慢的蚀变。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「奥特」——奥特曼换了另一套装甲，还是同一个英雄，只是样子改了 → alteration 改变；改动（只借音，不表词源）","word":"alteration"},"root":"拉丁 alter「两者中的另一个」→ 晚期拉丁 alterare「使变成另一个样子」→ alteratio「改变」；核心是「变成另一个版本」，不是「往上添加」。与 altar（祭坛，拉丁 altare，受 altus「高」影响）同音形近但不同源。","sensesIntro":{"en":"Nine senses of alteration all describe one thing moving toward its other version while remaining itself. The differences come from what is being changed and how much change is allowed: a coat, a building, a ledger, a cell, a rock, a legal instrument, a note.","cn":"alteration 的九个义项都在描述同一件事：一个东西朝着它的另一个版本移动，同时仍是它自己。差别来自被改的是什么，以及允许改到什么程度：外套、建筑、账本、细胞、岩石、法律文书、音符。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same thing wearing its other version, still recognisable.","cn":"核心意象：同一个东西换上了它的另一个版本，仍可辨认。"},"chain":["ONE THING, ONE STATE","ALTER, THE OTHER OF TWO","MOVE TOWARD THE OTHER","STILL THE SAME THING","THE CHANGE LEFT VISIBLE","A THRESHOLD IN LAW AND SCIENCE"],"branches":[{"senses":"01 · 02","en":"THE GENERAL PAIR: the act of crossing to the other state, and the marks that crossing leaves on the thing.","cn":"一般性的一对：跨向另一个状态的动作，以及这次跨越在事物身上留下的痕迹。"},{"senses":"03 · 04","en":"MADE OBJECTS: a coat let out at the waist and a house with a new doorway both survive as themselves, which is what makes the change an alteration.","cn":"制成品：腰身放大的外套和加了新门的房子都作为自身继续存在，这正是这种改变被称为 alteration 的原因。"},{"senses":"05 · 08","en":"RECORDS AND VALIDITY: an altered ledger leaves a provable trace, and law decides at what point that trace becomes a material alteration.","cn":"记录与效力：被改的账本留下可证明的痕迹，而法律判定这条痕迹到哪一点成为实质性变更。"},{"senses":"06 · 07","en":"NATURAL BODIES: tissue and rock change in place; the organ or the rock body stays identifiable while its chemistry or minerals are reworked.","cn":"自然体：组织与岩石在原地改变；器官或岩体保持可辨识，而其化学或矿物被重新改造。"},{"senses":"09","en":"MUSIC: a note is moved to a neighbouring pitch but remains the same degree, the smallest possible version of the same picture.","cn":"音乐：一个音被移到相邻音高，却仍是同一音级，这是同一画面最小尺度的版本。"}]},"affixes":{"intro":{"en":"Alteration is a Latin action noun borrowed whole, not built in English. The chain alter → alterare → alteratio → -ation shows the suffix doing its normal job, but the interesting part is alter: a comparative word meaning 'the other of two', which is why the noun implies a paired before and after rather than simple addition.","cn":"alteration 是整体借入的拉丁动作名词，不是在英语里造的。链条 alter → alterare → alteratio → -ation 显示后缀在做它常规的工作，但真正有意思的是 alter：一个意为“两者中的另一个”的比较级词，这解释了为什么这个名词暗示成对的“之前／之后”，而不是简单添加。"},"latinIntro":{"en":"The Latin layer is alter 'the other of two', alterare 'to make other, change', and alteratio 'a changing', with the action suffix -atio. The same alter also underlies alternative and alternation, but through different formations and with different modern meanings.","cn":"拉丁层包括 alter“两者中的另一个”、alterare“使成为另一个、改变”、alteratio“改变”，以及动作后缀 -atio。同一个 alter 也是 alternative 与 alternation 的基础，但构词路径不同，现代意义也不同。"},"items":[{"word":"alteration","structure":"alter + -ation (Latin -atio, action noun)","meaning":"the act or result of changing something in part","meaningCN":"部分改变某物的动作或结果（-ation 动作名词）","example":"The alteration to the will was dated and signed.","exampleCN":"遗嘱上的这处改动注明了日期并签了名。"},{"word":"alter","structure":"Latin alter (the other of two), via Old French alterer","meaning":"to change something in part","meaningCN":"部分地改变；改动（经由古法语 alterer）","example":"They altered the design after the first test.","exampleCN":"第一次测试后他们改动了设计。"},{"word":"altered","structure":"alter + -ed (past participle adjective)","meaning":"changed, no longer in the original state","meaningCN":"被改变的；不再处于原状的（-ed 分词形容词）","example":"The altered photograph no longer matched the negative.","exampleCN":"被改过的照片与底片已经对不上了。"},{"word":"alterable","structure":"alter + -able (can be)","meaning":"possible to change","meaningCN":"可改变的（-able 能够）","example":"The schedule is alterable until the deposit is paid.","exampleCN":"在付定金之前，日程是可以改的。"},{"word":"inalterable","structure":"in- (not) + alterable","meaning":"impossible to change","meaningCN":"不可改变的（in- 否定 + alterable）","example":"The treaty's core article is inalterable.","exampleCN":"条约的核心条款不可更改。"},{"word":"alternative","structure":"alternat- (by turns) + -ive (adjective)","meaning":"offering the other of two choices","meaningCN":"提供两者中另一选择的；替代的（同出 alter）","example":"They chose the alternative route through the pass.","exampleCN":"他们选择了翻山的另一条路线。"},{"word":"alternation","structure":"alternate + -ion (action noun)","meaning":"the process of taking turns","meaningCN":"轮流；交替（同族，但不是“改变”）","example":"The alternation of wet and dry seasons drives the cycle.","exampleCN":"干湿季的交替驱动着这个周期。"},{"word":"altar","structure":"Latin altare, influenced by altus (high)","meaning":"a raised table for sacrifice; a different root","meaningCN":"祭坛；高起的献祭台（不同词根，形近陷阱）","example":"A stone altar stood at the east end of the chapel.","exampleCN":"小教堂东端立着一座石祭坛。"},{"word":"altercation","structure":"alterc- (to dispute) + -ation","meaning":"a noisy quarrel","meaningCN":"争吵；口角（同出 alter，但指双方争执）","example":"The altercation began over a parking space.","exampleCN":"这场争吵因一个车位而起。"},{"word":"altruism","structure":"French altruisme, from autrui 'other people', from Latin alteri 'others'","meaning":"concern for the well-being of others","meaningCN":"利他主义；关心他人福祉（经由法语，源自拉丁 alteri“他人”）","example":"Altruism can be described as putting the other first.","exampleCN":"利他主义可以描述为把他人放在前面。"}],"latinEntries":[{"word":"alter","structure":"Latin comparative, PIE *al- 'beyond' + -ter","meaning":"the other of two","meaningCN":"两者中的另一个"},{"word":"alterare","structure":"alter + -are (verb ending)","meaning":"to make other, change","meaningCN":"使成为另一个；改变"},{"word":"alteratio","structure":"alterare + -tio (action noun)","meaning":"a changing, alteration","meaningCN":"改变；变更（动作名词）"}]}},{"word":"alternatively","ipa_uk":"/ɔːlˈtɜːnətɪvli/","ipa_us":"/ɔːlˈtɜːrnətɪvli/","definition_zh":"或者；另一种选择是；作为替代方案；换一种说法；又称","definition_en":"used to introduce another possibility, choice, method, explanation, or name, either instead of or in addition to the one just mentioned","core_image":"路口立着第二块路牌：第一条路还在，但牌子上写着“也可以走这边”","scene":"论文讨论部分，作者先给出一种解释，随后又提出另一种可能的成因。In the discussion section, the author gives one explanation and then says, alternatively, the decline may reflect a change in sampling.","sceneCN":"这里 alternatively 是「另一种解释」（第 4 个义项：学术写作中提出可替代的假设）；句意：在讨论部分，作者先给出一种解释，随后提出另一种解释：这次下降可能反映采样方式的变化。场景要点：双栏论文、讨论段、加粗的转承词、两种并排的假设、页边的审稿批注。","pos":[{"tag":"adv.","zh":"副词：或者；作为另一种选择；替代地"}],"collocations":[{"phrase":"or alternatively","zh":"或者作为替代"},{"phrase":"alternatively known as","zh":"又称；又名"},{"phrase":"alternatively called","zh":"或者称为"},{"phrase":"alternatively one could","zh":"或者也可以……"},{"phrase":"alternatively referred to as","zh":"或被称为"},{"phrase":"alternatively considered","zh":"换一种考虑方式"},{"phrase":"alternatively spelled","zh":"或拼作"}],"forms":[{"label":"副词形态","form":"alternatively（无屈折变化）"}],"derivatives":[{"word":"alternative","pos":"n./adj.","zh":"替代方案；可供选择的；另类的"},{"word":"alternately","pos":"adv.","zh":"交替地；轮流地"},{"word":"alternate","pos":"v./adj.","zh":"轮流；交替的；备用的"},{"word":"alternation","pos":"n.","zh":"交替；轮流"}],"senses":[{"no":"01","title":"Offer a second everyday choice","titleCN":"提出日常的第二种选择","definition":"used at the start of a sentence or clause to introduce another course of action the speaker could take","definitionCN":"用于句首或从句开头，引出说话者可以采取的另一种行动方案","example":"We can drive, or alternatively we can take the night train.","exampleCN":"我们可以开车，或者也可以坐夜车。","why":"Alternative began as 'offering one or the other of two'. The adverb marks the second side of that choice, so its basic job is to hold up the other option.","whyCN":"alternative 最初意为“提供两者中的一个或另一个”。这个副词标记那个选择的第二边，所以它的基本工作就是把另一个选项举出来。"},{"no":"02","title":"Slot a substitute inside a sentence","titleCN":"在句中塞入一个替换项","definition":"used after 'or' to replace a word or phrase just given with a different one","definitionCN":"用在 or 之后，用一个不同的词或短语替换刚给出的那个","example":"Send the signed copy by email or, alternatively, by fax.","exampleCN":"把签好的副本用邮件发来，或者用传真。","why":"In mid-sentence the adverb works on a phrase rather than a whole plan. The 'other' is now a means of doing the same thing, not a different thing to do.","whyCN":"在句子中间，这个副词作用于一个短语，而不是整个计划。此时“另一个”是完成同一件事的手段，而不是另一件事。"},{"no":"03","title":"Name a fallback if the first plan fails","titleCN":"第一种方案失败时的备选","definition":"used to present a plan to be used if the first one cannot be carried out","definitionCN":"用于提出一个在原计划无法执行时启用的方案","example":"If the bridge is closed, alternatively we can go around by the lake road.","exampleCN":"如果桥封了，我们也可以绕湖边的路走。","why":"The two options are ordered by availability, not by preference. The adverb signals that the second waits behind the first, ready if the first drops out.","whyCN":"两个选项按可行性排序，而不是按偏好排序。这个副词表明第二个在第一个之后待命，一旦第一个落空就上场。"},{"no":"04","title":"Introduce a rival hypothesis","titleCN":"引出另一种假设","definition":"used in academic writing to put forward a second explanation that may account for the same evidence","definitionCN":"用于学术写作，提出可能解释同一批证据的第二种解释","example":"Alternatively, the decline may reflect a change in sampling rather than a real loss.","exampleCN":"另一种解释是，这次下降可能反映采样方式的变化，而不是真正的减少。","why":"Research rarely has one candidate cause. The adverb places a second explanation beside the first without claiming it is better, which is why it is so common in discussion sections.","whyCN":"研究很少只有一个候选原因。这个副词把第二种解释放在第一种旁边，并不宣称它更好，所以它在讨论部分极为常见。"},{"no":"05","title":"Introduce a second method","titleCN":"引出第二种方法","definition":"used in instructions to describe another procedure that achieves the same result","definitionCN":"用于操作说明，描述能达到同一结果的另一种程序","example":"Alternatively, the sample can be digested overnight at room temperature.","exampleCN":"或者，样品可以在室温下消化过夜。","why":"A method is a route to a fixed end. The word marks a parallel route, so it appears in protocols where the result matters more than the procedure.","whyCN":"方法是一条通往固定终点的路线。这个词标记一条平行路线，所以它出现在“结果比程序更重要”的实验方案里。"},{"no":"06","title":"Offer a second reading of a text","titleCN":"提出对文本的第二种解读","definition":"used to suggest a different interpretation of a passage, image, or event","definitionCN":"用于提出对一段文字、图像或事件的另一种解读","example":"Alternatively, the scene can be read as a burial rather than a meal.","exampleCN":"另一种读法是，这个场景可以被理解为葬礼而非宴饮。","why":"Interpretation is the humanities' version of a hypothesis. The adverb keeps both readings alive by presenting the second as an option, not a correction.","whyCN":"解读是人文学科的“假设”。这个副词把第二种读法作为选项而非更正提出，从而让两种读法都继续成立。"},{"no":"07","title":"Offer a substitute ingredient or material","titleCN":"提出可替换的配料或材料","definition":"used in recipes and specifications to name something that can replace the first item","definitionCN":"用于食谱和规格说明，指出可以替代第一种原料的东西","example":"Alternatively, use almond milk if the recipe must be dairy-free.","exampleCN":"如果这道菜不能含乳制品，也可以改用杏仁奶。","why":"The options are interchangeable at the level of function. The adverb tells the reader that the first item is not a requirement, only the default.","whyCN":"这些选项在功能层面可以互换。这个副词告诉读者，第一种原料不是硬性要求，只是默认值。"},{"no":"08","title":"Give a second name","titleCN":"给出第二个名称","definition":"used before another name, spelling, or label for the same thing","definitionCN":"用于引出同一事物的另一个名称、拼写或标签","example":"The plant, alternatively known as silverweed, grows along the tideline.","exampleCN":"这种植物又称银叶草，长在潮线一带。","why":"Names are options too: two labels for one object. Here the second item does not replace the first as a course of action but as a designation.","whyCN":"名称也可以是选项：一个物体挂两个标签。这里第二项替换第一种的不是行动方案，而是称呼。"},{"no":"09","title":"Give a second way of calculating","titleCN":"给出第二种算法","definition":"used in quantitative writing to present a different calculation or estimate of the same quantity","definitionCN":"用于定量写作，给出同一数量的另一种计算或估算方式","example":"Alternatively, one can estimate the total by dividing the sample count by the sampling fraction.","exampleCN":"或者，也可以把样本计数除以抽样比例来估算总数。","why":"A number can be reached by more than one road. The adverb marks the second road and implicitly asks whether the two arrive at the same place, which is a check on the result.","whyCN":"一个数字可以由不止一条路到达。这个副词标记第二条路，并隐含地追问两条路是否到达同一处，这就是对结果的检验。"}],"etymology":{"intro":{"en":"Alternatively is not a Latin import: it is English alternative + -ly. The chain is alter 'the other of two' → alternare 'do by turns' → alternativus 'offering one or the other' → alternative → alternatively. Each step moves from 'other' to 'taking turns' to 'offering a choice', which is why the adverb can introduce an option but never means 'in turns'. That job belongs to alternately, a different derivative of the same root.","cn":"alternatively 不是从拉丁语整体借来的：它是英语的 alternative 加 -ly。链条是 alter“两者中的另一个”→ alternare“轮流做”→ alternativus“提供两者中的另一个”→ alternative → alternatively。每一步都从“另一个”走到“轮流”，再走到“提供选择”，所以这个副词可以引出选项，却从不表示“轮流地”。那是同根的另一派生词 alternately 的职责。"},"items":[{"era":"1580s","en":"Alternative appears first as an adjective meaning 'offering one or the other of two', from Medieval Latin alternativus.","cn":"alternative 最早作为形容词出现，意为“提供两者中的一个或另一个”，来自中世纪拉丁语 alternativus。"},{"era":"LATIN","en":"Alternativus comes from Latin alternatus, past participle of alternare 'do one thing and then another, do by turns', from alternus 'one after the other, alternate, reciprocal'.","cn":"alternativus 来自拉丁语 alternatus，即 alternare“做一件事再做另一件、轮流做”的过去分词，后者出自 alternus“一个接一个、轮流、相互的”。"},{"era":"PIE","en":"Alternus goes back to alter 'the other (of the two)', reconstructed as PIE *al- 'beyond' plus the comparative suffix -ter. The same root gives alias, alien, altruism, ultimate and, through a variant, English other.","cn":"alternus 可追溯到 alter“两者中的另一个”，重构为原始印欧语 *al-“在……之外”加比较级后缀 -ter。同一词根给出 alias、alien、altruism、ultimate，并经一个变体给出英语 other。"},{"era":"OLD ENGLISH","en":"The -ly is the adverbial suffix from Old English -lice, from Proto-Germanic *-liko-, cognate with lich and identical in origin with like. It forms an adverb meaning 'in the manner of the adjective'.","cn":"-ly 是来自古英语 -lice 的副词后缀，出自原始印欧语 *-liko-，与 lich 同源，并与 like 来源相同。它构成意为“以形容词所描述的方式”的副词。"},{"era":"MODERN ENGLISH","en":"Etymonline has no separate entry for alternatively; the dictionary lists it under alternative as 'Related: Alternatively'. Its formation is therefore transparent: alternative + -ly. The modern discourse use grows alongside the adjective's 20c sense 'purporting to be a superior choice'.","cn":"etymonline 没有 alternatively 的独立条目；词典在 alternative 条目下以“Related: Alternatively”列出它。因此它的构成是透明的：alternative 加 -ly。现代语篇用法随形容词在 20 世纪的“自称更优选择”义一起发展。"},{"era":"TRAP: ALTERNATELY","en":"Alternately is early 15c, from alternate (adj.) + -ly, and means 'by turns' — night and day, up and down. Alternatively means 'as another choice'. Alternate comes from alternatus, alternative from alternativus: same alter root, different formations, different modern jobs.","cn":"alternately 记录于 15 世纪初，由 alternate（形容词）加 -ly 构成，意为“轮流地”——昼夜、上下。alternatively 意为“作为另一种选择”。alternate 来自 alternatus，alternative 来自 alternativus：同一个 alter 词根，不同构形，现代职责也不同。"}]},"similar":{"note":{"en":"The first group is the core trap: one letter separates 'as another choice' from 'by turns'. The other entries are the base adjective, its verb, and the noun of rotation. The second group compares the connectives that can stand where alternatively stands, each with a different logic.","cn":"第一组是核心陷阱：一个字母之差，把“作为另一种选择”与“轮流地”分开。其余条目是基础形容词、其动词、以及表示轮换的名词。第二组比较可以站在 alternatively 位置上的连接词，它们的逻辑各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"alternately","ipa":"/ɔːlˈtɜːnətli/","tag":"by turns, not by choice","definition":"in turns, one after the other, as night follows day. It answers 'in what order?', while alternatively answers 'what else could we do?'.","definitionCN":"轮流地、一个接一个，如昼夜相继。它回答“按什么顺序？”，而 alternatively 回答“我们还能做什么？”。"},{"word":"alternative","ipa":"/ɔːlˈtɜːnətɪv/","tag":"base adjective and noun","definition":"offering another choice, or the other choice itself. The adverb adds only the manner suffix; it does not add a new sense.","definitionCN":"提供另一种选择的，或指那个替代选择本身。副词只加了方式后缀，并没有增加新义。"},{"word":"alternate","ipa":"/ˈɔːltəneɪt/","tag":"verb of rotation","definition":"to take turns, or to arrange two things in succession. As an adjective it means 'every other' or 'backup', not 'another option'.","definitionCN":"轮流，或把两件事物依次安排。作形容词时意为“每隔一个的”或“备用的”，不是“另一个选项”。"},{"word":"alternation","ipa":"/ˌɔːltəˈneɪʃn/","tag":"noun of rotation","definition":"the regular succession of two things, one after the other. It is a pattern in time, not a menu of choices.","definitionCN":"两件事物依次规律更替。它是时间中的模式，不是一份选项菜单。"}]},{"heading":"NEAR MEANING","entries":[{"word":"otherwise","ipa":"/ˈʌðəwaɪz/","tag":"consequence or other respect","definition":"used for the result if something is not done, or for 'in other respects'. It warns of a consequence, while alternatively simply offers a parallel option.","definitionCN":"用于表示若不这样做会有的结果，或表示“在其他方面”。它带有后果警告，而 alternatively 只是并列地给出另一个选项。"},{"word":"instead","ipa":"/ɪnˈsted/","tag":"replacement after rejection","definition":"in place of something that has been rejected or not done. It implies the first option is already out, while alternatively keeps both options open.","definitionCN":"代替已被否定或未做的某事。它暗示第一个选项已经出局，而 alternatively 让两个选项都保持开放。"},{"word":"or else","ipa":"/ɔːr els/","tag":"threat or consequence","definition":"used to introduce a consequence, often a threat, if the first course is not followed. It is coercive, where alternatively is neutral.","definitionCN":"用于引出不照第一种做法时的后果，常含威胁。它带强迫意味，而 alternatively 是中性的。"},{"word":"on the other hand","ipa":"/ɒn ði ˈʌðə hænd/","tag":"contrast, not substitute","definition":"used to balance two sides of an argument. It marks contrast between facts, not a substitute course of action.","definitionCN":"用于平衡一个论点的两面。它标记事实之间的对比，而不是提出替代的行动方案。"}]}]},"mnemonics":{"normalIntro":{"en":"Real pieces: alter 'the other of two', alternare 'do by turns', alternativus, and the native -ly. The central warning is the one-letter difference from alternately, and the domain collocations that show where the adverb works.","cn":"真实成分：alter“两者中的另一个”、alternare“轮流做”、alternativus，以及本土副词后缀 -ly。核心警告是与 alternately 的一字母之差，以及显示副词活动领域的搭配。"},"normal":[{"en":"alter is 'the other of two': alternative offers the other, and alternatively holds that other up as an option.","cn":"alter 是“两者中的另一个”：alternative 提供那另一个，alternatively 则把那另一个举成一个选项。"},{"en":"The root chain is alter → alternare 'do by turns' → alternativus 'offering one or the other'. The 'turns' idea is in the history but not in the modern adverb's job.","cn":"词根链是 alter → alternare“轮流做”→ alternativus“提供两者之一”。“轮流”的想法留在历史里，却不在现代副词的职责里。"},{"en":"One letter decides: alternately means 'by turns'; alternatively means 'as another choice'. Ask whether the sentence is about order or about options.","cn":"一个字母决定：alternately 是“轮流地”；alternatively 是“作为另一种选择”。问自己这句话讲的是顺序还是选项。"},{"en":"In academic writing it is the standard signal for a rival hypothesis, a second method, or a second calculation, not a correction.","cn":"在学术写作中，它是引出竞争性假设、第二种方法或第二种算法的标准信号，而不是更正。"},{"en":"The -ly is the native adverb suffix from Old English -lice; it adds manner, never a new meaning.","cn":"-ly 是来自古英语 -lice 的本土副词后缀；它只添加方式，从不添加新义。"}],"abstract":[{"en":"At a fork, the second sign does not erase the first; it only says the other road also leads somewhere.","cn":"在岔路口，第二块路牌并不擦掉第一块；它只说另一条路也通向某处。"},{"en":"A hypothesis and its rival stand side by side on the same page, neither one winning yet; the adverb is the space between them.","cn":"一个假设和它的对手并排站在同一页上，谁也没赢；这个副词就是它们之间的那道空隙。"},{"en":"Two names for one plant, two methods for one result, two sums for one quantity: the word keeps the second from looking like a mistake.","cn":"一株植物两个名字、一个结果两种方法、一个数量两种算法：这个词让第二个不至于看起来像错误。"}]},"examples":[{"en":"Alternatively, you can submit the form online.","cn":"或者，你也可以在线提交表格。"},{"en":"The protein could be degraded; alternatively, its gene may simply be silent.","cn":"这种蛋白可能被降解了；另一种可能是，它的基因根本没有表达。"},{"en":"The town is alternatively known as Little Venice.","cn":"这个镇又称小威尼斯。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「奥特耐替勿理」——奥特说：别急，还有另一条路“替”着走，不理第一条也行 → alternatively 或者；作为替代（只借音，不表词源）","word":"alternatively"},"root":"由 alternative 加 -ly 构成；alternative 出自中世纪拉丁 alternativus，源自拉丁 alternare「轮流做」，再往上为 alternus「一个接一个」与 alter「两者中的另一个」；核心是「把另一个选项摆出来」。与 alternately（交替地）同根但构词不同，不可混用。","sensesIntro":{"en":"Nine senses of alternatively are nine places where the adverb can put a second item: a choice, a phrase, a fallback, a hypothesis, a method, a reading, an ingredient, a name, a calculation. In every case it keeps the first item standing and offers the second without cancelling either.","cn":"alternatively 的九个义项，是副词放置“第二项”的九个位置：一个选择、一个短语、一个备选、一个假设、一种方法、一种读法、一种配料、一个名称、一种算法。每一种情况下，它都让第一项继续站着，同时提出第二项，而不取消任何一方。"},"semanticMap":{"core":{"en":"CORE IMAGE: a second sign at the same fork, pointing at another road that is also open.","cn":"核心意象：同一个岔路口的第二块路牌，指向另一条同样开放的路。"},"chain":["ALTER, THE OTHER OF TWO","ALTERNARE, DO BY TURNS","ALTERNATIVUS, OFFERING ONE OR THE OTHER","ALTERNATIVE, THE OTHER CHOICE","-LY, IN THAT MANNER","A SECOND ITEM HELD OPEN"],"branches":[{"senses":"01 · 02","en":"THE CORE MOVE: hold up a second option, either for a whole plan or for a single phrase inside a sentence.","cn":"核心动作：举起第二个选项，或针对整个计划，或只针对句中的一个短语。"},{"senses":"03","en":"CONTINGENCY: the second option waits behind the first, available only if the first fails.","cn":"备用方案：第二个选项在第一个后面待命，只在第一个失败时启用。"},{"senses":"04 · 09","en":"REASONING: a rival explanation or a second calculation, placed beside the first so that evidence can be weighed.","cn":"推理：竞争性的解释或第二种算法，被放在第一个旁边，以便权衡证据。"},{"senses":"05 · 07","en":"PRACTICE: a second procedure or a substitute ingredient, interchangeable because the end is fixed.","cn":"实践：第二种程序或可替代的配料，因为终点固定而可以互换。"},{"senses":"06 · 08","en":"MEANING AND NAME: a second reading of a text, or a second label for the same thing.","cn":"意义与名称：对文本的第二种读法，或同一事物的第二个标签。"}]},"affixes":{"intro":{"en":"Alternatively is English morphology on a Latin base: alternative + -ly. The -ly adds only 'in that manner', while the Latin part carries the whole idea of the other of two and of taking turns. The one-letter neighbour alternately is built from a different Latin participle and means something else.","cn":"alternatively 是拉丁词基上的英语构词：alternative 加 -ly。-ly 只添加“以那种方式”，而拉丁部分承载了“两者中的另一个”与“轮流”的全部意思。只差一个字母的邻居 alternately 由另一个拉丁分词构成，意思也不同。"},"latinIntro":{"en":"The Latin layer is alter 'the other of two', alternare 'do by turns', alternus 'one after the other', and alternativus 'offering one or the other'. English also forms alternate and alternation from the same family, with the 'turns' meaning.","cn":"拉丁层包括 alter“两者中的另一个”、alternare“轮流做”、alternus“一个接一个”、alternativus“提供两者之一”。英语还从同一词族构成 alternate 与 alternation，保留“轮流”义。"},"items":[{"word":"alternatively","structure":"alternative + -ly (manner adverb)","meaning":"as another choice or possibility","meaningCN":"作为另一种选择或可能（-ly 方式副词）","example":"Alternatively, we could meet on Friday.","exampleCN":"或者，我们可以周五见面。"},{"word":"alternative","structure":"alternat- (by turns) + -ive (adjective and noun)","meaning":"offering or being the other choice","meaningCN":"提供或作为另一选择的（-ive 形容词／名词）","example":"They found an alternative source of water.","exampleCN":"他们找到了另一个水源。"},{"word":"alternately","structure":"alternate (adj.) + -ly","meaning":"by turns, one after the other","meaningCN":"交替地；轮流地（同根不同构词，易混）","example":"The two lights flashed alternately.","exampleCN":"两盏灯交替闪烁。"},{"word":"alternate","structure":"alternatus (past participle of alternare) + -ate","meaning":"to take turns; every other; backup","meaningCN":"轮流；每隔一个的；备用的","example":"Wet and dry years alternate in this region.","exampleCN":"这个地区湿年与干年交替出现。"},{"word":"alternation","structure":"alternate + -ion (action noun)","meaning":"regular succession by turns","meaningCN":"规律性的交替（-ion 动作名词）","example":"The alternation of generations is common in ferns.","exampleCN":"世代交替在蕨类中很常见。"},{"word":"alter","structure":"Latin alter (the other of two)","meaning":"to make different; to change in part","meaningCN":"使不同；部分改变（同根另一支）","example":"We had to alter the plan when the road closed.","exampleCN":"路封了，我们只好改计划。"},{"word":"alteration","structure":"alter + -ation (action noun)","meaning":"a change in part","meaningCN":"改动；变更（同根，但指改变而非选择）","example":"The alteration to the contract was initialled.","exampleCN":"合同上的那处改动被签了首字母。"},{"word":"alias","structure":"Latin alias 'at another time, otherwise'","meaning":"a second name; otherwise called","meaningCN":"别名；又名（同出 *al-，可辅助记忆“另一个”）","example":"The suspect used an alias at the border.","exampleCN":"嫌疑人在边境用了化名。"},{"word":"alien","structure":"Latin alienus 'belonging to another'","meaning":"foreign; belonging elsewhere","meaningCN":"外来的；属于别处的（同出 *al-“别的”）","example":"The species is alien to this island.","exampleCN":"这个物种不是本岛原生的。"},{"word":"otherwise","structure":"other + -wise (manner)","meaning":"in another way, or if not","meaningCN":"以另一种方式；否则（英语本土构词，义近但不同）","example":"Write it down, otherwise you will forget.","exampleCN":"记下来，否则你会忘。"}],"latinEntries":[{"word":"alter","structure":"Latin comparative, PIE *al- 'beyond' + -ter","meaning":"the other of two","meaningCN":"两者中的另一个"},{"word":"alternare","structure":"alternus + -are (verb)","meaning":"to do one thing then another, do by turns","meaningCN":"做一件再做另一件；轮流做"},{"word":"alternativus","structure":"alternat- + -ivus (adjective)","meaning":"offering one or the other","meaningCN":"提供两者之一；可供选择的"}]}},{"word":"ambiguity","ipa_uk":"/ˌæmbɪˈɡjuːəti/","ipa_us":"/ˌæmbɪˈɡjuːəti/","definition_zh":"歧义；含糊；模棱两可；犹豫不决；（意图的）不确定","definition_en":"the quality of having more than one possible meaning, of being unclear, or of a state of doubt in which the mind cannot settle","core_image":"一句话被同时驱向两条路：两种读法都站得住，谁也没被甩开","scene":"审稿人读到「他们给旧船刷了漆和发动机」这一句，先笑出声，随后在页边写下批注。The reviewer reads the sentence 'they painted the old boat and the engine', laughs, and notes the structural ambiguity in the margin.","sceneCN":"这里 ambiguity 是「句法歧义」（第 4 个义项：句子结构可作两种切分）；句意：审稿人读到这句话先笑出声，随后在页边记下它的句法歧义。场景要点：稿纸页边的批注、被圈出的 and、两种颜色的修改笔、停住的笔尖。","pos":[{"tag":"n.","zh":"歧义；含糊；模棱两可；犹豫不决"}],"collocations":[{"phrase":"avoid ambiguity","zh":"避免歧义"},{"phrase":"remove ambiguity","zh":"消除含糊之处"},{"phrase":"deliberate ambiguity","zh":"有意为之的模棱两可"},{"phrase":"ambiguity of meaning","zh":"意义上的歧义"},{"phrase":"resolve an ambiguity","zh":"消解一处歧义"},{"phrase":"structural ambiguity","zh":"结构歧义"},{"phrase":"moral ambiguity","zh":"道德上的含混（人物或结局难以简单评判）"}],"forms":[{"label":"复数（多于一个）","form":"ambiguities"}],"derivatives":[{"word":"ambiguous","pos":"adj.","zh":"有歧义的；含糊不清的；模棱两可的"},{"word":"ambiguously","pos":"adv.","zh":"含糊地；模棱两可地"},{"word":"ambiguousness","pos":"n.","zh":"歧义性；含糊"},{"word":"unambiguous","pos":"adj.","zh":"不含糊的；明确无误的"},{"word":"unambiguously","pos":"adv.","zh":"明确无误地"}],"senses":[{"no":"01","title":"Doubting, unable to decide","titleCN":"犹疑不决：心智停不下来","definition":"the state of being unable to decide or of hesitating between possibilities","definitionCN":"无法作出决定、在几种可能之间犹豫不定的状态","example":"His ambiguity about the job offer showed in the way he kept changing the subject.","exampleCN":"他对这份工作邀请的犹豫，表现在他总把话题岔开。","why":"This is the earliest English sense, recorded c.1400. Latin ambigere meant 'to be driven around', so the mind here is not empty of meaning; it is pulled first one way and then the other.","whyCN":"这是英语最早的义项，约记录于 1400 年。拉丁语 ambigere 意为“被驱赶着转来转去”，所以这里并非“没有意思”，而是心智先被拉向一边、又被拉向另一边。"},{"no":"02","title":"Two meanings in one word","titleCN":"一词两义：同一个词被读出两种意思","definition":"the quality of a word or phrase that can be understood in two or more different ways","definitionCN":"一个词或短语可以被理解成两种或多种不同意思的性质","example":"The ambiguity of 'bank' made the joke work.","exampleCN":"bank 一词的歧义让这个笑话成立了。","why":"Once ambiguity names the word rather than the mind, the two directions of ambigere become two readings of one form. The word itself is the crossroads where both roads stay open.","whyCN":"当 ambiguity 指的不是心智而是词语时，ambigere 的两个方向就变成同一个词形的两种读法。词本身就是那个两条路都敞开的十字路口。"},{"no":"03","title":"The meaning is left unclear","titleCN":"表述含混：意义没有被说清","definition":"the quality of a statement or description that is not precise enough to be understood clearly","definitionCN":"陈述或描述不够精确、因而无法被清楚理解的性质","example":"Critics attacked the ambiguity of the policy statement.","exampleCN":"批评者抨击那份政策声明的含混不清。","why":"Here the two readings are not both useful; the text simply fails to close the gap. The same fork remains, but it is now a defect of description, recorded from the early 15th century.","whyCN":"这里两种读法并非都有用，文本只是没能把缺口合上。同一个分叉仍在，但此时它是表述上的缺陷；这一用法记录于 15 世纪早期。"},{"no":"04","title":"Two parses of one sentence","titleCN":"同一句话的两种句法切分","definition":"in linguistics, the property of a sentence whose grammatical structure can be analysed in more than one way","definitionCN":"在语言学中，指句子的语法结构可以被分析成不止一种形式","example":"The sentence 'old men and women' is famous for its structural ambiguity.","exampleCN":"“old men and women”这句话以结构歧义著称。","why":"The fork is no longer in the dictionary but in the brackets: [old men] and women assigns old to men only, while old [men and women] assigns it to both. One string of words supports two trees.","whyCN":"分叉不在词典里，而在括号里：[old men] and women 把 old 只给 men，而 old [men and women] 把 old 同时给了 men 和 women。同一串词支撑起两棵句法树。"},{"no":"05","title":"Deliberate ambiguity in negotiation","titleCN":"谈判中的有意含糊","definition":"the intentional use of unclear wording so that different parties can each read what they want into it","definitionCN":"故意使用不清楚的措辞，让不同各方都能从中读出自己想要的意思","example":"The agreement preserved a deliberate ambiguity over the status of the region.","exampleCN":"该协议在该地区的地位问题上保留了一种有意的含糊。","why":"Both readings are kept alive on purpose. Instead of driving the mind to a decision, the wording lets each side drive it in its own direction, so ambiguity becomes a diplomatic tool rather than a fault.","whyCN":"两种读法被有意地同时保留。措辞不把心智驱向某个决定，而是让每一方把它驱向自己的方向，于是含糊从缺陷变成了外交工具。"},{"no":"06","title":"One picture, two figures","titleCN":"一张图，两个形象","definition":"the quality of an image or sound that can be perceived in two different ways, as in an ambiguous figure","definitionCN":"图像或声音可以被感知为两种不同样式的性质，如双义图形","example":"The duck-rabbit drawing is a classic case of perceptual ambiguity.","exampleCN":"鸭兔图是知觉歧义的经典例子。","why":"The eye, like the mind in the earliest sense, is driven to two gestalts and can flip between them. Both readings are fully present in the same stimulus, so neither can be dismissed.","whyCN":"眼睛就像最早义项里的心智，被驱向两种完形，并在两者之间翻转。两种读法都完整地存在于同一个刺激中，因此哪一种都无法被排除。"},{"no":"07","title":"An unclear position or role","titleCN":"身份或角色的模糊","definition":"the state of having a role or status that is not clearly defined, so that expectations remain unsettled","definitionCN":"所担任的角色或地位没有被清楚界定、因而期待始终悬而未决的状态","example":"The ambiguity of her position as adviser and friend caused friction.","exampleCN":"她既是顾问又是朋友，这种身份的模糊引发了摩擦。","why":"A person can occupy two categories at once. Neither label wins, so the social situation wavers like the original verb: the same person is legitimately read two ways.","whyCN":"一个人可以同时占据两个类别。两个标签都不占上风，于是社会处境像原动词一样摇摆：同一个人被两种方式合理地解读。"},{"no":"08","title":"Meaning left open in a work","titleCN":"作品中保留的开放意义","definition":"in literature and art, the quality of a work that invites several readings without settling on one","definitionCN":"在文学与艺术中，作品邀请多种读法而不落定于其一的品质","example":"The ambiguity of the ending is what makes the novel memorable.","exampleCN":"结局的开放含混正是这部小说令人难忘的原因。","why":"Here the fork is valued rather than repaired. The work holds two readings in suspension and leaves the reader to waver, turning the old defect into an aesthetic effect.","whyCN":"这里的分叉是被珍视的，而不是被修复的。作品把两种读法悬置起来，让读者自己去摇摆，把旧的缺陷转成了审美效果。"},{"no":"09","title":"Unclear intention behind an act","titleCN":"行为背后意图不明","definition":"the quality of an action or gesture whose underlying intention cannot be determined, even when the words or act themselves are clear","definitionCN":"行为或姿态背后的意图无法确定，即使言语或动作本身很清楚","example":"There was an ambiguity in his kindness that made her distrust it.","exampleCN":"他的善意里有某种说不清的意味，让她反而起了疑心。","why":"Two possible motives are driven at once, so the fork moves from wording to intention. The act is plain, but why it was done remains double, which is why the word can describe motives as well as sentences.","whyCN":"两种可能的动机同时被驱动，分叉就从措辞移到了意图。行为本身很清楚，但“为什么这样做”仍然是双重的；因此这个词既能描述句子，也能描述动机。"}],"etymology":{"intro":{"en":"Ambiguity comes from Latin ambiguitas, a noun of state from ambiguus 'having double meaning'. The verb behind it is ambigere 'to dispute, wander, waver', literally ambi- 'about, both ways' + agere 'to drive'. The second element is therefore agere, not a piece that sounds like 'guity'; the core image is a mind driven in two directions at once.","cn":"ambiguity 来自拉丁语 ambiguitas，是由 ambiguus“有两种意思的”构成的状态名词。其背后的动词是 ambigere“争执、徘徊、犹豫”，字面为 ambi-“两边、周围”+ agere“驱动”。因此第二成分是 agere，而不是某个听起来像“guity”的部分；核心意象是心智同时被驱向两个方向。"},"items":[{"era":"c. 1400","en":"First recorded in English as 'uncertainty, doubt, indecision, hesitation', from Old French ambiguite and directly from Latin ambiguitatem (nominative ambiguitas). The earliest sense is about the doubting mind, not about a double-meaning word.","cn":"英语最早记录为“不确定、怀疑、犹豫不决”，来自古法语 ambiguite，并直接来自拉丁语 ambiguitatem（主格 ambiguitas）。最早的义项说的是犹豫的心智，而不是一词两义。"},{"era":"LATIN NOUN","en":"Ambiguitas was a noun of state from ambiguus 'having double meaning, doubtful'. That adjective already contains the fork: a thing can be taken in two ways, and therefore the person facing it does not know which way to go.","cn":"ambiguitas 是由 ambiguus“有两种意思的、可疑的”构成的状态名词。那个形容词本身已经含有分叉：一件事可以被两种方式理解，因此面对它的人不知道该往哪边走。"},{"era":"LATIN VERB","en":"Ambigere meant 'to dispute about, contend, debate', but literally 'to wander, go about, go around', and figuratively 'to hesitate, waver, be in doubt'. The physical image is being driven around in circles rather than arriving at a point.","cn":"ambigere 意为“就……争执、辩论”，但字面是“游荡、四处走、绕圈”，引申为“犹豫、摇摆、存疑”。其身体意象是被驱赶着绕圈，而不是抵达某一点。"},{"era":"MORPHOLOGY / PIE","en":"Ambi- 'about' is from PIE *ambhi- 'around'; agere 'drive, lead, act' is from PIE *ag- 'to drive, draw out or forth, move'. So the word is built on driving, not on any root meaning 'doubt' or 'two-faced'. Ambiguity is what happens when something is driven both ways at once.","cn":"ambi-“周围”来自原始印欧语 *ambhi-“环绕”；agere“驱动、引领、行动”来自 *ag-“驱赶、拉出、移动”。因此这个词建立在“驱动”上，而不是任何意为“怀疑”或“两面”的词根上。ambiguity 就是某物被同时驱向两边的结果。"},{"era":"EARLY 15C.","en":"The sense 'obscurity in description' is recorded from the early 15th century. The adjective ambiguous follows later, first attested in Sir Thomas More in 1528, so the abstract noun was in English before its adjective became common.","cn":"“描述含混”这一义项记录于 15 世纪早期。形容词 ambiguous 出现更晚，最早见于 1528 年的托马斯·莫尔；也就是说，这个抽象名词先进入英语，其形容词后来才通行。"},{"era":"MODERN ENGLISH","en":"Modern English extends the same fork to syntax, perception, diplomacy, social roles, art and motive. Two look-alikes must be kept apart: ambivalent is ambi- + valere 'to be worth, be strong', and ambition is ambi- + ire 'to go'. Neither shares the agere element of ambiguity.","cn":"现代英语把同一个分叉扩展到句法、知觉、外交、社会角色、艺术与动机。两个形似词必须分开：ambivalent 是 ambi- + valere“有价值、有力量”，ambition 是 ambi- + ire“走”。两者都不含 ambiguity 的 agere 成分。"}]},"similar":{"note":{"en":"The first group separates words that look or sound like ambiguity but are built from different Latin verbs; the second compares words learners often use in its place. The key test is whether the trouble lies in two readings or in missing knowledge.","cn":"第一组区分那些形似或音似 ambiguity、却由不同拉丁动词构成的词；第二组比较学习者常用来替换它的词。关键区别是：麻烦究竟来自“两种读法”，还是来自“知识缺失”。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ambiguous","ipa":"/æmˈbɪɡjuəs/","tag":"same family","definition":"having more than one possible meaning. It is the adjective from ambiguity and names the thing that carries two readings, not the state of doubt itself.","definitionCN":"具有不止一种可能意思的。它是 ambiguity 派生的形容词，指承载两种读法的那个东西，而不是犹疑状态本身。"},{"word":"ambivalent","ipa":"/æmˈbɪvələnt/","tag":"different root","definition":"having mixed or conflicting feelings about someone or something. It is ambi- plus Latin valere 'to be strong, be worth', so it is about two pulls of feeling, not two meanings.","definitionCN":"对某人或某事怀有混合、矛盾的情感。它是 ambi- 加拉丁语 valere“有力量、有价值”，说的是两种情感拉力，而不是两种意思。"},{"word":"ambition","ipa":"/æmˈbɪʃn/","tag":"different root","definition":"a strong desire to achieve something. It goes back to Latin ambire 'to go around', originally canvassing for votes: ambi- + ire 'to go', with no agere.","definitionCN":"实现某事的强烈愿望。它上溯拉丁语 ambire“四处走”，原指为拉票而奔走：ambi- + ire“走”，不含 agere。"},{"word":"ambulatory","ipa":"/ˈæmbjələtəri/","tag":"different root","definition":"relating to walking, or able to walk. It comes from Latin ambulare 'to walk', which merely happens to begin with amb-. There is no ambi- prefix at all.","definitionCN":"与行走有关的，或能行走的。它来自拉丁语 ambulare“行走”，只是碰巧以 amb- 开头，根本没有 ambi- 前缀。"}]},{"heading":"NEAR MEANING","entries":[{"word":"vagueness","ipa":"/ˈveɪɡnəs/","tag":"lack of precision","definition":"the quality of being imprecise or lacking a clear boundary. Vagueness says the edges are fuzzy; ambiguity says two or more distinct readings are actually available.","definitionCN":"不精确或缺少清晰边界的性质。vagueness 说边界模糊；ambiguity 说确实存在两种或更多彼此不同的读法。"},{"word":"equivocation","ipa":"/ɪˌkwɪvəˈkeɪʃn/","tag":"deliberate deception","definition":"the use of a word with more than one meaning in order to mislead. Equivocation adds the intent to deceive, while ambiguity can be innocent or even useful.","definitionCN":"利用一词多义来误导他人。equivocation 多了一层欺骗意图，而 ambiguity 可以是无意的，甚至是有用的。"},{"word":"uncertainty","ipa":"/ʌnˈsɜːtnti/","tag":"missing knowledge","definition":"the state of not knowing what will happen or what is true. Uncertainty is about the observer's ignorance; ambiguity is about the object supporting several readings.","definitionCN":"不知道会发生什么或什么是真的。uncertainty 说的是观察者的无知；ambiguity 说的是对象本身支持多种读法。"},{"word":"obscurity","ipa":"/əbˈskjʊərəti/","tag":"hidden meaning","definition":"the quality of being hard to understand because it is hidden or unfamiliar. Obscurity hides one meaning; ambiguity displays two.","definitionCN":"因隐蔽或陌生而难以理解的性质。obscurity 把一种意思藏起来；ambiguity 则把两种意思摆出来。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: ambi- 'both ways' plus agere 'to drive', the ambiguity family, and the three look-alikes built from valere, ire and ambulare.","cn":"只用真实成分与真实同族词：ambi-“两边”加 agere“驱动”、ambiguity 词族，以及由 valere、ire、ambulare 构成的三个形似词。"},"normal":[{"en":"ambi- means 'both ways' and agere means 'to drive'. Ambiguity is literally a thing driven in two directions at once.","cn":"ambi- 意为“两边”，agere 意为“驱动”。ambiguity 字面上就是“被同时驱向两边的状态”。"},{"en":"The same agere root gives agent, act, agenda and agile, so ambiguity belongs with 'driving and doing', not with any word for 'two-faced'.","cn":"同一 agere 词根给出 agent、act、agenda、agile，所以 ambiguity 属于“驱动与行动”这一族，与任何“两面”词无关。"},{"en":"Three look-alikes use three different second elements: ambivalent has valere 'be worth', ambition has ire 'go', ambulatory has ambulare 'walk'.","cn":"三个形似词用了三个不同的第二成分：ambivalent 是 valere“有价值”，ambition 是 ire“走”，ambulatory 是 ambulare“行走”。"},{"en":"The earliest sense was 'hesitation', not 'double meaning'. The mind wavered first; the word's double meaning was named later.","cn":"最早的义项是“犹豫”，不是“一词两义”。先有摇摆的心智，后来才用它命名词语的双重意思。"},{"en":"Structural ambiguity lives in brackets: [old men] and women versus old [men and women].","cn":"结构歧义活在括号里：[old men] and women 对 old [men and women]。"}],"abstract":[{"en":"Picture a road that splits at a fork. The driver is not lost for lack of a map; both roads are real, and the car is pulled down each one in turn.","cn":"想象一条在岔口分开的路。司机并非因为没有地图而迷路；两条路都真实存在，车子被先后拉向每一条。"},{"en":"The same fork can sit in a word, a sentence, a drawing, a treaty, a job title or a gesture. What stays constant is that two readings remain standing at once.","cn":"同一个分叉可以藏在单词、句子、图画、条约、职位名称或一个姿态里。不变的是：两种读法同时立着。"},{"en":"Sometimes the fork is a fault to be repaired; sometimes it is deliberately preserved. Ambiguity can therefore be either a problem or a resource.","cn":"有时这个分叉是要修掉的缺陷，有时它被有意保留。因此 ambiguity 既可能是问题，也可能是资源。"}]},"examples":[{"en":"Please rewrite the sentence to remove its ambiguity.","cn":"请改写这句话，消除它的歧义。"},{"en":"The play ends in ambiguity, and each audience member decides what happened.","cn":"这部剧以含糊收场，每位观众都自己判断到底发生了什么。"},{"en":"There was an ambiguity in her tone that made him unsure whether she was joking.","cn":"她的语气里有某种含混，让他拿不准她是不是在开玩笑。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「俺必鬼题」——俺必答的那道鬼题，两个答案都说得通 → ambiguity 歧义、模棱两可","word":"ambiguity"},"root":"来自拉丁语 ambiguitas，上溯 ambiguus“有两种意思的”与 ambigere“徘徊、争执”，字面是 ambi-“两边”加 agere“驱动”，核心是“心智被同时驱向两边”。","sensesIntro":{"en":"Nine senses of ambiguity, all one fork: a form, a situation or a mind is driven in two directions at once. Sometimes both readings are legitimate, sometimes the split is a defect, and sometimes it is deliberately preserved.","cn":"ambiguity 的九个义项都源于同一个分叉：一个词形、一种处境或一颗心智被同时驱向两个方向。有时两种读法都合法，有时分裂是缺陷，有时它被有意保留。"},"semanticMap":{"core":{"en":"CORE IMAGE: one form or situation driven down two roads at the same time.","cn":"核心意象：同一个词形或处境被同时驱上两条路。"},"chain":["ONE FORM","TWO READINGS","MIND PULLED BOTH WAYS","NO SINGLE MEANING","BOTH STILL STANDING","DOUBT OR OPENNESS"],"branches":[{"senses":"01 · 09","en":"INNER FORK: hesitation and unclear motive. The mind is pulled both ways before any wording is fixed.","cn":"内在分叉：犹豫与动机不明。措辞尚未固定，心智先被拉向两边。"},{"senses":"02 · 04","en":"CODE: one word or one sentence carries two readings, whether in the dictionary or in the brackets.","cn":"代码层：一个词或一句话承载两种读法，无论在词典里还是在句法括号里。"},{"senses":"03 · 08","en":"TEXT: vagueness is a fault and open-endedness is a virtue, but both leave meaning unresolved.","cn":"文本层：含混是缺陷，开放是美德，但两者都让意义悬而未决。"},{"senses":"05 · 07","en":"INSTITUTIONS: negotiators and social roles keep two readings alive, sometimes on purpose and sometimes by accident.","cn":"制度层：谈判者与社会角色让两种读法同时存活，有时出于有意，有时出于无意。"},{"senses":"06","en":"PERCEPTION: the eye flips between two figures held in one drawing.","cn":"知觉层：眼睛在一张图里所持的两个形象之间翻转。"}]},"affixes":{"intro":{"en":"Ambiguity is a Latin-derived noun whose parts are frozen: ambi- 'both ways' + agere 'to drive' + -ity. English adds only ordinary suffixes to the finished family. The -ity is not a meaning-bearing 'guity' chunk, and the whole word never meant 'two-faced'.","cn":"ambiguity 是拉丁来源的名词，其成分已经凝固：ambi-“两边”+ agere“驱动”+ -ity。英语只是在成品词族后加普通后缀。-ity 并不是一个带意义的“guity”部件，整个词也从来不是“两面派”的意思。"},"latinIntro":{"en":"The Latin family is ambigere 'to dispute, wander, waver', its adjective ambiguus 'double-meaning, doubtful', and agere 'to drive, lead, act'. The same agere yields agent, act, agenda and agile, while ambivalent and ambition belong to valere and ire respectively.","cn":"拉丁词族包括 ambigere“争执、徘徊、犹豫”、其形容词 ambiguus“有两种意思的、可疑的”，以及 agere“驱动、引领、行动”。同一 agere 给出 agent、act、agenda、agile，而 ambivalent 与 ambition 分别属于 valere 和 ire。"},"items":[{"word":"ambiguity","structure":"ambi- (both ways) + agere (to drive) + -ity (noun of state)","meaning":"the state of being driven two ways, hence double meaning or doubt","meaningCN":"被驱向两边的状态，因而指歧义或犹疑（-ity 构成状态名词）","example":"The ambiguity of the clause delayed the signing.","exampleCN":"条款的歧义推迟了签署。"},{"word":"ambiguous","structure":"ambigu- (from ambiguus) + -ous (adjective)","meaning":"open to more than one interpretation","meaningCN":"可作不止一种解释的；有歧义的（-ous 构成形容词）","example":"He gave an ambiguous answer and left the room.","exampleCN":"他给了个模棱两可的回答，然后离开了房间。"},{"word":"ambiguously","structure":"ambiguous + -ly (adverb of manner)","meaning":"in a way that can be understood in more than one sense","meaningCN":"以含糊、可作多种理解的方式（-ly 构成方式副词）","example":"She smiled ambiguously and said nothing.","exampleCN":"她含义不明地笑了笑，什么也没说。"},{"word":"ambiguousness","structure":"ambiguous + -ness (noun of quality)","meaning":"the quality of being ambiguous","meaningCN":"有歧义性；含糊（-ness 构成性质名词）","example":"The ambiguousness of the title was intentional.","exampleCN":"标题的含混是有意为之。"},{"word":"unambiguous","structure":"un- (not) + ambiguous","meaning":"having only one clear meaning","meaningCN":"不含糊的；只有一种清楚意思的（un- 否定）","example":"The instructions were short and unambiguous.","exampleCN":"说明简短而明确。"},{"word":"unambiguously","structure":"un- (not) + ambiguously","meaning":"in a way that leaves no doubt","meaningCN":"毫不含糊地；明确无误地","example":"The court ruled unambiguously in her favour.","exampleCN":"法院明确无误地判她胜诉。"},{"word":"ambivalent","structure":"ambi- (both) + valere (to be worth, be strong) — a different root","meaning":"having mixed feelings; not the same as having two meanings","meaningCN":"有矛盾情感的；与“两种意思”不同源（valere 有价值、有力量）","example":"She felt ambivalent about moving abroad.","exampleCN":"她对移居国外心情矛盾。"},{"word":"ambivalence","structure":"ambivalent + -ence (noun of state)","meaning":"the state of having conflicting feelings","meaningCN":"矛盾情感；正反情绪并存（-ence 构成状态名词）","example":"His ambivalence made the decision harder.","exampleCN":"他的矛盾心理让决定更难做。"},{"word":"ambition","structure":"ambi- (around) + ire (to go) — a different root","meaning":"a strong drive to achieve something, originally 'going around' to canvass","meaningCN":"雄心；抱负（原指四处奔走拉票，与 agere 无关）","example":"Her ambition was to lead the research team.","exampleCN":"她的抱负是领导这个研究团队。"},{"word":"ambit","structure":"ambi- (around) + ire (to go) — a different root","meaning":"the scope or boundary of something","meaningCN":"范围；界限（同 ambire 一族，与 agere 无关）","example":"That question lies outside the ambit of the inquiry.","exampleCN":"那个问题不在调查范围之内。"}],"latinEntries":[{"word":"ambigere","structure":"ambi- (about, both ways) + agere (to drive)","meaning":"to dispute, wander, waver, be in doubt","meaningCN":"争执；徘徊；犹豫；存疑"},{"word":"ambiguus","structure":"from ambigere, adjective ending -uus","meaning":"having double meaning, doubtful","meaningCN":"有两种意思的；可疑的"},{"word":"agere","structure":"Latin verb, from PIE *ag- 'to drive'","meaning":"to drive, lead, act, do","meaningCN":"驱动；引领；行动；做"}]}},{"word":"amendment","ipa_uk":"/əˈmendmənt/","ipa_us":"/əˈmendmənt/","definition_zh":"修正；修订；修正案；（法律文件的）更改；（土壤）改良剂；改过自新","definition_en":"a change made to correct or improve something, especially a formal change to a law or document, or the act of removing faults from something","core_image":"把条文里那处缺陷挖掉、补正，让文本重新站直","scene":"议事厅里，一名议员把一张纸推到桌子中央，提议把「十八岁投票」写进宪法。In the chamber, a member pushes a sheet of paper to the centre of the table and proposes an amendment that would let eighteen-year-olds vote.","sceneCN":"这里 amendment 是「宪法修正案」（第 2 个义项：对宪法或法律的正式修改）；句意：议事厅里，一名议员把纸推到桌子中央，提出一项允许十八岁者投票的宪法修正案。场景要点：议事厅的长桌、推到中央的纸页、纸上的编号、议员举起的手。","pos":[{"tag":"n.","zh":"修正；修订；修正案；（土壤）改良剂；改过自新"}],"collocations":[{"phrase":"constitutional amendment","zh":"宪法修正案"},{"phrase":"propose an amendment","zh":"提出修正案"},{"phrase":"adopt an amendment","zh":"通过修正案"},{"phrase":"amendment to the bill","zh":"对法案的修正"},{"phrase":"amendment of the contract","zh":"合同的修订"},{"phrase":"soil amendment","zh":"土壤改良剂"},{"phrase":"draft amendment","zh":"修正案草案"}],"forms":[{"label":"复数（多于一个）","form":"amendments"}],"derivatives":[{"word":"amend","pos":"v.","zh":"修正；修订；改进"},{"word":"amends","pos":"n.","zh":"（make amends）赔偿；补偿"},{"word":"amendable","pos":"adj.","zh":"可修正的；可修订的"},{"word":"amendatory","pos":"adj.","zh":"修正的；修改性的"},{"word":"emend","pos":"v.","zh":"校订；勘正（尤指文本）"}],"senses":[{"no":"01","title":"Making something better by removing faults","titleCN":"去缺陷而使之变好","definition":"the act of correcting or improving something that is faulty or imperfect","definitionCN":"纠正或改进有缺陷、不完美之事的行为","example":"The amendment of the manuscript took longer than writing it.","exampleCN":"修订这份手稿花的时间比写它还长。","why":"The earliest sense, recorded in the early 13th century, is simply 'betterment, improvement'. Latin emendare is ex- 'out' plus menda 'fault', so making better begins with taking a fault out, not with putting something in.","whyCN":"最早义项记录于 13 世纪早期，就是“改善、变好”。拉丁语 emendare 是 ex-“出”加 menda“缺陷”，所以“变好”的起点是把缺陷拿出去，而不是把东西放进去。"},{"no":"02","title":"A formal change to a constitution or law","titleCN":"对宪法或法律的正式修改","definition":"an official change to a constitution, statute, or legal instrument, made according to established procedure","definitionCN":"依照既定程序对宪法、成文法或法律文书作出的正式更改","example":"The First Amendment protects freedom of speech and of the press.","exampleCN":"第一修正案保护言论与出版自由。","why":"A constitution is treated as a text with possible faults or gaps. Once the correction must pass a fixed procedure, the act of removing the fault becomes a numbered public document called an amendment.","whyCN":"宪法被当作一份可能有缺陷或空白的文本。当纠正必须经过固定程序时，“去掉缺陷”的行为就变成一份编号的公开文件，称为 amendment。"},{"no":"03","title":"A proposed change to a bill","titleCN":"对法案提出的修改","definition":"a change proposed to a bill during debate, by a member or a committee, before it becomes law","definitionCN":"法案在辩论期间由议员或委员会提出、在其成为法律之前的更改","example":"The committee tabled an amendment to cut the proposed budget.","exampleCN":"委员会提出一项修正案，要求削减拟议预算。","why":"Here the fault is not yet in a finished law but in a draft. The amendment is the correction offered while the text is still open, which is why it is often a proposal rather than a settled change.","whyCN":"这里的缺陷还不在已生效的法律里，而在草案里。修正案是在文本仍然敞开时提出的纠正，因此它往往是一项提案，而不是已经落定的更改。"},{"no":"04","title":"Correction of an error in legal process","titleCN":"对法律程序错误的更正","definition":"in law, the correction of an error in a writ, pleading, or court process","definitionCN":"在法律上，对令状、诉状或法院程序中的错误进行更正","example":"The court allowed an amendment of the writ to correct the defendant's name.","exampleCN":"法院允许修改令状，以更正被告的姓名。","why":"The sense 'correction of error in a legal process' is recorded about 1600, and 'alteration of a writ or bill to remove its faults' in the 1690s. The fault is now procedural, and the amendment is the official act that removes it.","whyCN":"“更正法律程序中的错误”这一义项约记录于 1600 年，而“更改令状或法案以去掉其缺陷”记录于 17 世纪 90 年代。这里的缺陷是程序性的，修正就是去掉它的正式行为。"},{"no":"05","title":"A change to a contract or agreement","titleCN":"对合同或协议的修订","definition":"a formal change to the terms of a contract, lease, or agreement, usually signed by all parties","definitionCN":"对合同、租约或协议条款的正式更改，通常由各方签署","example":"Both parties signed an amendment extending the lease by two years.","exampleCN":"双方签署了一份修正协议，把租期延长两年。","why":"A contract is a text whose terms must fit reality. When reality changes, the mismatch is treated as a fault in the document, and the amendment restores the fit.","whyCN":"合同是一份条款必须贴合现实的文本。现实一变，不匹配就被当作文件里的缺陷，而 amendment 恢复这种贴合。"},{"no":"06","title":"A textual revision before publication","titleCN":"出版前的文本修订","definition":"a correction or revision made to a scholarly, technical, or literary text","definitionCN":"对学术、技术或文学文本所作的更正或修订","example":"The journal asked for several amendments before accepting the paper.","exampleCN":"期刊在接受论文之前要求作几处修订。","why":"This is the domain where the old 'remove the fault' sense survives most purely. The sibling verb emend and the noun emendation are reserved for exactly this textual work, while amendment has spread to law and institutions.","whyCN":"这是“去掉缺陷”这一古老义项保留得最纯粹的领域。同源的动词 emend 与名词 emendation 专门用于这种文本工作，而 amendment 则扩展到了法律与制度。"},{"no":"07","title":"Material added to improve soil","titleCN":"用来改良土壤的材料","definition":"a substance such as compost, lime, or gypsum added to soil to improve its condition for growing plants","definitionCN":"为改善土壤种植条件而加入土壤的物质，如堆肥、石灰或石膏","example":"Compost is a common soil amendment in organic farming.","exampleCN":"堆肥是有机农业中常见的土壤改良剂。","why":"This looks like the 'adding' sense, but the name comes from the purpose, not the motion: the material is called an amendment because it amends the soil, that is, removes its defects. The addition is only the means.","whyCN":"这看起来像“添加”义，但名称来自目的而非动作：这种材料被称为 amendment，是因为它改良土壤，也就是去掉土壤的缺陷。添加只是手段。"},{"no":"08","title":"Reformation of a person's conduct","titleCN":"人的行为改过","definition":"the correction or improvement of a person's behaviour or character, an older sense recorded around 1300","definitionCN":"对一个人的行为或品性的纠正与改善，这一较古老的义项约记录于 1300 年","example":"The programme was designed for the amendment of young offenders.","exampleCN":"该项目是为改造年轻罪犯而设计的。","why":"Around 1300 the word was applied to persons as well as things: a person could be 'corrected, reformed'. The fault is now a habit or a character trait, and removing it is moral improvement.","whyCN":"约 1300 年时，这个词也用于人而不只是物：人可以“被纠正、被改造”。这里的缺陷是习惯或品性，去掉它就是道德上的改善。"},{"no":"09","title":"An addition wearing the name of correction","titleCN":"顶着“修正”之名的追加条款","definition":"in modern legislative usage, a provision attached to a law or bill that is formally an amendment even when it adds new material rather than repairing a fault","definitionCN":"在现代立法用法中，附加到法律或法案上的条款；即使它增加新内容而非修复缺陷，形式上仍叫 amendment","example":"The bill was loaded with amendments that had little to do with correcting anything.","exampleCN":"这项法案被塞进了许多与纠正错误几乎无关的修正条款。","why":"The meaning 'to add to legislation, ostensibly to correct or improve it' is recorded from 1777. The word's form still says 'remove the fault', but practice can turn it into an addition, which is exactly where learners misread amendment as 'extra clause'.","whyCN":"“为立法增加内容、名义上是纠正或改进它”这一用法记录于 1777 年。词形仍在说“去掉缺陷”，但实践可以把它变成追加，这正是学习者把 amendment 误读为“额外条款”的地方。"}],"etymology":{"intro":{"en":"Amendment is amend plus -ment, and amend comes from Old French amender, from Latin emendare 'to correct, free from fault'. The Latin verb is ex- 'out' + menda 'fault, blemish', so the core is removal of a defect, not addition. The same Latin source gives emend and emendation, but those stay in the domain of textual correction, while amendment spread to law, contracts and even soil.","cn":"amendment 是 amend 加 -ment；amend 来自古法语 amender，再上溯拉丁语 emendare“纠正、去掉缺陷”。这个拉丁动词是 ex-“出”加 menda“缺陷、瑕疵”，所以核心是“去掉缺陷”，不是“添加”。同一拉丁来源还给出 emend 与 emendation，但这两个词留在文本校勘领域，而 amendment 扩展到了法律、合同甚至土壤。"},"items":[{"era":"EARLY 13C.","en":"First recorded in English as 'betterment, improvement'. By c.1300 it is also used of persons, meaning 'correction, reformation'. The starting point is not an added clause but a thing made better.","cn":"英语最早记录为“改善、变好”。到 1300 年左右也用于人，意为“纠正、改造”。起点不是追加条款，而是使某物变好。"},{"era":"OLD FRENCH","en":"From Old French amendement 'rectification, correction; advancement, improvement', from amender 'to amend' (12c.), which could mean 'correct, set right, make better, improve'.","cn":"来自古法语 amendement“纠正、改正；促进、改善”，出自 amender“修正”（12 世纪），意为“纠正、摆正、使更好、改进”。"},{"era":"LATIN","en":"Amender goes back to Latin emendare 'to correct, free from fault', built from ex 'out' + menda, mendum 'fault, physical blemish; error'. The prepositional image is pulling the fault out of the thing.","cn":"amender 上溯拉丁语 emendare“纠正、去掉缺陷”，由 ex“出”加 menda、mendum“缺陷、身体瑕疵；错误”构成。其介词意象是把缺陷从东西里拉出来。"},{"era":"PIE","en":"Standard references trace menda to PIE *mend- 'physical defect, fault', said to be the source also of Sanskrit minda 'physical blemish', Old Irish mennar 'stain', Welsh mann 'sign, mark', and Hittite mant- 'something harming'. The set is well attested, though the exact reconstruction is not beyond dispute.","cn":"通行词源资料把 menda 追溯到原始印欧语 *mend-“身体缺陷、过错”，并称它也是梵语 minda“身体瑕疵”、古爱尔兰语 mennar“污点”、威尔士语 mann“记号”与赫梯语 mant-“有害之物”的来源。这组对应有充分记录，但具体构拟并非毫无争议。"},{"era":"SPELLING / MEND","en":"The spelling with a- is unusual but early, and also appears in Provençal and Italian. In English, the senses 'repair; cure' were largely taken over by the shortened offspring mend, formed by dropping the initial a-. That is why amendment now sounds institutional while mend sounds manual.","cn":"带 a- 的拼写不寻常但出现很早，也见于普罗旺斯语和意大利语。在英语里，“修理；治愈”这些义项大多被缩短形式 mend 接管——它去掉了开头的 a-。因此 amendment 现在听起来偏制度，而 mend 听起来偏手工。"},{"era":"LEGAL SHIFT / MODERN","en":"The legal sense 'correction of error in a legal process' is c.1600, and 'alteration of a writ or bill to remove its faults' is the 1690s. The meaning 'to add to legislation, ostensibly to correct or improve it' is recorded from 1777, which marks the drift toward 'added clause'. Modern soil amendment is named for the improvement it brings, not for the act of adding.","cn":"法律义“更正法律程序中的错误”约在 1600 年，“更改令状或法案以去掉缺陷”在 17 世纪 90 年代。“为立法增加内容、名义上纠正或改进它”的用法记录于 1777 年，这标志着向“追加条款”的漂移。现代 soil amendment 是因它带来的改良而得名，而不是因“添加”这个动作。"}]},"similar":{"note":{"en":"The first group separates amendment from the verb it comes from, the plural noun amends, and the scholarly sibling emend; the second compares words that also name changes but do not share the 'remove a fault' core.","cn":"第一组把 amendment 与它的源动词、复数名词 amends、以及学术领域的同源词 emend 分开；第二组比较同样表示“改动”、却不含“去掉缺陷”核心的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"amend","ipa":"/əˈmend/","tag":"base verb","definition":"to correct or improve a text, law, or situation. It is the verb behind amendment; the noun names the act or the resulting document.","definitionCN":"纠正或改进文本、法律或状况。它是 amendment 背后的动词；名词指行为或由此产生的文件。"},{"word":"amends","ipa":"/əˈmendz/","tag":"plural noun","definition":"in the phrase make amends, compensation for a wrong done. It looks like the plural of amend but functions as a fixed noun meaning reparation.","definitionCN":"用于 make amends，意为对造成的过错作出补偿。它看起来像 amend 的复数，但实际是表示“补偿”的固定名词。"},{"word":"emend","ipa":"/ɪˈmend/","tag":"same Latin source","definition":"to correct errors in a text, especially by scholarly editing. It shares Latin emendare with amend but is restricted to textual criticism.","definitionCN":"校订文本中的错误，尤指学术编辑。它与 amend 共享拉丁语 emendare，但只限用于文本校勘。"},{"word":"emendation","ipa":"/ˌiːmenˈdeɪʃn/","tag":"scholarly sibling","definition":"a scholarly correction to a text, or the act of making one. It is the technical counterpart of amendment in textual criticism.","definitionCN":"对文本的学术性校正，或作出这种校正的行为。它是 amendment 在文本校勘领域的技术对应词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"revision","ipa":"/rɪˈvɪʒn/","tag":"broad reworking","definition":"a general re-examination and change of a text or plan. Revision can rework the whole, while an amendment usually targets a specific fault or clause.","definitionCN":"对文本或计划的整体重新审视与改动。revision 可以重做整体，而 amendment 通常针对某一缺陷或条款。"},{"word":"correction","ipa":"/kəˈrekʃn/","tag":"fixing an error","definition":"the act of making something wrong right. Correction is narrower and more factual; a legal amendment can be formal even when nothing is strictly wrong.","definitionCN":"把错误改对的行为。correction 更窄、更偏事实；法律上的 amendment 即使没有严格意义上的错误也可以是正式程序。"},{"word":"alteration","ipa":"/ˌɔːltəˈreɪʃn/","tag":"neutral change","definition":"a change of any kind, with no implication that the result is better. Alteration is neutral, while amendment carries the purpose of removing a fault.","definitionCN":"任何形式的改动，不暗示结果更好。alteration 是中性的，而 amendment 带有“去掉缺陷”的目的。"},{"word":"addendum","ipa":"/əˈdendəm/","tag":"something added","definition":"material added at the end of a document to supplement it. An addendum adds without rewriting; an amendment alters existing wording.","definitionCN":"附加在文件末尾以补充内容的材料。addendum 只追加、不改写；amendment 则改动现有措辞。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: ex- 'out' plus menda 'fault', the amend/emend family, and the shortened mend. No invented 'add' meaning.","cn":"只用真实成分与真实同族词：ex-“出”加 menda“缺陷”、amend/emend 词族，以及缩短形式 mend。不编造“添加”的意思。"},"normal":[{"en":"Latin emendare is ex- 'out' + menda 'fault'. Amendment is literally 'fault-out', the removal of a defect.","cn":"拉丁语 emendare 是 ex-“出”加 menda“缺陷”。amendment 字面上就是“把缺陷拿出去”。"},{"en":"Mend is the shortened child of amend: the same word lost its first a-. That is why you mend a sock but amend a law.","cn":"mend 是 amend 缩短后的子嗣：同一个词丢掉了开头的 a-。所以你补袜子用 mend，改法律用 amend。"},{"en":"Emend and emendation stay with manuscripts; amendment moved into law, contracts and soil.","cn":"emend 与 emendation 留在手稿校勘里；amendment 则走进了法律、合同和土壤。"},{"en":"Soil amendment is named for the improvement it brings to the soil, even though you physically add it.","cn":"soil amendment 是因它给土壤带来的改良而得名，尽管你实际上是把东西加进去。"},{"en":"The modern political 'amendment' can be an added clause, but the word still pretends to be a correction: that gap is the trap.","cn":"现代政治中的 amendment 可能是追加条款，但这个词仍假装自己是在纠错：这个落差正是陷阱。"}],"abstract":[{"en":"Picture a crack in a stone step. Amendment is not a new slab laid on top; it is the work of digging out the bad piece and making the step level again.","cn":"想象石阶上有一道裂缝。amendment 不是在上面铺一块新石板，而是把坏掉的一块挖出来、让台阶重新平整。"},{"en":"The same repair can be done to a sentence, a law, a contract or a person's conduct. What changes is the material, not the gesture.","cn":"同一种修补可以施于句子、法律、合同或一个人的行为。改变的是材料，不是动作。"},{"en":"When the repair is written down and voted on, it becomes a numbered document. When it merely adds, the name survives but the gesture has changed.","cn":"当修补被写下来并付诸表决，它就变成一份编号文件；当它只是追加时，名字留了下来，动作却已经变了。"}]},"examples":[{"en":"The senate passed an amendment to the housing law.","cn":"参议院通过了一项住房法修正案。"},{"en":"We signed a short amendment to the contract last Friday.","cn":"上周五我们签署了一份简短的合同修订协议。"},{"en":"The editor suggested three amendments to the second chapter.","cn":"编辑建议对第二章作三处修订。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿门得门」——阿门牧师把写错的条文改得端正，再推门进去宣读 → amendment 修正、修正案","word":"amendment"},"root":"来自古法语 amendement，上溯 amender 与拉丁语 emendare“去掉缺陷”，字面是 ex-“出”加 menda“缺陷”，核心是“把缺陷拿掉”，而非“添加”。","sensesIntro":{"en":"Nine senses of amendment, all one gesture: a fault is found and taken out. The material can be a manuscript, a constitution, a bill, a writ, a contract, soil or a person's conduct; only in the modern legislative drift does the gesture turn into addition.","cn":"amendment 的九个义项都来自同一个动作：发现缺陷并把它拿出去。材料可以是手稿、宪法、法案、令状、合同、土壤或一个人的行为；只有现代立法的漂移让这个动作变成了追加。"},"semanticMap":{"core":{"en":"CORE IMAGE: a faulty piece is dug out so the whole can stand correct.","cn":"核心意象：把坏掉的一块挖出来，让整体重新站正。"},"chain":["A FAULT IS FOUND","THE FAULT IS REMOVED","THE THING IS MADE BETTER","THE CORRECTION IS FORMALIZED","THE TEXT IS ALTERED","AN ADDITION WEARS THE NAME"],"branches":[{"senses":"01 · 08","en":"THINGS AND PERSONS: a manuscript or a character can both be made better by removing what is wrong.","cn":"物与人：手稿和品性都可以通过去掉错误之处而变好。"},{"senses":"02 · 03","en":"LAW AND LEGISLATURE: a constitution is amended by procedure, and a bill is amended while it is still a draft.","cn":"法律与立法：宪法依程序被修正，法案在仍是草案时被修正。"},{"senses":"04 · 05 · 06","en":"DOCUMENTS: a writ, a contract and a scholarly text each have faults that must be officially removed.","cn":"文件：令状、合同与学术文本各有必须正式去掉的缺陷。"},{"senses":"07","en":"SOIL: the material is named for the improvement it brings, not for the act of adding it.","cn":"土壤：这种材料因带来的改良而得名，而不是因添加的动作而得名。"},{"senses":"09","en":"DRIFT: a clause may be attached purely to add, yet it still travels under the name of correction.","cn":"漂移：条款可能纯粹为追加而附加，却仍顶着“纠正”的名字行走。"}]},"affixes":{"intro":{"en":"Amendment is a transparent English derivative: amend + -ment. The base verb came into English from Old French, and its Latin core is ex- 'out' + menda 'fault'. English then adds -ment, -able, -atory and the negative un- to the finished stem, while the same Latin source also enters through emend and emendation.","cn":"amendment 是一个透明的英语派生词：amend + -ment。基础动词经古法语进入英语，其拉丁内核是 ex-“出”加 menda“缺陷”。英语随后在成品词干上加 -ment、-able、-atory 和否定前缀 un-，而同一拉丁来源还通过 emend 与 emendation 进入英语。"},"latinIntro":{"en":"The Latin family is emendare 'to correct, free from fault', menda/mendum 'fault, blemish', and the preposition ex 'out'. Menda is not related to English mend as a separate root; mend is simply amend with its first syllable lost.","cn":"拉丁词族包括 emendare“纠正、去掉缺陷”、menda/mendum“缺陷、瑕疵”，以及介词 ex“出”。menda 与英语 mend 并非两个独立词根；mend 只是丢掉了第一个音节的 amend。"},"items":[{"word":"amendment","structure":"amend + -ment (noun of action or result)","meaning":"the act of correcting, or the corrected clause itself","meaningCN":"修正行为，或修正后的条款本身（-ment 构成行为或结果名词）","example":"The amendment was accepted without debate.","exampleCN":"该修正案未经辩论就被接受了。"},{"word":"amend","structure":"Old French amender < Latin emendare (ex- out + menda fault)","meaning":"to remove faults from something, to correct","meaningCN":"去掉缺陷；纠正；修订","example":"They agreed to amend the treaty.","exampleCN":"他们同意修订这项条约。"},{"word":"amends","structure":"amend + -s (plural noun, fixed phrase)","meaning":"compensation for a wrong, in make amends","meaningCN":"（make amends）补偿；赔罪（-s 构成的固定名词）","example":"He tried to make amends for the damage.","exampleCN":"他试图为造成的损害作出补偿。"},{"word":"amendable","structure":"amend + -able (can be done)","meaning":"able to be corrected or changed","meaningCN":"可修正的；可修订的（-able 表示能够）","example":"The draft is still amendable at this stage.","exampleCN":"草案在这个阶段仍可修订。"},{"word":"amendatory","structure":"amend + -atory (relating to an action)","meaning":"serving to amend or correct","meaningCN":"修正性的；起修改作用的（-atory 构成形容词）","example":"The amendatory clause changed the payment date.","exampleCN":"这条修正性条款改变了付款日期。"},{"word":"unamended","structure":"un- (not) + amended (past participle as adjective)","meaning":"not corrected or changed","meaningCN":"未修正的；未经修改的（un- 否定 + -ed 形容词）","example":"The unamended text still contains the error.","exampleCN":"未修订的文本仍含有那个错误。"},{"word":"emend","structure":"e- (ex-, out) + mend(um) (fault) — same Latin source","meaning":"to correct a text by scholarly editing","meaningCN":"校订文本；勘正（同源，限于文本校勘）","example":"The editor emended the disputed line.","exampleCN":"编辑勘正了那行有争议的文字。"},{"word":"emendation","structure":"emend + -ation (noun of action)","meaning":"a scholarly correction to a text","meaningCN":"校勘；勘正（-ation 构成行为名词）","example":"The new edition lists every emendation.","exampleCN":"新版列出了每一处校勘。"},{"word":"mend","structure":"shortened from amend by loss of the initial a- (aphetic form)","meaning":"to repair something physical","meaningCN":"修补；缝补（amendment 的缩短亲族，多用于具体物件）","example":"She mended the torn sleeve herself.","exampleCN":"她自己缝好了破了的袖子。"},{"word":"emendatory","structure":"emend + -atory (adjective)","meaning":"intended to correct a text","meaningCN":"意在勘正的；校订性的","example":"The emendatory notes fill thirty pages.","exampleCN":"校订注释占了三页篇幅。"}],"latinEntries":[{"word":"emendare","structure":"ex- (out) + menda (fault) + -are (verb ending)","meaning":"to correct, free from fault","meaningCN":"纠正；去掉缺陷"},{"word":"menda","structure":"Latin noun (also mendum), from PIE *mend- 'defect'","meaning":"fault, physical blemish, error","meaningCN":"缺陷；身体瑕疵；错误"},{"word":"ex-","structure":"Latin preposition and prefix","meaning":"out of, away from","meaningCN":"出；离开"}]}},{"word":"analogy","ipa_uk":"/əˈnælədʒi/","ipa_us":"/əˈnælədʒi/","definition_zh":"类比；类推；相似之处；（数学）比例；同功（生物学）；类推法","definition_en":"a comparison between two things that shows how they correspond in one respect, or the relation of proportion and similarity that such a comparison relies on","core_image":"两组配对摆在一起：A 之于 B，正如 C 之于 D，比例相同","scene":"生物课上，老师把心脏画成水泵。In the biology class, the teacher draws the heart as a pump and explains the analogy: both push a liquid along.","sceneCN":"这里 analogy 是「说明性类比」（第 1 个义项：用已知事物解释相似关系的比较）；句意：生物课上，老师把心脏画成水泵，并解释这个类比：两者都在推动液体。场景要点：黑板上的心脏与水泵简图、两条箭头、粉笔写的 A:B = C:D。","pos":[{"tag":"n.","zh":"类比；类推；相似之处；（数学）比例；同功"}],"collocations":[{"phrase":"draw an analogy between","zh":"在……之间作类比"},{"phrase":"by analogy with","zh":"根据与……的类比"},{"phrase":"a close analogy","zh":"密切的相似关系"},{"phrase":"a false analogy","zh":"错误的类比"},{"phrase":"reason by analogy","zh":"用类推法推理"},{"phrase":"analogy between A and B","zh":"A 与 B 之间的类比"},{"phrase":"on the analogy of","zh":"仿照……的类比"}],"forms":[{"label":"复数（多于一个）","form":"analogies"}],"derivatives":[{"word":"analogous","pos":"adj.","zh":"相似的；类似的；可比拟的"},{"word":"analogue","pos":"n.","zh":"相似物；对应物；模拟信号设备"},{"word":"analogical","pos":"adj.","zh":"类推的；类比性的"},{"word":"analogically","pos":"adv.","zh":"以类推的方式"},{"word":"analogize","pos":"v.","zh":"作类比；用类比说明"}],"senses":[{"no":"01","title":"An explanatory comparison","titleCN":"用来解释的比较","definition":"a comparison between two things that explains one of them by showing how it corresponds to the other in a particular respect","definitionCN":"通过展示两件事在某一方面的对应关系，用其中一件来解释另一件的比较","example":"The teacher drew an analogy between the heart and a pump.","exampleCN":"老师把心脏与水泵作了类比。","why":"Greek analogia began as a relation of proportion, and a proportion always involves two pairs. Here the pairs are heart : blood and pump : water; the comparison is useful because the same relation holds in both.","whyCN":"希腊语 analogia 最初指比例关系，而比例总涉及两组配对。这里是“心脏：血液”和“水泵：水”；比较之所以有用，是因为同一种关系在两组中都成立。"},{"no":"02","title":"The correspondence itself","titleCN":"对应关系本身","definition":"the structural similarity or correspondence between two things, considered as a relation rather than as a rhetorical act","definitionCN":"两件事之间的结构相似或对应，被看作一种关系，而不是一次修辞行为","example":"There is a striking analogy between the two legal systems.","exampleCN":"这两种法律体系之间存在惊人的相似。","why":"The word can name either the act of comparing or the relation that makes the comparison possible. In this sense nobody is speaking; the analogy simply exists between the two systems, like a ratio waiting to be noticed.","whyCN":"这个词既可指比较的动作，也可指使比较成为可能的关系。在这个义项里没有人在说话；类比就存在于两个体系之间，像一组等待被发现的比。"},{"no":"03","title":"A proportion in mathematics","titleCN":"数学上的比例","definition":"in mathematics, an equality of ratios, the original Greek sense of the word","definitionCN":"在数学中，指两个比的相等，即该词最初的希腊语含义","example":"In Greek mathematics, an analogy was an equality of two ratios.","exampleCN":"在希腊数学中，analogy 指两个比相等。","why":"This is the root sense recorded in English in the early 15th century: 'correspondence, proportion'. Before it named a figure of speech, it named the exact relation 2:4 = 3:6, where the same ratio appears twice.","whyCN":"这是英语 15 世纪早期记录的根本义项：“对应、比例”。在它命名一种修辞之前，它命名的是 2:4 = 3:6 这种精确关系——同一个比出现两次。"},{"no":"04","title":"An argument from similarity","titleCN":"由相似性推出的论证","definition":"in logic, an argument that infers a further similarity from known similarities between two cases","definitionCN":"在逻辑中，从两个案例已知的相似之处推出更多相似之处的论证","example":"The argument rests on an analogy with the spread of infectious diseases.","exampleCN":"这一论证依靠与传染病传播的类比。","why":"If two things agree in several respects, one may carry that agreement one step further and conclude that they agree in another. The proportion becomes an inference: the relation found in the known case is carried over to the unknown one.","whyCN":"如果两件事在若干方面一致，人们可以把这种一致再推进一步，断定它们在另一点上也一致。比例于是变成推理：在已知案例中发现的关系被搬运到未知案例。"},{"no":"05","title":"Reasoning by analogy in law","titleCN":"法律上的类推","definition":"the legal method of applying a rule to a new case because the new case is relevantly similar to cases the rule already covers","definitionCN":"因新案件与规则已覆盖的案件存在相关相似性，而把该规则适用于新案件的法律方法","example":"The court extended the rule by analogy to digital records.","exampleCN":"法院通过类推把该规则扩展到数字记录。","why":"Law cannot wait for every new situation to be legislated. When a new case shares the legally relevant features of an old one, the same rule is carried across; the analogy supplies the bridge, and the court must argue that the bridge holds.","whyCN":"法律不能等每一种新情况都被立法覆盖。当新案件与旧案件共享法律上相关的特征时，同一规则就被搬运过去；类比提供桥梁，而法院必须论证这座桥站得住。"},{"no":"06","title":"Similar function without shared ancestry","titleCN":"同功：功能相似而非同源","definition":"in biology, a similarity between structures that perform the same function but did not arise from a common ancestor","definitionCN":"在生物学中，指执行相同功能、却并非来自共同祖先的结构之间的相似","example":"The wings of birds and insects are an analogy, not a homology.","exampleCN":"鸟翼与昆虫翅膀是同功，而不是同源。","why":"Here the correspondence is in function, not in descent. Two lineages independently arrive at the same solution, so the relation is a proportion between roles rather than a family tree; biology keeps analogy and homology strictly apart.","whyCN":"这里的对应在功能上，而不在血统上。两个谱系独立地抵达同一方案，所以这层关系是角色之间的比例，而不是族谱；生物学严格区分同功与同源。"},{"no":"07","title":"Pattern-based change in language","titleCN":"语言中的类推变化","definition":"in linguistics, the reshaping of a word or form on the model of an existing pattern, as when an irregular verb becomes regular","definitionCN":"在语言学中，依照现有模式重塑词或词形，例如不规则动词变得规则","example":"The child said 'goed' by analogy with regular past tenses.","exampleCN":"孩子依照规则过去式的模式说出了“goed”。","why":"The child has found a proportion: walk : walked = go : X. The known pair drives the new form, so analogy here is a pattern carried from old words to a new one, not a comparison made for explanation.","whyCN":"孩子发现了一组比例：walk : walked = go : X。已知的配对驱动了新形式，所以这里的类比是从旧词搬运到新词的模式，而不是为了解释而作的比较。"},{"no":"08","title":"Model-based reasoning in science","titleCN":"科学中的模型类比","definition":"the use of a familiar system as a model for reasoning about an unfamiliar one, as when gas molecules are treated like billiard balls","definitionCN":"把熟悉的系统当作模型来推理陌生系统，例如把气体分子当作台球","example":"Physicists reasoned by analogy from billiard balls to gas molecules.","exampleCN":"物理学家从台球作类比，推及气体分子。","why":"The model supplies a set of relations that can be calculated. The analogy licenses carrying those relations into the target domain, while also warning where the comparison breaks down; it is a tool for thought, not just a figure of speech.","whyCN":"模型提供了一组可以计算的关系。类比允许把这些关系搬运到目标领域，同时也提醒比较在何处失效；它是思维工具，而不只是修辞格。"},{"no":"09","title":"A parallel with past events","titleCN":"与历史事件的平行比较","definition":"a parallel drawn between a present situation and a past one in order to interpret or justify a course of action","definitionCN":"把当前处境与过去处境并置比较，以解释或论证某种行动方针","example":"Politicians drew an analogy between the crisis and the 1930s.","exampleCN":"政客们把这场危机与 1930 年代作了类比。","why":"The two pairs here are present : crisis and past : depression. The past case is treated as a known ratio, and the present is read through it; the analogy can illuminate, but it can also mislead if the relevant features differ.","whyCN":"这里的两组配对是“当下：危机”与“过去：大萧条”。过去案例被当作已知的比，当下则通过它被读取；类比可以照亮问题，但若相关特征不同，也会误导。"}],"etymology":{"intro":{"en":"Analogy comes from Latin analogia, from Greek analogia 'proportion'. It is ana- 'according to, upon' + logos 'ratio', so the -logia here is a relation of ratio, not the '-ology' of a science or field of study. The word is built on proportion, not on 'study of'; logic shares logos but is a different word, and analogous, analogue and analog all belong to the same family.","cn":"analogy 来自拉丁语 analogia，再上溯希腊语 analogia“比例”。它由 ana-“按照、在上”加 logos“比例”构成，所以这里的 -logia 是“比例关系”，不是表示“学科研究”的 -ology。这个词建立在“比例”上，而不是“对……的研究”上；logic 与它共享 logos，却是另一个词，而 analogous、analogue、analog 都属于同一词族。"},"items":[{"era":"EARLY 15C.","en":"First recorded in English as 'correspondence, proportion', from Old French analogie or directly from Latin analogia. The first meaning is mathematical and relational, not explanatory.","cn":"英语最早记录为“对应、比例”，来自古法语 analogie，或直接来自拉丁语 analogia。最初的意思是数学性的、关系性的，而不是解释性的。"},{"era":"GREEK","en":"Greek analogia meant 'proportion', from ana 'upon, according to' + logos 'ratio'. It was a mathematical term, and Plato gave it a wider sense by extending it beyond numerical ratios.","cn":"希腊语 analogia 意为“比例”，由 ana“在上、按照”加 logos“比、比例”构成。它原是一个数学术语，柏拉图把它扩展到数值比例之外，赋予它更宽的含义。"},{"era":"LOGOS / PIE","en":"Logos here means 'ratio', not 'word' or 'science'; it also meant 'word, speech, reckoning'. It goes back to PIE *leg- 'to collect, gather', whose derivatives include 'to speak' on the notion of picking out words. The same logos underlies logic and -logy, but those are separate formations.","cn":"这里的 logos 意为“比例”，而不是“词”或“学科”；它也有“词、言语、计算”之义。它上溯原始印欧语 *leg-“收集、聚拢”，其派生词因“挑出词语”而含“说话”义。同一个 logos 也支撑 logic 与 -logy，但那些是另外的构词。"},{"era":"1540S","en":"The sense 'partial agreement, likeness or proportion between things' is recorded from the 1540s. The mathematical relation is now projected onto any two things that correspond in some respect.","cn":"“事物之间部分一致、相似或成比例”这一义项记录于 16 世纪 40 年代。数学关系此时被投射到任何在某方面对应的事物上。"},{"era":"c. 1600","en":"In logic, analogy becomes 'an argument from the similarity of things in some ways inferring their similarity in others'. The proportion is no longer merely observed; it is used to carry a conclusion across.","cn":"在逻辑中，analogy 变成“由事物在某些方面的相似，推断它们在另一些方面也相似”的论证。比例不再只是被观察到的，而是被用来把结论搬运过去。"},{"era":"MODERN ENGLISH","en":"Specialized senses follow: biological analogy (same function, different ancestry) in the 19th century, linguistic analogy, legal reasoning by analogy, and model-based reasoning in science. Analogous is recorded from the 1640s, analogue from 1826. None of these turns analogy into a field of study; the '-logy' in biology or geology is a different compound of logos.","cn":"专门义项随后出现：19 世纪的生物学同功（功能相同、来源不同）、语言学类推、法律类推，以及科学中的模型推理。analogous 记录于 16 世纪 40 年代，analogue 记录于 1826 年。这些都没有把 analogy 变成一门学科；biology、geology 里的 -logy 是 logos 的另一种构词。"}]},"similar":{"note":{"en":"The first group separates the true family members from analytics, which looks like a -logy word but is built on analysis; the second compares the figures and relations learners most often confuse with analogy.","cn":"第一组把真正的同族词与 analytics 分开——后者看起来像 -logy 词，其实建立在 analysis 上；第二组比较学习者最常与 analogy 混淆的修辞格与关系词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"analogous","ipa":"/əˈnæləɡəs/","tag":"same family","definition":"similar in a way that permits a comparison. It is the adjective from the same Greek root, describing the things rather than the comparison.","definitionCN":"相似到可以进行比较的。它是同一希腊词根派生的形容词，描述事物本身，而不是比较行为。"},{"word":"analogue","ipa":"/ˈænəlɒɡ/","tag":"same family","definition":"a thing that corresponds to another thing, or a continuous physical signal. It is the noun for one member of the pair, not the relation between the pairs.","definitionCN":"与另一事物相对应的事物，或连续物理信号。它是配对中一方的名词，而不是两组配对之间的关系。"},{"word":"analogical","ipa":"/ˌænəˈlɒdʒɪkl/","tag":"derived adjective","definition":"based on or using analogy. It describes reasoning or explanation that proceeds by analogy, while analogy names the relation itself.","definitionCN":"基于或使用类比的。它描述以类比进行的推理或解释，而 analogy 指关系本身。"},{"word":"analytics","ipa":"/ˌænəˈlɪtɪks/","tag":"different root","definition":"the systematic analysis of data. Despite its -ics ending it is built on analysis and lysis 'a loosening', not on logos 'ratio'; it is not a synonym for analogy.","definitionCN":"对数据的系统分析。尽管以 -ics 结尾，它建立在 analysis 与 lysis“松开”上，而不是 logos“比例”上；它不是 analogy 的同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"metaphor","ipa":"/ˈmetəfə/","tag":"figure of speech","definition":"a figure that says one thing is another, without 'like' or 'as'. Metaphor asserts identity, while analogy explicitly maps a relation between two pairs.","definitionCN":"不用 like 或 as，直接把一物说成另一物的修辞。metaphor 断言同一，而 analogy 明确地映射两组配对之间的关系。"},{"word":"simile","ipa":"/ˈsɪməli/","tag":"figure of speech","definition":"a comparison introduced by 'like' or 'as'. A simile points at a resemblance; an analogy usually goes further and works out the correspondence.","definitionCN":"用 like 或 as 引出的比较。simile 只指出相似，analogy 通常更进一步，把对应关系展开。"},{"word":"homology","ipa":"/həˈmɒlədʒi/","tag":"biological opposite","definition":"in biology, similarity due to shared ancestry. It is the opposite of analogy in that domain: homology is same origin, analogy is same function.","definitionCN":"在生物学中，因共同祖先而产生的相似。它在该领域与 analogy 相对：homology 是同源，analogy 是同功。"},{"word":"parallel","ipa":"/ˈpærəlel/","tag":"direct correspondence","definition":"a close correspondence between two events or developments. A parallel is often observed rather than argued, while an analogy is typically used to reason from one case to another.","definitionCN":"两个事件或发展之间的密切对应。parallel 常是被观察到的，而 analogy 通常用来从一个案例推理到另一个案例。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: ana- 'according to' plus logos 'ratio', the analogous/analogue family, and the one look-alike that is not a relative, analytics.","cn":"只用真实成分与真实同族词：ana-“按照”加 logos“比例”、analogous/analogue 词族，以及唯一一个并非同族的形似词 analytics。"},"normal":[{"en":"ana- means 'according to' and logos here means 'ratio'. Analogy is a relation built 'according to a ratio'.","cn":"ana- 意为“按照”，这里的 logos 意为“比例”。analogy 就是“按照一个比”建立起来的关系。"},{"en":"The original image is 2:4 = 3:6: two pairs, one ratio, repeated.","cn":"最初的意象是 2:4 = 3:6：两组配对，同一个比，重复出现。"},{"en":"The same logos gives logic, -logy and dialogue, but each is a different formation; analogy is not 'the study of ana'.","cn":"同一个 logos 给出 logic、-logy、dialogue，但每个都是不同的构词；analogy 不是“对 ana 的研究”。"},{"en":"In biology, analogy is same function without shared ancestry; homology is the opposite.","cn":"在生物学中，analogy 是同功而无共同祖先；homology 正好相反。"},{"en":"Analytics looks like a sibling but comes from analysis and lysis 'a loosening', not from logos.","cn":"analytics 看起来像亲戚，却来自 analysis 与 lysis“松开”，而不是来自 logos。"}],"abstract":[{"en":"Picture two pairs of dancers: the same step is performed by each pair, so watching one teaches you what the other is doing.","cn":"想象两对舞者：每一对跳的是同一个舞步，所以看一对就能明白另一对在做什么。"},{"en":"The same proportion can be observed (a similarity), asserted (an explanation), or used (an argument). Analogy moves along this line from relation to inference.","cn":"同一个比例可以被观察到（相似）、被陈述（解释），或被使用（论证）。analogy 沿着这条线从关系走向推理。"},{"en":"When the proportion is between functions rather than ancestors, biology calls it analogy; when it is between a model and an unknown system, science calls it reasoning by analogy.","cn":"当比例位于功能而非祖先之间，生物学称之为同功；当它位于模型与未知系统之间，科学称之为类比推理。"}]},"examples":[{"en":"The book draws an analogy between the city and a living body.","cn":"这本书把城市比作一个活的躯体。"},{"en":"By analogy with earlier rulings, the judge applied the same principle.","cn":"法官依照先前的裁决作类推，适用了同一原则。"},{"en":"The comparison is only an analogy; the two cases differ in important ways.","cn":"这一比较只是类比；两个案例在重要方面并不相同。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「安纳乐吉」——安纳说乐吉家的水泵就像心脏，两组一比就懂 → analogy 类比、类推","word":"analogy"},"root":"来自拉丁语 analogia，源出希腊语 analogia“比例、对应”，由 ana-“按照”加 logos“比例、理性”构成；这里的 -logia 是“比例关系”，不是“学科研究”。","sensesIntro":{"en":"Nine senses of analogy, all one proportion: two pairs share a ratio. The relation can be observed, used to explain, carried into an argument, applied in law, found in biology, followed in language, used as a scientific model, or projected onto the past.","cn":"analogy 的九个义项都源于同一个比例：两组配对共享一个比。这个关系可以被观察到、用来解释、搬进论证、用于法律、见于生物、跟随于语言、当作科学模型，或投射到过去。"},"semanticMap":{"core":{"en":"CORE IMAGE: two pairs share one ratio, A is to B as C is to D.","cn":"核心意象：两组配对共享一个比，A 之于 B 正如 C 之于 D。"},"chain":["TWO PAIRS","THE SAME RATIO","ONE RESPECT ALIKE","RELATION CARRIED OVER","INFERENCE DRAWN","MEANING TRANSFERRED"],"branches":[{"senses":"03","en":"MATHEMATICS: the original sense is an equality of ratios, where the same proportion appears twice.","cn":"数学：最初义项是两个比相等，同一个比例出现两次。"},{"senses":"01 · 02","en":"COMPARISON AND RELATION: one can perform the comparison, or simply point to the correspondence that already exists.","cn":"比较与关系：人可以作出比较，也可以只指出已经存在的对应。"},{"senses":"04 · 05","en":"REASONING: logic and law both carry a rule from a known case to a similar one.","cn":"推理：逻辑与法律都把规则从已知案例搬运到相似案例。"},{"senses":"06 · 07","en":"SCIENCES OF FORM: biology compares functions without ancestry; linguistics copies a pattern without comparing two objects.","cn":"形式科学：生物学比较功能而不问血统；语言学复制模式而不比较两个对象。"},{"senses":"08 · 09","en":"MODEL AND HISTORY: a familiar system can model an unknown one, and a past crisis can frame a present one.","cn":"模型与历史：熟悉系统可以模拟未知系统，过去危机可以框定当下危机。"}]},"affixes":{"intro":{"en":"Analogy is a Greek compound that reached English through Latin and French: ana- 'according to' + logos 'ratio' + -ia (noun ending). English adds -ous, -ical, -ically and -ize to the finished stem, and the same family gives analogous, analogue and analog. The -logy in analogy is not the productive '-ology' suffix.","cn":"analogy 是一个经拉丁语和法语进入英语的希腊复合词：ana-“按照”加 logos“比例”加 -ia（名词词尾）。英语在成品词干上加 -ous、-ical、-ically、-ize，同一词族给出 analogous、analogue、analog。analogy 里的 -logy 并不是能产的“-ology”后缀。"},"latinIntro":{"en":"The Latin forms are analogia 'proportion' (borrowed from Greek) and analogus 'proportionate' (from Greek analogos). Logos 'ratio, word, reckoning' is the second element; it is not a Latin suffix, and it does not mean 'science' here.","cn":"拉丁形式是 analogia“比例”（借自希腊语）与 analogus“成比例的”（来自希腊语 analogos）。第二成分是 logos“比例、词、计算”；它不是拉丁后缀，在这里也不表示“学科”。"},"items":[{"word":"analogy","structure":"ana- (according to) + logos (ratio) + -ia (noun ending)","meaning":"a proportion or correspondence between two pairs","meaningCN":"两组配对之间的比例或对应（-ia 构成抽象名词）","example":"The analogy between the two markets is limited.","exampleCN":"两个市场之间的相似是有限的。"},{"word":"analogies","structure":"analogy + -ies (plural)","meaning":"more than one comparison or correspondence","meaningCN":"多个类比或对应关系（-ies 为复数）","example":"The lecture was built on three analogies.","exampleCN":"那场讲座建立在三个类比之上。"},{"word":"analogous","structure":"Greek analogos + -ous (adjective)","meaning":"corresponding or similar in a relevant respect","meaningCN":"相似的；可比的（-ous 构成形容词）","example":"The two processes are analogous but not identical.","exampleCN":"这两个过程相似，但并不相同。"},{"word":"analogue","structure":"French analogue < Latin analogus < Greek analogos","meaning":"a corresponding thing; a continuous signal","meaningCN":"对应物；相似物；模拟信号（名词）","example":"The old tape recorder is an analogue of the digital file.","exampleCN":"老式磁带录音机是数字文件的对应物。"},{"word":"analog","structure":"US spelling of analogue, also adjective","meaning":"using continuous signals; a counterpart","meaningCN":"模拟的；对应物（美式拼写，亦作形容词）","example":"The studio still keeps analog equipment.","exampleCN":"录音室仍保留着模拟设备。"},{"word":"analogical","structure":"analogy + -ical (adjective)","meaning":"of or by analogy","meaningCN":"类推的；类比性的（-ical 构成形容词）","example":"The argument is analogical rather than deductive.","exampleCN":"这个论证是类推性的，而不是演绎性的。"},{"word":"analogically","structure":"analogical + -ly (adverb of manner)","meaning":"in a way that uses analogy","meaningCN":"以类推的方式（-ly 构成方式副词）","example":"The two cases were treated analogically.","exampleCN":"两个案例被以类推的方式处理。"},{"word":"analogize","structure":"analogy + -ize (verb)","meaning":"to explain or reason by analogy","meaningCN":"作类比；用类比说明（-ize 构成动词）","example":"He analogized the brain to a network.","exampleCN":"他把大脑类比为一个网络。"},{"word":"disanalogy","structure":"dis- (apart, not) + analogy","meaning":"a relevant difference that weakens an analogy","meaningCN":"削弱类比的相异之处（dis- 否定 + analogy）","example":"The disanalogy lies in the different scales involved.","exampleCN":"相异之处在于所涉尺度不同。"}],"latinEntries":[{"word":"analogia","structure":"Greek analogia 'proportion', borrowed into Latin","meaning":"proportion, correspondence","meaningCN":"比例；对应"},{"word":"analogus","structure":"from Greek analogos 'proportionate'","meaning":"proportionate, corresponding","meaningCN":"成比例的；对应的"},{"word":"logos","structure":"Greek noun 'ratio, word, reckoning', from PIE *leg- 'gather'","meaning":"ratio, proportion; word, account","meaningCN":"比例；词；计算"}]}},{"word":"analytical","ipa_uk":"/ˌænəˈlɪtɪkl/","ipa_us":"/ˌænəˈlɪtɪkl/","definition_zh":"分析的；善于分析的；解析的；（语言学）分析型的；（哲学）分析哲学的","definition_en":"using analysis, that is, breaking a whole into its parts in order to understand it, or showing the careful reasoning characteristic of such a method","core_image":"把一台完整的机器拆成零件摊在桌上，看清每个零件怎样咬合","scene":"实验台上，技术员把水样逐步分离成各种元素。At the bench, the technician uses analytical chemistry to separate the water sample into its elements.","sceneCN":"这里 analytical 是「分析化学的」（第 5 个义项：用化学分析把物质分解成组成成分）；句意：实验台上，技术员用分析化学方法把水样分离成各种元素。场景要点：实验台、滴定管与色谱仪、贴标签的样品瓶、打印出的峰图。","pos":[{"tag":"adj.","zh":"分析的；善于分析的；解析的"}],"collocations":[{"phrase":"analytical method","zh":"分析方法"},{"phrase":"analytical skills","zh":"分析能力"},{"phrase":"analytical mind","zh":"善于分析的头脑"},{"phrase":"analytical approach","zh":"分析式的方法"},{"phrase":"analytical chemistry","zh":"分析化学"},{"phrase":"analytical reasoning","zh":"分析性推理"},{"phrase":"analytical philosophy","zh":"分析哲学"}],"forms":[{"label":"比较级（多音节形容词用 more 构成）","form":"more analytical"}],"derivatives":[{"word":"analytically","pos":"adv.","zh":"以分析的方式；从分析上"},{"word":"analytic","pos":"adj.","zh":"分析的；解析的（同义变体）"},{"word":"analysis","pos":"n.","zh":"分析；解析；分析报告"},{"word":"analyze","pos":"v.","zh":"分析；解析"},{"word":"analyst","pos":"n.","zh":"分析者；分析师"},{"word":"analytics","pos":"n.","zh":"数据分析（技术或方法）"}],"senses":[{"no":"01","title":"Using analysis as a method","titleCN":"把分析作为方法","definition":"using the method of analysis, in which a complex whole is broken into its parts in order to understand it","definitionCN":"使用分析的方法，即把一个复杂的整体拆成各部分以理解它","example":"She took an analytical approach to the problem instead of guessing.","exampleCN":"她没有靠猜，而是用分析的方法处理这个问题。","why":"Greek analyein meant 'to loosen up, release', and analysis is a 'breaking up'. The adjective names any method that performs this loosening: the whole is taken apart before it is explained.","whyCN":"希腊语 analyein 意为“松开、释放”，analysis 就是“拆开”。这个形容词命名任何执行这种松开的办法：整体先被拆开，然后才被解释。"},{"no":"02","title":"A mind that habitually analyses","titleCN":"习惯拆解问题的头脑","definition":"of a person or mind, naturally inclined to examine things by separating them into parts and testing the relations between them","definitionCN":"指人或头脑天生倾向于把事物分开、检验各部分关系的","example":"He has an analytical mind and notices inconsistencies quickly.","exampleCN":"他有一颗善于分析的头脑，很快就能发现不一致之处。","why":"A method can become a habit. When the loosening is done repeatedly by the same person, analytical stops describing a procedure and starts describing a temperament.","whyCN":"方法可以变成习惯。当同一个人反复进行这种“松开”时，analytical 就不再描述一种程序，而开始描述一种性情。"},{"no":"03","title":"A detailed, dissecting account","titleCN":"细致剖析的论述","definition":"of a text, report, or account, organized by careful separation and examination of its subject rather than by mere description","definitionCN":"指文本、报告或叙述按对研究对象的细致分离与检验来组织，而不只是描述","example":"The report offers an analytical account of the market rather than a summary.","exampleCN":"这份报告对市场作了分析性论述，而不是只给摘要。","why":"The product of analysis carries the name of the method. An account is called analytical when you can see the joints where the subject was cut, instead of a smooth surface of description.","whyCN":"分析的产物继承了方法的名字。当你能看见研究对象被切开的接缝、而不是一层平滑的描述表面时，这篇论述就被称为 analytical。"},{"no":"04","title":"The analytic tradition in philosophy","titleCN":"哲学中的分析传统","definition":"relating to analytic philosophy, the tradition that treats the clarification of language and logical analysis as central to philosophy","definitionCN":"与（英美）分析哲学有关的，这一传统把语言澄清与逻辑分析视为哲学的核心","example":"Analytical philosophy often begins with a careful distinction between two uses of a word.","exampleCN":"分析哲学常常从一个词两种用法的细致区分开始。","why":"If philosophy's troubles come from confused language, then the cure is to loosen the words and see their parts. The school is named for exactly that procedure, which is why analytical here names a tradition, not just a style.","whyCN":"如果哲学的麻烦来自混乱的语言，那么解药就是松开词语、看清其部件。这个学派正是因这一程序得名，所以这里的 analytical 命名的是一种传统，而不只是一种风格。"},{"no":"05","title":"Chemistry that resolves substances","titleCN":"把物质分解开来的化学","definition":"relating to analytical chemistry, the branch that identifies and measures the components of a substance","definitionCN":"与分析化学有关的，这一分支鉴定并测量物质的组成成分","example":"Analytical chemistry identified traces of lead in the water sample.","exampleCN":"分析化学检出了水样中的微量铅。","why":"This is the most literal scientific use: the sample is physically resolved into its elements. The loosening is no longer a metaphor but a laboratory operation with instruments and numbers.","whyCN":"这是最字面的科学用法：样品被实际分解成元素。松开不再是比喻，而是有仪器、有数值的实验室操作。"},{"no":"06","title":"Languages built from separate words","titleCN":"用独立词构成的语言","definition":"in linguistics, describing a language that shows grammatical relations with particles and word order rather than with inflection","definitionCN":"在语言学中，描述一种用虚词和词序而非屈折变化来表达语法关系的语言","example":"Chinese is often described as an analytic language.","exampleCN":"汉语常被描述为分析型语言。","why":"Such a language does not fuse grammar into the word's endings; it keeps the pieces separate and lets word order do the joining. The term was applied to languages from 1830, and it extends the image of parts laid out rather than merged.","whyCN":"这种语言不把语法融进词尾，而是让各个成分保持分离，由词序来完成连接。这一术语从 1830 年起用于语言，它延伸了“零件摊开而非熔合”的意象。"},{"no":"07","title":"Geometry and solutions by algebra","titleCN":"用代数处理的几何与解","definition":"in mathematics, using algebraic or calculus methods to study figures and to obtain exact solutions, as in analytic geometry","definitionCN":"在数学中，用代数或微积分方法研究图形并获得精确解，如解析几何","example":"Analytic geometry turns a curve into an equation.","exampleCN":"解析几何把一条曲线变成一个方程。","why":"A geometric whole is broken into coordinates and variables, then reassembled as an equation. The method earns the name because the figure is resolved into measurable parts that can be calculated.","whyCN":"一个几何整体被拆成坐标与变量，再被重组成方程。这种方法配得上这个名字，因为图形被分解成可计算的量。"},{"no":"08","title":"Jung's analytical psychology","titleCN":"荣格的分析心理学","definition":"relating to analytical psychology, Carl Jung's school, which analyses unconscious material such as symbols, dreams and archetypes","definitionCN":"与分析心理学有关的，即荣格学派，分析象征、梦与原型等无意识材料","example":"The seminar introduced Jung's analytical psychology.","exampleCN":"研讨课介绍了荣格的分析心理学。","why":"The psyche is treated as a whole that must be taken apart into its images and complexes. The school takes the same word as chemistry and philosophy, but the material being loosened is inner life.","whyCN":"心灵被当作一个必须拆成意象与情结的整体。这个学派与化学、哲学共用同一个词，但被松开的材料是内在生活。"},{"no":"09","title":"Reasoning measured by tests","titleCN":"被测验衡量的推理能力","definition":"of a test, task, or skill, requiring step-by-step logical reasoning rather than memory or intuition","definitionCN":"指测验、任务或技能要求逐步的逻辑推理，而不是记忆或直觉","example":"The exam tests analytical reasoning rather than vocabulary.","exampleCN":"这项考试考查分析性推理，而不是词汇。","why":"Once the method is a trainable skill, institutions begin to measure it. Analytical reasoning names the ability to take a stated whole apart, inspect the steps, and reach a conclusion that can be checked.","whyCN":"当方法成为可训练的 skill，机构就开始测量它。analytical reasoning 指把一个给定的整体拆开、检查各步骤、并得出可核查结论的能力。"}],"etymology":{"intro":{"en":"Analytical is the adjective from Greek analytikos 'skilled in dissolving', which goes back to analyein 'to loosen, release' (ana- 'up, back, throughout' + lysis 'a loosening'). It entered English in the 1520s through Medieval Latin analyticus, while the noun analysis is first recorded only in the 1580s. So English analytical is not simply 'analysis + -al': the adjective arrived first from the Greek-Latin family, and analyze followed around 1600.","cn":"analytical 是希腊语 analytikos“善于拆解的”的形容词，后者上溯 analyein“松开、释放”（ana-“向上、向后、贯穿”加 lysis“松开”）。它于 16 世纪 20 年代经中世纪拉丁语 analyticus 进入英语，而名词 analysis 直到 16 世纪 80 年代才被记录。所以英语的 analytical 并非简单的“analysis + -al”：形容词先随希腊—拉丁词族进来，analyze 约在 1600 年才出现。"},"items":[{"era":"1520S","en":"First recorded in English as 'employing analytic methods', formed with -al from Medieval Latin analyticus, which goes back to Greek analytikos. The adjective is therefore older in English than the noun analysis.","cn":"英语最早记录为“使用分析方法的”，由 -al 加中世纪拉丁语 analyticus 构成，后者上溯希腊语 analytikos。因此在英语里，形容词比名词 analysis 更古老。"},{"era":"GREEK","en":"Analytikos 'analytical' comes from analytos 'dissolved', from analyein 'to unloose, release, set free'. In Aristotle the verb also means 'to analyze', and the image is loosening a complex thing until its parts separate.","cn":"analytikos“分析的”来自 analytos“被分解的”，再上溯 analyein“松开、释放、使自由”。在亚里士多德那里，这个动词也有“分析”之义；意象是把复杂之物松开，直到各部分分离。"},{"era":"MORPHOLOGY","en":"Anayein is ana- 'up, back, throughout' + lysis 'a loosening', from lyein 'to unfasten', from PIE *leu- 'to loosen, divide, cut apart'. The second element is lysis, not a piece that sounds like 'nalysis'; the word is not 'a + nalysis'.","cn":"anayein 是 ana-“向上、向后、贯穿”加 lysis“松开”，后者来自 lyein“解开”，再上溯原始印欧语 *leu-“松开、分开、切开”。第二成分是 lysis，而不是某个听起来像“nalysis”的部分；这个词不是“a + nalysis”。"},{"era":"1580S / c. 1600","en":"The noun analysis is recorded from the 1580s, via Medieval Latin from Greek, meaning 'resolution of anything complex into simple elements'. The verb analyze follows c.1600 from French analyser, which was itself formed from the noun analyse.","cn":"名词 analysis 记录于 16 世纪 80 年代，经中世纪拉丁语来自希腊语，意为“把复杂之物分解成简单元素”。动词 analyze 约在 1600 年随后出现，来自法语 analyser，而法语动词本身又由名词 analyse 构成。"},{"era":"1830","en":"In linguistics, the term is applied from 1830 to languages that use particles and auxiliaries rather than inflections to show grammatical relations. The same adjective now names a language type, not a procedure.","cn":"在语言学中，这一术语从 1830 年起用于那些用虚词和助词而非屈折变化来表示语法关系的语言。同一个形容词此时命名的是一种语言类型，而不是一种程序。"},{"era":"MODERN ENGLISH","en":"Analytical chemistry resolves compounds into elements; analytic philosophy clarifies language and argument; analytical psychology analyses symbols and dreams; analytic geometry turns figures into equations. Keep the family apart: analytics is analysis + -ics (data analysis), not a plural of analytic, and analogical comes from analogy and logos, not from lysis.","cn":"分析化学把化合物分解成元素；分析哲学澄清语言与论证；分析心理学分析象征与梦；解析几何把图形变成方程。要把词族分清：analytics 是 analysis + -ics（数据分析），不是 analytic 的复数；analogical 来自 analogy 与 logos，而不是来自 lysis。"}]},"similar":{"note":{"en":"The first group separates the short variant analytic, the unrelated-looking analytics, the verb analyze and the look-alike analogical; the second compares adjectives that also praise careful thinking but do not mean 'breaking into parts'.","cn":"第一组区分短变体 analytic、看似无关却形近的 analytics、动词 analyze，以及形似而不同源的 analogical；第二组比较同样称赞“细致思考”、却不含“拆成部分”之意的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"analytic","ipa":"/ˌænəˈlɪtɪk/","tag":"same family","definition":"the shorter variant of analytical, used especially in fixed terms such as analytic philosophy and analytic geometry. It is the same adjective, not a different root.","definitionCN":"analytical 的较短变体，尤用于 analytic philosophy、analytic geometry 等固定术语。它是同一个形容词，不是另一个词根。"},{"word":"analytics","ipa":"/ˌænəˈlɪtɪks/","tag":"different formation","definition":"the systematic analysis of data, especially by software. It is analysis + -ics, a separate noun, not the plural of analytic.","definitionCN":"对数据的系统分析，尤指借助软件。它是 analysis + -ics 构成的独立名词，不是 analytic 的复数。"},{"word":"analyze","ipa":"/ˈænəlaɪz/","tag":"same family, verb","definition":"to break something down in order to understand it. It is the verb of the family, while analytical is the adjective describing the method or the mind.","definitionCN":"为理解某物而把它拆解。它是该词族的动词，而 analytical 是描述方法或头脑的形容词。"},{"word":"analogical","ipa":"/ˌænəˈlɒdʒɪkl/","tag":"different root","definition":"based on analogy. It looks close to analytical but comes from analogy and logos 'ratio', not from analysis and lysis 'a loosening'.","definitionCN":"基于类比的。它看起来接近 analytical，却来自 analogy 与 logos“比例”，而不是来自 analysis 与 lysis“松开”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"systematic","ipa":"/ˌsɪstəˈmætɪk/","tag":"ordered procedure","definition":"done according to a fixed system or plan. Systematic stresses order and coverage; analytical stresses taking the whole apart to see how it works.","definitionCN":"按固定体系或计划进行的。systematic 强调秩序与覆盖面；analytical 强调把整体拆开以看清其运作。"},{"word":"logical","ipa":"/ˈlɒdʒɪkl/","tag":"valid inference","definition":"following the rules of valid reasoning. Logical stresses the correctness of the steps; analytical stresses the act of decomposition that produces the steps.","definitionCN":"遵循有效推理规则的。logical 强调步骤的正确性；analytical 强调产生这些步骤的拆解动作。"},{"word":"critical","ipa":"/ˈkrɪtɪkl/","tag":"evaluative judgment","definition":"examining something in order to judge its merits and faults. Critical adds evaluation; analytical examination can remain neutral and descriptive.","definitionCN":"为判断优缺点而审视某物。critical 多了一层评价；分析性审视可以保持中性、描述性。"},{"word":"detailed","ipa":"/ˈdiːteɪld/","tag":"full of detail","definition":"including many facts or small features. Detailed says there is a lot of information; analytical says the information is organized by reasoning about parts and relations.","definitionCN":"包含许多事实或细微特征的。detailed 说的是信息量大；analytical 说的是信息按部分与关系的推理被组织起来。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: ana- 'up, back' plus lysis 'a loosening', the analysis/analyze family, and the two look-alikes that are not relatives, analytics and analogical.","cn":"只用真实成分与真实同族词：ana-“向上、向后”加 lysis“松开”、analysis/analyze 词族，以及两个并非同族的形似词 analytics 与 analogical。"},"normal":[{"en":"ana- means 'up, back, throughout' and lysis means 'a loosening'. Analytical is the habit of loosening a whole until its parts show.","cn":"ana- 意为“向上、向后、贯穿”，lysis 意为“松开”。analytical 就是把整体松开、直到部件露出来的习惯。"},{"en":"The same *leu- root gives analysis, paralysis, dissolve and solve, so analytical belongs with 'loosening', not with 'learning'.","cn":"同一 *leu- 词根给出 analysis、paralysis、dissolve、solve，所以 analytical 属于“松开”这一族，与“学习”无关。"},{"en":"The adjective is older in English than the noun: analytical 1520s, analysis 1580s, analyze c.1600. It is not simply analysis + -al.","cn":"在英语里形容词比名词更老：analytical 是 16 世纪 20 年代，analysis 是 80 年代，analyze 约 1600 年。它不是简单的 analysis + -al。"},{"en":"Three specialized homes: analytical chemistry (resolves substances), analytic geometry (turns figures into equations), analytical psychology (dissects the psyche).","cn":"三个专门归宿：分析化学（分解物质）、解析几何（把图形变成方程）、分析心理学（剖析心灵）。"},{"en":"analytics is analysis + -ics, a data noun; analogical is analogy + -ical, from logos. Neither is a form of analytical.","cn":"analytics 是 analysis + -ics 的数据名词；analogical 是 analogy + -ical，来自 logos。两者都不是 analytical 的形式。"}],"abstract":[{"en":"Picture a pocket watch taken apart on a cloth: every wheel is separated, and only then can you say how the watch keeps time.","cn":"想象一只怀表被拆开摊在布上：每个齿轮都被分开，只有这时你才能说出这只表如何走时。"},{"en":"The same loosening can be done to water, to a sentence, to a curve, to a dream or to an argument. The material changes; the gesture does not.","cn":"同一种松开可以施于水样、句子、曲线、梦或论证。材料变了，动作没变。"},{"en":"When the gesture becomes reliable enough to teach and test, it turns into a skill, and analytical reasoning becomes something an exam can measure.","cn":"当这个动作可靠到可以教授和测验，它就变成一种技能，analytical reasoning 也就成了考试可以测量的东西。"}]},"examples":[{"en":"Her analytical skills made her the first person to spot the error.","cn":"她的分析能力使她成为第一个发现错误的人。"},{"en":"The paper gives an analytical overview of the last ten years of research.","cn":"这篇论文对过去十年的研究作了分析性综述。"},{"en":"Analytical chemistry can detect amounts far below what the eye can see.","cn":"分析化学能检测到远低于肉眼可见量的物质。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「安纳利替扣」——安纳利把扣子拆成一根根线来查，看清它怎么扣上 → analytical 分析的、解析的","word":"analytical"},"root":"来自希腊语 analytikos，经中世纪拉丁语 analyticus 进入英语；上溯 analyein“松开、拆解”（ana-“向上／拆开”加 lysis“松开”），核心是“拆开整体以看清结构”。","sensesIntro":{"en":"Nine senses of analytical, all one gesture: loosen a whole until its parts are visible. The whole can be a problem, a mind, a report, a language, a compound, a figure, a psyche or a test item.","cn":"analytical 的九个义项都来自同一个动作：把整体松开，直到各部分可见。这个整体可以是问题、头脑、报告、语言、化合物、图形、心灵或一道考题。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whole is loosened until its parts lie open to view.","cn":"核心意象：把整体松开，直到各部件摊开可见。"},"chain":["A WHOLE","LOOSEN IT","TAKE IT APART","SEE THE PARTS","TRACE THEIR RELATIONS","EXPLAIN THE WHOLE"],"branches":[{"senses":"01 · 03","en":"METHOD AND PRODUCT: the procedure of analysis, and the written account that shows the joints it cut.","cn":"方法与产物：分析的程序，以及显露出切割接缝的书面论述。"},{"senses":"02 · 09","en":"THE MIND AND THE TEST: a settled habit of analysis, and the measurable skill that institutions test.","cn":"头脑与测验：稳定的分析习惯，以及机构测量的可测量技能。"},{"senses":"04 · 08","en":"SCHOOLS: analytic philosophy and analytical psychology are named for the same loosening, applied to language and to the psyche.","cn":"学派：分析哲学与分析心理学因同一种松开而得名，分别施于语言与心灵。"},{"senses":"05 · 07","en":"EXACT SCIENCES: chemistry resolves substances into elements, and geometry resolves figures into equations.","cn":"精确科学：化学把物质分解成元素，几何把图形分解成方程。"},{"senses":"06","en":"LANGUAGE TYPE: an analytic language keeps its grammatical pieces separate instead of fusing them into endings.","cn":"语言类型：分析型语言让语法成分保持分离，而不是熔进词尾。"}]},"affixes":{"intro":{"en":"Analytical is analytic + -al; analytic came from Medieval Latin analyticus, from Greek analytikos. The living English suffix here is -al, while the Greek core is ana- 'up, back' + lysis 'a loosening'. English also forms analytically with -ly, analysis and analyze by other routes, and analytics with -ics.","cn":"analytical 是 analytic + -al；analytic 来自中世纪拉丁语 analyticus，再上溯希腊语 analytikos。这里活的英语后缀是 -al，而希腊内核是 ana-“向上、向后”加 lysis“松开”。英语还以 -ly 构成 analytically，以其他路径构成 analysis 与 analyze，并以 -ics 构成 analytics。"},"latinIntro":{"en":"Medieval Latin analyticus is the immediate source, and Latin analysis (from Greek) is the noun. Greek analyein 'to loosen' and lysis 'a loosening' are the deepest elements; they are Greek, not Latin, and are listed here because they explain the family.","cn":"直接来源是中世纪拉丁语 analyticus，名词则是拉丁语 analysis（来自希腊语）。最深层的成分是希腊语 analyein“松开”与 lysis“松开”；它们是希腊语而非拉丁语，列在这里是因为它们解释了整个词族。"},"items":[{"word":"analytical","structure":"analytic + -al (adjective), from Medieval Latin analyticus < Greek analytikos","meaning":"of or using analysis","meaningCN":"分析的；使用分析方法的（-al 构成形容词）","example":"The team needs a more analytical approach.","exampleCN":"团队需要一种更重分析的方法。"},{"word":"analytic","structure":"Medieval Latin analyticus < Greek analytikos","meaning":"the shorter variant, common in fixed terms","meaningCN":"较短变体，常见于固定术语（同义）","example":"Analytic geometry links algebra and shape.","exampleCN":"解析几何把代数与图形联系起来。"},{"word":"analytically","structure":"analytical + -ly (adverb of manner)","meaning":"in an analytical manner","meaningCN":"以分析的方式（-ly 构成方式副词）","example":"She read the proposal analytically.","exampleCN":"她以分析的方式读了这份提案。"},{"word":"analysis","structure":"ana- (up, back, throughout) + lysis (a loosening) + -is (noun ending)","meaning":"the resolution of a complex whole into its elements","meaningCN":"把复杂整体分解成元素；分析（-is 构成名词）","example":"The analysis took three weeks.","exampleCN":"这项分析花了三周。"},{"word":"analyze","structure":"French analyser, formed from analyse 'analysis'","meaning":"to break something down in order to understand it","meaningCN":"分析；拆解以理解（动词）","example":"They analyzed the samples in the lab.","exampleCN":"他们在实验室分析了样品。"},{"word":"analyst","structure":"French analyste, from analyser","meaning":"a person who analyses","meaningCN":"分析者；分析师（-ist 类人物名词）","example":"The analyst compared the two markets.","exampleCN":"分析师比较了两个市场。"},{"word":"analytics","structure":"analysis + -ics (noun of a field or practice)","meaning":"the systematic analysis of data","meaningCN":"数据分析（-ics 构成领域名词，不是 analytic 的复数）","example":"The company hired a data analytics team.","exampleCN":"公司雇了一个数据分析团队。"},{"word":"analyticity","structure":"analytic + -ity (noun of quality)","meaning":"the property of being analytic, especially of a statement true by meaning","meaningCN":"分析性；解析性（-ity 构成性质名词）","example":"Philosophers debated the analyticity of such statements.","exampleCN":"哲学家们争论这类陈述的分析性。"},{"word":"psychoanalytical","structure":"psycho- (mind) + analytical","meaning":"relating to psychoanalysis","meaningCN":"精神分析的（psycho- 心灵 + analytical）","example":"He wrote a psychoanalytical reading of the novel.","exampleCN":"他写了一篇对这部小说的精神分析解读。"}],"latinEntries":[{"word":"analyticus","structure":"Medieval Latin, from Greek analytikos","meaning":"analytical, skilled in dissolving","meaningCN":"分析的；善于拆解的"},{"word":"analysis","structure":"Latin from Greek analysis, ana- + lysis","meaning":"a breaking up, a loosening","meaningCN":"分解；松开"},{"word":"anayein","structure":"Greek verb: ana- (up, back) + lyein (to unfasten)","meaning":"to unloose, release, set free","meaningCN":"松开；释放；使自由（希腊语来源）"}]}},{"word":"analytically","ipa_uk":"/ˌænəˈlɪtɪkli/","ipa_us":"/ˌænəˈlɪtɪkli/","definition_zh":"以分析的方式；从分析上；通过对整体的拆解；（数学）解析地（求得精确解）","definition_en":"in a manner that uses analysis, by breaking a whole into its parts, or by means of an exact analytical method rather than an approximate one","core_image":"不是绕着整台机器猜，而是把零件逐一摊开、顺着咬合处往下查","scene":"工程师没有画图试凑，而是在纸上解出方程，直接得到曲线的精确交点。Instead of plotting and guessing, the engineer solves the equation analytically and gets the exact intersection.","sceneCN":"这里 analytically 是「解析地、用精确解法」（第 9 个义项：用解析方法求得闭式精确解，而不是数值近似）；句意：工程师没有画图试凑，而是在纸上解析求解，直接得到精确交点。场景要点：草稿纸上的方程、被划掉的数值表、铅笔写出的根号解、合上的计算器。","pos":[{"tag":"adv.","zh":"以分析的方式；从分析上；解析地"}],"collocations":[{"phrase":"think analytically","zh":"以分析的方式思考"},{"phrase":"approach a problem analytically","zh":"用分析的方法处理问题"},{"phrase":"solve analytically","zh":"解析地求解（求得精确解）"},{"phrase":"analytically rigorous","zh":"分析上严谨的"},{"phrase":"analytically trained","zh":"受过分析训练的"},{"phrase":"examine something analytically","zh":"对某事件作分析性考察"},{"phrase":"argue analytically","zh":"以分析的方式论证"}],"forms":[{"label":"副词形态","form":"analytically（无屈折变化）"}],"derivatives":[{"word":"analytical","pos":"adj.","zh":"分析的；善于分析的；解析的"},{"word":"analytic","pos":"adj.","zh":"分析的；解析的（同义变体）"},{"word":"analysis","pos":"n.","zh":"分析；解析"},{"word":"analyze","pos":"v.","zh":"分析；解析"},{"word":"analyst","pos":"n.","zh":"分析者；分析师"}],"senses":[{"no":"01","title":"In an analytical manner","titleCN":"以分析的方式","definition":"in a way that uses analysis rather than intuition, habit, or mere description","definitionCN":"以使用分析、而非直觉、习惯或单纯描述的方式","example":"The committee examined the proposal analytically, point by point.","exampleCN":"委员会逐点地、以分析的方式审查了这项提案。","why":"The -ly suffix turns the adjective into a manner adverb: whatever analytical describes, analytically tells you how it is done. The default sense is simply 'by analysis', with no special field attached.","whyCN":"-ly 后缀把形容词变成方式副词：analytical 描述什么，analytically 就说明这件事是怎样做的。默认义项就是“通过分析”，不附带特定领域。"},{"no":"02","title":"By taking the problem apart","titleCN":"把问题拆开来看","definition":"by separating a complex problem into smaller parts and dealing with each part in turn","definitionCN":"把复杂问题拆成较小部分，并依次处理每一部分","example":"Instead of reacting to the whole crisis, they worked analytically through each cause.","exampleCN":"他们没有对整个危机作出反应，而是分析性地逐一处理每个成因。","why":"This makes the core image explicit: the whole is loosened before anything is said about it. The adverb marks the order of work — parts first, whole later — rather than the topic.","whyCN":"这里把核心意象说清楚了：在谈论整体之前，先把它松开。副词标记的是工作的顺序——先部分、后整体——而不是话题。"},{"no":"03","title":"With step-by-step reasoning","titleCN":"一步一步地推理","definition":"by reasoning from premises to conclusion in explicit, checkable steps","definitionCN":"以明确、可核查的步骤从前提到结论进行推理","example":"She argued analytically, showing how each claim followed from the evidence.","exampleCN":"她以分析的方式论证，说明每个论断如何从证据推出。","why":"Analysis produces parts, and reasoning links them. When the links are laid out one by one, the manner is analytical in the argumentative sense, close to 'logically' but with the added image of decomposed steps.","whyCN":"分析产生部分，推理连接部分。当这些连接被逐一摆出时，这种方式就是论证意义上的 analytical，接近 logically，但多了一层“步骤被拆开”的意象。"},{"no":"04","title":"By chemical analysis","titleCN":"通过化学分析","definition":"by means of analytical chemistry, identifying or measuring the components of a sample","definitionCN":"借助分析化学，鉴定或测量样品的组成成分","example":"The water was tested analytically for lead and nitrate.","exampleCN":"水样经过分析检测，测定了铅和硝酸盐。","why":"In the laboratory the loosening is literal: reagents and instruments separate the sample into measurable components. Analytically here tells you the method used, not the frame of mind.","whyCN":"在实验室里，松开是字面意义上的：试剂与仪器把样品分离成可测量的成分。这里的 analytically 说明所用方法，而不是心态。"},{"no":"05","title":"From an analytical discipline's perspective","titleCN":"从分析学科的角度","definition":"in the manner or perspective of an analytical discipline, such as linguistics or philosophy, rather than a descriptive or historical one","definitionCN":"以分析学科（如语言学或哲学）的方式或视角，而非描述性或历史性视角","example":"The novel has been studied analytically by linguists interested in tense.","exampleCN":"这部小说被关注时态的语言学家以分析的方式研究过。","why":"A discipline trains its members in a method, and the adverb then names the perspective they bring. The same object can be studied historically, descriptively or analytically; the last one asks how its parts are put together.","whyCN":"一个学科用某种方法训练成员，副词随后命名他们带来的视角。同一个对象可以被历史地、描述地或分析地研究；最后一种追问它的各部分如何拼合。"},{"no":"06","title":"Listening in a probing way","titleCN":"以探究、拆解的方式倾听","definition":"of a person, in a manner that sorts claims from evidence and tests what is being said","definitionCN":"指人以区分论断与证据、检验对方所说内容的方式","example":"He listened analytically, separating what was known from what was assumed.","exampleCN":"他以分析的方式倾听，把已知与假定分开。","why":"When the method becomes a personal habit, the adverb describes behaviour rather than procedure. The listener is not cold; he is dividing the speech into claims that can be checked.","whyCN":"当方法变成个人习惯，副词描述的就是行为而非程序。这样的听者并不冷漠；他只是把对方的话分成可核查的论断。"},{"no":"07","title":"In a dissecting written style","titleCN":"以剖析式的写作风格","definition":"of writing or speech, in a style that lays out components and relations instead of narrating or describing","definitionCN":"指写作或言谈以铺陈成分与关系、而非叙述或描写的风格","example":"The report describes the policy analytically, with each assumption exposed.","exampleCN":"报告以分析的方式描述这项政策，把每个假设都暴露出来。","why":"A style can carry a method. When the sentences are arranged by parts and relations rather than by time or scene, the writing is said to proceed analytically; the adverb modifies the texture of the text.","whyCN":"风格可以承载方法。当句子按部分与关系、而不是按时间或场景排列时，这种写作就被说成以分析的方式展开；副词修饰的是文本的质地。"},{"no":"08","title":"In the manner of analytic philosophy","titleCN":"以分析哲学的方式","definition":"by the methods of analytic philosophy, clarifying concepts and arguments through logical and linguistic analysis","definitionCN":"以分析哲学的方法，通过逻辑与语言分析澄清概念和论证","example":"The question was treated analytically, beginning with the meaning of 'cause'.","exampleCN":"这个问题被以分析的方式处理，先从“原因”一词的意义开始。","why":"Here the adverb invokes a named tradition. The loosening is applied to concepts: a word is separated into its uses, and a question is answered only after its terms are clarified.","whyCN":"这里的副词唤起一个有名有姓的传统。松开被施于概念：一个词被分成各种用法，问题只有在术语被澄清之后才被回答。"},{"no":"09","title":"By an exact mathematical solution","titleCN":"以精确的数学解法","definition":"in mathematics, by obtaining an exact closed-form solution through analysis, as opposed to a numerical approximation","definitionCN":"在数学中，通过分析得到闭式精确解，而不是数值近似","example":"The equation can be solved analytically, so no iteration is needed.","exampleCN":"这个方程可以解析求解，因此不需要迭代。","why":"In this technical contrast, analysis means deriving the answer from the structure of the equation, not sampling numbers. The adverb marks the route to the result: exact derivation rather than stepwise approximation.","whyCN":"在这一技术性对照里，分析指从方程的结构推出答案，而不是取数值样本。副词标记通往结果的路线：精确推导，而非逐步逼近。"}],"etymology":{"intro":{"en":"Analytically is analytical plus the adverbial suffix -ly. Analytical came into English in the 1520s from Medieval Latin analyticus, from Greek analytikos, whose base analyein means 'to loosen, release' (ana- 'up, back' + lysis 'a loosening'). The adverb therefore says 'in the manner of that loosening'. The suffix -ly is native English, not Greek or Latin: it goes back to Old English -lice and Proto-Germanic *-liko-, cognate with lich 'body' and like.","cn":"analytically 是 analytical 加副词后缀 -ly。analytical 于 16 世纪 20 年代从中世纪拉丁语 analyticus 进入英语，再上溯希腊语 analytikos，其词基 analyein 意为“松开、释放”（ana-“向上、向后”加 lysis“松开”）。因此副词说的是“以那种松开的方式”。后缀 -ly 是英语本族成分，不是希腊语或拉丁语：它上溯古英语 -lice 与原始日耳曼语 *-liko-，与 lich“身体”和 like 同源。"},"items":[{"era":"1520S","en":"The base adjective analytical is first recorded in English as 'employing analytic methods', via Medieval Latin analyticus from Greek analytikos. The adverb depends on this adjective, so its history begins here.","cn":"基础形容词 analytical 最早记录于 16 世纪 20 年代，意为“使用分析方法的”，经中世纪拉丁语 analyticus 来自希腊语 analytikos。副词依附于这个形容词，因此它的历史从这里开始。"},{"era":"OLD ENGLISH / PROTO-GERMANIC","en":"The adverbial -ly comes from Old English -lice, from Proto-Germanic *-liko-, and is cognate with lich 'body' and identical with like (adj.). The modern form emerged in late Middle English, probably under the influence of Old Norse -liga.","cn":"副词后缀 -ly 来自古英语 -lice，再上溯原始日耳曼语 *-liko-，与 lich“身体”同源，并与形容词 like 同形。现代形式出现于中古英语晚期，可能受古北欧语 -liga 的影响。"},{"era":"16C–17C","en":"Analytically is the regular manner adverb from analytical. The etymonline entry for the adverb itself could not be retrieved for this batch because the site returned a bot-check page; the analytical entry lists 'Related: Analytically' but gives no separate date, so the first recorded date of the adverb remains uncertain (unconfirmed here).","cn":"analytically 是由 analytical 规则构成的方式副词。本批检索时，etymonline 的副词条目因网站返回人机验证页而未能取得；analytical 条目只列出“Related: Analytically”，未给单独年代，因此该副词的首见年代在本批中仍属存疑（未获确认）。"},{"era":"17C–19C","en":"The adverb spreads with the sciences. Mathematics contrasts solving a problem analytically (exact derivation) with solving it numerically, and analytical chemistry makes 'tested analytically' a laboratory phrase.","cn":"这个副词随科学扩展。数学把“解析地求解”（精确推导）与“数值地求解”相对，分析化学则让“以分析方式检测”成为实验室用语。"},{"era":"19C–20C","en":"Academic English uses analytically for the perspective of a discipline: a text can be read analytically rather than historically or descriptively. Analytic philosophy and analytical psychology supply two named traditions in which the adverb is routine.","cn":"学术英语用 analytically 表示某一学科的视角：一部文本可以被分析地阅读，而不是历史地或描述地阅读。分析哲学与分析心理学提供了两个有名有姓的传统，副词在其中是常规用法。"},{"era":"MODERN ENGLISH","en":"The adverb is a manner word, not a separate lexical root. It must not be confused with analogically, which comes from analogy and logos 'ratio', or with analytics, a data noun from analysis + -ics. Both look close and neither shares the lysis element.","cn":"这个副词是方式词，不是独立的词根。它不能与 analogically 混淆——后者来自 analogy 与 logos“比例”；也不能与 analytics 混淆——后者是 analysis + -ics 的数据名词。两者形近，且都不含 lysis 成分。"}]},"similar":{"note":{"en":"The first group separates the adjective base, its short variant, the data noun analytics and the look-alike analogically; the second compares adverbs that also describe careful thought but do not mean 'by decomposition'.","cn":"第一组区分形容词基础、其短变体、数据名词 analytics，以及形似而不同源的 analogically；第二组比较同样描述细致思考、却不含“拆解”之意的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"analytical","ipa":"/ˌænəˈlɪtɪkl/","tag":"adjective base","definition":"using analysis. It describes a method, mind or account, while analytically describes how an action is performed.","definitionCN":"使用分析的。它描述方法、头脑或论述，而 analytically 描述动作怎样进行。"},{"word":"analytic","ipa":"/ˌænəˈlɪtɪk/","tag":"short variant","definition":"the shorter form of the same adjective, common in terms such as analytic geometry. It is not the adverb and cannot replace analytically.","definitionCN":"同一形容词的较短形式，常见于 analytic geometry 等术语。它不是副词，不能替换 analytically。"},{"word":"analytics","ipa":"/ˌænəˈlɪtɪks/","tag":"different formation","definition":"the systematic analysis of data. It is a noun from analysis + -ics, not an adverb and not the plural of analytic.","definitionCN":"对数据的系统分析。它是 analysis + -ics 的名词，不是副词，也不是 analytic 的复数。"},{"word":"analogically","ipa":"/ˌænəˈlɒdʒɪkli/","tag":"different root","definition":"by analogy, or in a manner based on analogy. It looks almost identical in shape but comes from logos 'ratio', not from lysis 'a loosening'.","definitionCN":"以类比的方式，或基于类比的。它的词形几乎相同，却来自 logos“比例”，而不是 lysis“松开”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"logically","ipa":"/ˈlɒdʒɪkli/","tag":"valid inference","definition":"in a way that follows the rules of valid reasoning. Logically stresses the correctness of inference, while analytically stresses the decomposition that supplies the steps.","definitionCN":"以遵循有效推理规则的方式。logically 强调推理的正确性，而 analytically 强调提供这些步骤的拆解。"},{"word":"systematically","ipa":"/ˌsɪstəˈmætɪkli/","tag":"ordered coverage","definition":"in an ordered, methodical way that covers everything according to a system. Systematically can be mechanical, while analytically requires taking the subject apart.","definitionCN":"按体系有序、周全地。systematically 可以是机械的，而 analytically 要求把对象拆开。"},{"word":"methodically","ipa":"/məˈθɒdɪkli/","tag":"step-by-step order","definition":"in a careful, step-by-step manner. Methodically stresses orderly procedure, not the separation of a whole into parts.","definitionCN":"以谨慎、逐步的方式。methodically 强调有序程序，而不强调把整体分成部分。"},{"word":"critically","ipa":"/ˈkrɪtɪkli/","tag":"evaluative judgment","definition":"in a way that examines and judges merits and faults. Critically adds evaluation, while analytically can remain a neutral dissection.","definitionCN":"以审视并评判优缺点的方式。critically 多了一层评价，而 analytically 可以是中性的剖析。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: analytical + -ly, the native English -ly from Old English -lice, and the two look-alikes built on logos and on -ics.","cn":"只用真实成分与真实同族词：analytical + -ly、来自古英语 -lice 的本族后缀 -ly，以及两个建立在 logos 和 -ics 上的形似词。"},"normal":[{"en":"analytical + -ly: the suffix changes an adjective into a manner adverb, so analytically means 'in that analytical way'.","cn":"analytical + -ly：后缀把形容词变成方式副词，所以 analytically 意为“以那种分析的方式”。"},{"en":"-ly is native English, from Old English -lice, cognate with lich 'body' and like. It is not a Greek suffix, even when the base is Greek.","cn":"-ly 是英语本族后缀，来自古英语 -lice，与 lich“身体”和 like 同源。即使词基是希腊语，它也不是希腊后缀。"},{"en":"The base family: analytical 1520s, analysis 1580s, analyze c.1600. The adverb rides on the adjective.","cn":"基础词族：analytical 是 16 世纪 20 年代，analysis 是 80 年代，analyze 约 1600 年。副词依附于形容词。"},{"en":"Mathematics separates 'solve analytically' (exact) from 'solve numerically' (approximate).","cn":"数学把“解析地求解”（精确）与“数值地求解”（近似）分开。"},{"en":"analogically is built on logos 'ratio'; analytics is built on -ics. Neither contains lysis 'a loosening'.","cn":"analogically 建立在 logos“比例”上；analytics 建立在 -ics 上。两者都不含 lysis“松开”。"}],"abstract":[{"en":"Picture a hand loosening a knot: the rope does not disappear, it separates into strands that can be followed one by one.","cn":"想象一只手在松开一个结：绳子没有消失，而是分成可以逐根追踪的股。"},{"en":"The same loosening can be done in thought, in argument, in a lab, in a text or in an equation. The adverb says the action is done that way, not that the topic is analysis.","cn":"同一种松开可以在思考、论证、实验室、文本或方程中进行。副词说的是动作以这种方式完成，而不是话题属于分析。"},{"en":"In mathematics the manner becomes a choice of route: exact derivation through the structure, instead of walking numerically toward an answer.","cn":"在数学里，这种方式变成路线选择：顺着结构作精确推导，而不是用数值一步步逼近答案。"}]},"examples":[{"en":"She prefers to think analytically before making a decision.","cn":"她喜欢在作决定之前先分析性地思考。"},{"en":"The two compounds were compared analytically in the same laboratory.","cn":"这两种化合物在同一实验室里经过分析比较。"},{"en":"The model can be solved analytically, which makes it useful for teaching.","cn":"这个模型可以解析求解，因此很适合教学。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「安纳利替扣里」——安纳利把扣子拆开后，一颗一颗地查进去 → analytically 以分析的方式","word":"analytically"},"root":"由形容词 analytical 加副词后缀 -ly 构成，字面是“以分析的方式”；analytical 又来自希腊语 analytikos“善于拆解的”，其词基 analyein 意为“松开、拆解”。","sensesIntro":{"en":"Nine senses of analytically, all one manner: something is done by loosening a whole and working through its parts. The field can be a problem, an argument, a lab sample, a discipline, a listener, a text, a philosophical tradition or an equation.","cn":"analytically 的九个义项都来自同一种方式：把整体松开，再顺着各部分去做。领域可以是问题、论证、实验室样品、学科、听者、文本、哲学传统或方程。"},"semanticMap":{"core":{"en":"CORE IMAGE: a knot is loosened and its strands are followed one by one.","cn":"核心意象：把结松开，再一股一股地顺着查下去。"},"chain":["ADJECTIVE BASE","ADD -LY","IN THAT MANNER","BY ANALYSIS","PART AFTER PART","EXACT OR CHECKABLE RESULT"],"branches":[{"senses":"01 · 02 · 07","en":"GENERAL MANNER: the method itself, the order of taking a problem apart, and the dissecting texture of a text.","cn":"一般方式：方法本身、拆解问题的顺序，以及文本的剖析质地。"},{"senses":"03 · 06","en":"REASONING AND THE MIND: explicit steps in argument, and a listener who separates claims from evidence.","cn":"推理与头脑：论证中的明确步骤，以及把论断与证据分开的听者。"},{"senses":"04 · 05","en":"DISCIPLINES: a sample tested in the lab, and a text studied from an analytical perspective.","cn":"学科：实验室里被检测的样品，以及从分析视角被研究的文本。"},{"senses":"08","en":"PHILOSOPHY: concepts are clarified by separating a word into its uses before a question is answered.","cn":"哲学：在回答问题之前，先把一个词分成各种用法以澄清概念。"},{"senses":"09","en":"MATHEMATICS: the manner becomes a route, exact derivation instead of numerical approximation.","cn":"数学：方式变成路线，精确推导而非数值近似。"}]},"affixes":{"intro":{"en":"Analytically is analytical + -ly, and analytical is analytic + -al. The Greek-Latin core is ana- 'up, back' + lysis 'a loosening'; the English -ly is a native adverbial suffix from Old English -lice. So the word mixes a borrowed Greek base with a native English ending, which is why its form is so regular.","cn":"analytically 是 analytical + -ly，而 analytical 是 analytic + -al。希腊—拉丁内核是 ana-“向上、向后”加 lysis“松开”；英语的 -ly 是来自古英语 -lice 的本族副词后缀。因此这个词是 borrowed 的希腊词基加本族英语词尾，这也解释了它为何形式如此规则。"},"latinIntro":{"en":"The Latin source is analyticus (Medieval Latin) and analysis (from Greek). The deepest elements, analyein and lysis, are Greek. There is no separate Latin adverb here: the -ly ending is English.","cn":"拉丁来源是 analyticus（中世纪拉丁语）与 analysis（来自希腊语）。最深层的成分 analyein 与 lysis 是希腊语。这里没有独立的拉丁副词：-ly 词尾是英语的。"},"items":[{"word":"analytically","structure":"analytical + -ly (adverb of manner)","meaning":"in an analytical manner","meaningCN":"以分析的方式（-ly 构成方式副词）","example":"They reviewed the data analytically.","exampleCN":"他们以分析的方式审查了数据。"},{"word":"analytical","structure":"analytic + -al (adjective)","meaning":"of or using analysis","meaningCN":"分析的；使用分析的（-al 构成形容词）","example":"An analytical reading reveals the hidden premise.","exampleCN":"分析性的阅读揭示了隐藏的前提。"},{"word":"analytic","structure":"Medieval Latin analyticus < Greek analytikos","meaning":"the short variant of analytical","meaningCN":"analytical 的短变体（同义）","example":"Analytic geometry is taught in the first year.","exampleCN":"解析几何在第一年讲授。"},{"word":"analysis","structure":"ana- (up, back, throughout) + lysis (a loosening) + -is","meaning":"the breaking up of a whole into parts","meaningCN":"把整体分解成部分；分析","example":"The analysis revealed three separate causes.","exampleCN":"分析揭示了三个各自独立的成因。"},{"word":"analyze","structure":"French analyser, from analyse 'analysis'","meaning":"to break something down to understand it","meaningCN":"分析；拆解以理解","example":"The software analyzes the sentence structure.","exampleCN":"该软件分析句子结构。"},{"word":"analyst","structure":"French analyste, from analyser","meaning":"one who analyses","meaningCN":"分析者；分析师","example":"The analyst wrote a short report.","exampleCN":"分析师写了一份简短报告。"},{"word":"analytics","structure":"analysis + -ics (field or practice)","meaning":"data analysis as a practice","meaningCN":"数据分析（作为实践或领域）","example":"Analytics showed a drop in traffic.","exampleCN":"数据分析显示流量下降。"},{"word":"-ly","structure":"Old English -lice < Proto-Germanic *-liko-, cognate with lich and like","meaning":"adverbial suffix meaning 'in the manner of'","meaningCN":"副词后缀，意为“以……的方式”（本族英语成分）","example":"The suffix turns analytical into analytically.","exampleCN":"这个后缀把 analytical 变成 analytically。"},{"word":"analogically","structure":"analogical + -ly; base from analogy + logos (ratio)","meaning":"by analogy; a different root from analytically","meaningCN":"以类比的方式（来自 logos，与 analytically 不同源）","example":"The two cases were treated analogically.","exampleCN":"两个案例被以类比的方式处理。"}],"latinEntries":[{"word":"analyticus","structure":"Medieval Latin, from Greek analytikos","meaning":"analytical, skilled in dissolving","meaningCN":"分析的；善于拆解的"},{"word":"analysis","structure":"Latin from Greek analysis, ana- + lysis","meaning":"a breaking up, a loosening","meaningCN":"分解；松开"},{"word":"anayein","structure":"Greek verb: ana- (up, back) + lyein (to unfasten)","meaning":"to unloose, release, set free","meaningCN":"松开；释放；使自由（希腊语来源）"}]}},{"word":"ancestral","ipa_uk":"/ænˈsestrəl/","ipa_us":"/ænˈsestrəl/","definition_zh":"祖先的；祖传的；与先人有关的；（物种或语言）原始类型的","definition_en":"relating to ancestors, inherited from them, or marking an early form from which later ones developed","core_image":"一条向身后延伸的家族链，链的最前端站着先人；今天的一切都从那里传来","scene":"清明时，一家人回到祖屋，擦亮刻着先人名字的木牌，摆上供品。At Qingming, the family returns to the old house, polishes the wooden tablets with the names of the dead and lays out offerings in the ancestral hall.","sceneCN":"这里 ancestral 是「祖先祭祀的、先人的」（第 5 个义项：祭祀与纪念先人的）；句意：清明时一家人回到祖屋，在祖先祠堂里擦亮刻有先人名字的木牌并摆上供品。场景要点：祖屋的木门、刻名字的牌位、供桌、香炉、擦拭牌位的手。","pos":[{"tag":"adj.","zh":"祖先的；祖传的；原始类型的"}],"collocations":[{"phrase":"ancestral home","zh":"祖居；祖宅"},{"phrase":"ancestral land","zh":"祖辈的土地"},{"phrase":"ancestral lineage","zh":"祖先谱系"},{"phrase":"ancestral traits","zh":"祖先性状；遗传特征"},{"phrase":"ancestral worship","zh":"祖先崇拜"},{"phrase":"ancestral rites","zh":"祭祖仪式"},{"phrase":"ancestral species","zh":"祖先物种"}],"forms":[{"label":"比较级（更多用 more 构成）","form":"more ancestral"},{"label":"最高级（更多用 most 构成）","form":"most ancestral"}],"derivatives":[{"word":"ancestor","pos":"n.","zh":"祖先；原型"},{"word":"ancestry","pos":"n.","zh":"血统；世系"},{"word":"ancestress","pos":"n.","zh":"女祖先"},{"word":"ancestrally","pos":"adv.","zh":"在祖先方面；按祖先的方式"},{"word":"ancestorial","pos":"adj.","zh":"祖先的（ancestral 的替代形式）"}],"senses":[{"no":"01","title":"Belonging to the people before you","titleCN":"属于先人的：指向家族中的前人","definition":"relating to the ancestors from whom a person or family is descended","definitionCN":"与某个人或家族所出自的先人有关的","example":"A faded ancestral portrait hangs above the fireplace.","exampleCN":"壁炉上方挂着一幅褪色的先人画像。","why":"The suffix -al changes the concrete noun ancestor ('a forebear') into a relation word: it does not name the person but marks anything that points back to that person.","whyCN":"后缀 -al 把具体名词 ancestor（先人）变成关系形容词：它不指那个人，而是标记任何指向那个人的事物。"},{"no":"02","title":"Inherited through the family line","titleCN":"沿家族线继承的","definition":"received from ancestors, especially as property, traits, or rights","definitionCN":"从先人那里继承而来的，尤指财产、特征或权利","example":"The orchard came with an ancestral right to draw water from the stream.","exampleCN":"这座果园附带一项从溪中取水的祖传权利。","why":"Inheritance is how the family chain continues materially: what the earlier generation held passes to the later one, so 'of ancestors' comes to mean 'handed down from them'.","whyCN":"继承是家族链在物质上延续的方式：上一代握有的东西传给下一代，于是“属于先人的”引申为“由先人传下的”。"},{"no":"03","title":"Marking the original home","titleCN":"标记家族原乡的","definition":"describing the place where a family or people originated and to which it still traces itself","definitionCN":"描述某个家族或民族发源、并且至今仍以之为归属的地方","example":"Her ancestral village sits at the end of a narrow valley.","exampleCN":"她的祖籍村落在一条狭窄山谷的尽头。","why":"A lineage needs an anchor in space. The first generation is attached to a 'there', and later members call that place ancestral even if they have never lived there.","whyCN":"谱系需要在空间里有一个锚点。第一代人与某个“那里”绑定，后来的成员即使从未在那里生活，也会称那个地方为祖居。"},{"no":"04","title":"Of an earlier biological form","titleCN":"早期生物形态的","definition":"relating to an earlier species, population, or character from which later forms evolved","definitionCN":"与后来形态由之演化而来的早期物种、种群或性状有关的","example":"The fossil shows the ancestral wing structure of modern birds.","exampleCN":"这块化石显示了现代鸟类祖先的翅膀结构。","why":"The family-tree image transfers from people to species: the form lower on the branch is the ancestor of the forms above it, so its traits are ancestral.","whyCN":"家族树的意象从人转移到物种：分支下方的形态是上方形态的祖先，因此它的性状就是“祖先的”。"},{"no":"05","title":"Of rites and objects for the dead","titleCN":"祭祀先人的：仪式与器物的","definition":"belonging to the ceremonies and objects used to honor dead forebears","definitionCN":"属于纪念已故先人的仪式和器物的","example":"Incense smoke rose from the ancestral tablets in the hall.","exampleCN":"祠堂里，祖先牌位前升起袅袅香烟。","why":"Honoring the dead gives the abstract link a concrete occasion. The tablet, hall, and rite are all 'of the ancestors' because they exist to address them.","whyCN":"对死者的纪念给抽象的联系一个具体场合。牌位、祠堂和仪式都“属于祖先”，因为它们的存在就是为了向先人致意。"},{"no":"06","title":"Established by inherited custom","titleCN":"由祖制沿袭下来的","definition":"long established by inherited practice rather than by present choice","definitionCN":"长期由继承下来的做法确立，而非由当下的选择确立","example":"The village still settles grazing disputes by ancestral custom.","exampleCN":"这个村子仍按祖传习俗解决放牧纠纷。","why":"Custom can be inherited like land. If a rule is followed because the fathers followed it, it carries ancestral authority rather than merely being old.","whyCN":"习俗可以像土地一样被继承。若一条规则因为父辈遵守而被遵守，它就带有祖制的权威，而不只是“古老”。"},{"no":"07","title":"An earlier model of a later thing","titleCN":"后世之物的早期原型","definition":"being an earlier model or version from which a later thing is metaphorically descended","definitionCN":"作为后来事物在比喻意义上所由来的早期模型或版本","example":"The mechanical calculator is an ancestral device of the computer.","exampleCN":"机械计算器是计算机的祖先式装置。","why":"Once 'descent' is used for anything that develops from something else, machines and institutions can have ancestors too; ancestral then means 'earlier in the line'.","whyCN":"一旦“传承”被用于任何由他物发展而来的事物，机器和制度也可以有祖先；ancestral 于是表示“在谱系中更早的”。"},{"no":"08","title":"Of a people's shared origin","titleCN":"族群共同源头的","definition":"relating to the shared origin of a nation, tribe, or ethnic group","definitionCN":"与民族、部落或族群共同来源有关的","example":"The exhibition maps the ancestral territory of the coastal tribes.","exampleCN":"展览标出了沿海各部落的祖居地域。","why":"Ancestry can be imagined collectively: a whole people shares one set of forebears, so a land or language can be called ancestral for the group, not just for a family.","whyCN":"血统可以被集体地想象：整个民族共享一批先人，因此一片土地或一种语言可以对群体而言是“祖辈的”，而不只对一个家庭而言。"},{"no":"09","title":"The reconstructed root of a language family","titleCN":"语系中重构的原始形式","definition":"naming the oldest attested or reconstructed form from which a family of languages descends","definitionCN":"指一个语系所由来的最古老的有证或重构形式","example":"The ancestral form of the word is marked with an asterisk in the dictionary.","exampleCN":"这个词的原始形式在词典里用星号标出。","why":"Linguistic family trees put a reconstructed root at the base; because later languages 'descend' from it, the root is called ancestral even though no speaker ever used it.","whyCN":"语言谱系树把重构的词根放在底部；因为后来的语言从它“传承”而来，这个词根就被称为原始形式，尽管从未有人真的使用过它。"}],"etymology":{"intro":{"en":"Ancestral is an adjective formed in English from ancestor, not an inherited Latin adjective. Its root is literal: ante- 'before' + cedere 'to go', so an ancestor is 'one who goes before'. Two common notes need correcting: ancient is not from antiquus but from ante via Vulgar Latin *anteanus; and descendant is not a cedere word (it is de- + scandere 'climb'). The opposite-direction cedere relative is successor.","cn":"ancestral 是英语在 ancestor 之后构成的形容词，不是直接继承的拉丁形容词。它的词根很字面：ante-“在前”+ cedere“走”，所以 ancestor 就是“走在前面的人”。两个常见说法需要纠正：ancient 并非来自 antiquus，而是经俗拉丁语 *anteanus 来自 ante；descendant 也不是 cedere 词（它是 de- + scandere“爬”）。真正与 cedere 反向对应的是 successor。"},"items":[{"era":"1520s","en":"First recorded as 'pertaining to ancestors'. It was borrowed from Old French ancestrel (Anglo-French auncestrel), itself from ancestre 'ancestor'.","cn":"最早记录为“与祖先有关的”。它借自法语 ancestrel（盎格鲁法语 auncestrel），后者又来自 ancestre“祖先”。"},{"era":"OLD FRENCH","en":"Old French ancestre / ancessor (12c.) meant 'ancestor, forebear, forefather'. The English noun ancestor is recorded from c.1300 and took its current form in the early 15c.","cn":"古法语 ancestre / ancessor（12 世纪）意为“祖先、先人、父辈”。英语名词 ancestor 约在 1300 年有记录，15 世纪早期形成现在的拼写。"},{"era":"LATE LATIN","en":"Ancestre goes back to Late Latin antecessor 'predecessor', literally 'fore-goer', an agent noun from the past-participle stem of antecedere 'to precede'.","cn":"ancestre 可追溯到晚期拉丁语 antecessor“前任”，字面义为“先行者”，是 antecedere“走在前面”过去分词词干构成的施动名词。"},{"era":"LATIN","en":"antecedere = ante 'before' + cedere 'to go, yield'. The same cedere underlies predecessor and successor; successor (sub- 'after, near' + cedere) is the true opposite-direction relative, while descendant is not.","cn":"antecedere = ante“在前”+ cedere“走、让步”。同一 cedere 也构成 predecessor 与 successor；successor（sub-“在后、靠近”+ cedere）才是真正反向对应的同根词，而 descendant 不是。"},{"era":"PIE","en":"ante is traced to PIE *ant- 'front, forehead'; cedere to PIE *ked- 'to go, yield'. The reconstructions are standard, but the exact path through the Late Latin forms is not certain.","cn":"ante 被追溯到原始印欧语 *ant-“前面、额头”；cedere 追溯到 *ked-“走、让步”。这些重构是通行的，但经过晚期拉丁语形式的具体路径并不完全确定。"},{"era":"MODERN ENGLISH","en":"The suffix -al (Latin -alis, through French) turns the noun into an adjective. Ancestorial (1650s) is an alternative. Note that ancient comes from ante + -anus, not from antiquus, and that ancestor and ancient share only the *ant- 'before' root, not the cedere part.","cn":"后缀 -al（拉丁 -alis，经法语）把名词变成形容词。ancestorial（17 世纪 50 年代）是替代形式。注意 ancient 来自 ante + -anus，而不是 antiquus；ancestor 与 ancient 只共享 *ant-“前”这个词根，并不共享 cedere 部分。"}]},"similar":{"note":{"en":"The first group separates true derivatives and look-alike forms from ancestral itself; the second compares words that are close in meaning but not interchangeable.","cn":"第一组把真正的派生形式与形近形式同 ancestral 本身分开；第二组比较意思接近但不能互换的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ancestor","ipa":"/ˈænsestə/","tag":"base noun","definition":"the person from whom one is descended; the noun that ancestral is formed from. It names a person, while ancestral describes what points back to that person.","definitionCN":"某人所出自的先人；ancestral 由之构成的名词。它指一个人，而 ancestral 描述指向那个人的事物。"},{"word":"ancestry","ipa":"/ˈænsestri/","tag":"related collective noun","definition":"the whole line of descent, not one person. It is a collective noun and cannot replace ancestor in a sentence about a single forebear.","definitionCN":"整条血统世系，而不是某一个人。它是集合名词，在指单个先人的句子里不能替代 ancestor。"},{"word":"ancient","ipa":"/ˈeɪnʃənt/","tag":"look-alike, different formation","definition":"very old or belonging to the distant past. It comes from Latin ante 'before' through Vulgar Latin *anteanus; it is not a derivative of ancestor, and its source is not antiquus (that is antique).","definitionCN":"很古老的；属于遥远过去的。它经俗拉丁语 *anteanus 来自拉丁语 ante“前”；它不是 ancestor 的派生词，来源也不是 antiquus（后者给出 antique）。"},{"word":"ancestress","ipa":"/ˈænsestrəs/","tag":"derived feminine","definition":"a female ancestor. The -ess suffix marks feminine gender, not a different root.","definitionCN":"女祖先。-ess 后缀只标记女性，不表示不同词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hereditary","ipa":"/həˈredɪtəri/","tag":"inherited by law or biology","definition":"passing from parents to children through genes or legal inheritance. It stresses transmission, while ancestral stresses the people at the other end of the line.","definitionCN":"通过基因或法定继承从父母传给子女。它强调传递过程，而 ancestral 强调这条线另一端的先人。"},{"word":"familial","ipa":"/fəˈmɪliəl/","tag":"family-wide","definition":"relating to a family as a social unit, especially shared traits or disease. It need not reach back generations, unlike ancestral.","definitionCN":"与作为社会单位的家庭有关，尤指共享的特征或疾病。它不必追溯到许多代之前，这一点与 ancestral 不同。"},{"word":"inherited","ipa":"/ɪnˈherɪtɪd/","tag":"received","definition":"received from a predecessor, especially a quality or condition. It is the result word; ancestral names the source relation.","definitionCN":"从前人那里接收来的，尤指某种品质或状况。它是结果词，而 ancestral 命名的是来源关系。"},{"word":"primordial","ipa":"/praɪˈmɔːdiəl/","tag":"earliest","definition":"existing from the very beginning of the world or of a species. It is much stronger and more remote than ancestral.","definitionCN":"自世界或物种之初就存在的。它比 ancestral 强烈得多，也遥远得多。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: ancestor is ante- 'before' + cedere 'to go', the suffix -al makes the relation adjective, and the cedere family supplies the opposite-direction successor.","cn":"只用真实成分与真实同族词：ancestor 是 ante-“前”+ cedere“走”，后缀 -al 构成关系形容词，cedere 词族则提供反向的 successor。"},"normal":[{"en":"ancestor is ante- 'before' + cedere 'to go': the one who goes before.","cn":"ancestor 是 ante-“在前”+ cedere“走”：走在前面的人。"},{"en":"-al means 'pertaining to', so ancestral simply means 'of the one who went before'.","cn":"-al 意为“与……有关的”，所以 ancestral 就是“属于走在前面那个人的”。"},{"en":"Ancestor and ancient both start with ante 'before', but ancient is not a form of ancestor; antique is the word from antiquus.","cn":"ancestor 与 ancient 都以 ante“前”为源，但 ancient 不是 ancestor 的形式；来自 antiquus 的是 antique。"},{"en":"Successor, from sub- + cedere, is the cedere relative meaning 'one who comes after'; descendant is from scandere 'to climb', not cedere.","cn":"successor 由 sub- + cedere 构成，是表示“后来者”的 cedere 同根词；descendant 来自 scandere“爬”，不是 cedere。"},{"en":"Ancestral home, ancestral land and ancestral rites are fixed phrases for three branches: place, property, and ritual.","cn":"ancestral home、ancestral land、ancestral rites 是三条分支的固定搭配：地点、财产与仪式。"}],"abstract":[{"en":"Picture a relay race in which every runner hands a baton forward; the runner behind you is ancestral, and the baton is what was inherited.","cn":"想象一场接力赛，每个跑者把接力棒向前交；你身后的那位跑者是“祖先”，接力棒就是被继承下来的东西。"},{"en":"A family tree drawn on paper: every line above your name is an ancestor, and the whole upper part of the tree is your ancestry.","cn":"纸上画的一棵家谱树：你名字上方的每一条线都是 ancestor，整棵树上方的部分就是你的 ancestry。"},{"en":"The same tree can hold species or languages: the root is the ancestral form, and every branch above it descends from that root.","cn":"同一棵树也能容纳物种或语言：根是 ancestral form，上方每一根枝条都从那个根传承而来。"}]},"examples":[{"en":"Her ancestral home stands at the end of the lane.","cn":"她的祖宅立在巷子尽头。"},{"en":"The researchers compared the ancestral species with its modern relatives.","cn":"研究人员把那个祖先物种与现代近亲作了比较。"},{"en":"The festival includes ancestral rites that date back centuries.","cn":"这个节庆包含可追溯数百年的祭祖仪式。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「安祖传」——‘安’家的东西祖上传下来 → ancestral 祖传的、祖先的（只借音，不表词源）","word":"ancestral"},"root":"源自拉丁语 antecessor“先行者”，由 ante“在前”+ cedere“走”构成，核心是“走在前面的人”；-al 使其成为形容词。","sensesIntro":{"en":"Nine uses of ancestral all point backwards along a line: a person, a possession, a homeland, a species, a rite, a custom, a machine, a people, or a language can all have something standing earlier behind it.","cn":"ancestral 的九个用法都沿着一条线向后指：一个人、一份财产、一片故乡、一个物种、一种仪式、一种习俗、一台机器、一个民族或一种语言，背后都可以站着更早的东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: everything that points back along a line to the ones who went before.","cn":"核心意象：一切沿着一条线指向“走在前面的人”的事物。"},"chain":["BLOOD LINE","EARLIER GENERATION","HANDED DOWN","PLACE OF ORIGIN","EARLY FORM","PREDECESSOR"],"branches":[{"senses":"01 · 02","en":"PERSONS AND PROPERTY: the relation to a forebear, and what that forebear handed down.","cn":"人与财产：与先人的关系，以及先人传下的东西。"},{"senses":"03 · 08","en":"PLACES AND PEOPLES: a homeland anchors a family, and a shared homeland anchors a whole people.","cn":"地点与族群：故乡为家族提供锚点，共同的故土为一个民族提供锚点。"},{"senses":"04 · 09","en":"BIOLOGY AND LANGUAGE: species and language families are drawn as trees, with an ancestral form at the base.","cn":"生物与语言：物种和语系都被画成树，底部是 ancestral form。"},{"senses":"05 · 06","en":"RITUAL AND CUSTOM: the dead are addressed through rites, and their practice becomes inherited authority.","cn":"仪式与习俗：人们通过仪式向死者致意，而这些做法又成为继承下来的权威。"},{"senses":"07","en":"METAPHORICAL LINEAGE: machines and institutions can have earlier models, so the family-tree image extends beyond blood.","cn":"比喻谱系：机器和制度也可以有早期模型，家族树意象因此超出血缘。"}]},"affixes":{"intro":{"en":"Ancestral is a living English adjective built from ancestor + -al. The base noun is a French and Latin loan whose parts are frozen: ante- 'before' + cedere 'to go'. English adds -al, -ess, -ly and -ial to the finished family, while the same Latin root also arrives in predecessor, successor and antecedent.","cn":"ancestral 是由 ancestor + -al 构成的活的英语形容词。基础名词是法语和拉丁语借词，内部成分已经凝固：ante-“前”+ cedere“走”。英语在成品词族上加 -al、-ess、-ly、-ial，而同一拉丁词根也通过 predecessor、successor、antecedent 进入英语。"},"latinIntro":{"en":"The Latin source is antecedere 'to precede' and its agent noun antecessor 'fore-goer'. Cedere 'to go, yield' also gives predecessor and successor. Descendant belongs to scandere 'to climb', so it is a look-alike rather than a cedere relative.","cn":"拉丁语来源是 antecedere“走在前面”及其施动名词 antecessor“先行者”。cedere“走、让步”也构成 predecessor 与 successor。descendant 属于 scandere“爬”，因此是形近词，而不是 cedere 的同根词。"},"items":[{"word":"ancestral","structure":"ancestor + -al (relational adjective)","meaning":"relating to ancestors","meaningCN":"祖先的；与先人有关的（-al 构成关系形容词）","example":"The ancestral portrait was cleaned before the reunion.","exampleCN":"聚会前，那幅先人画像被清理干净。"},{"word":"ancestor","structure":"Latin ante- (before) + cedere (go), through Late Latin antecessor","meaning":"one who goes before; a forebear","meaningCN":"走在前面的人；祖先（ante- 前 + cedere 走）","example":"Her earliest known ancestor arrived by boat in 1840.","exampleCN":"她已知最早的那位祖先于 1840 年乘船抵达。"},{"word":"ancestry","structure":"ancestor + -ry (collective noun)","meaning":"the whole line of ancestors","meaningCN":"血统；世系（-ry 构成集合名词）","example":"The archive traces the family's ancestry to three counties.","exampleCN":"档案把这个家族的血统追溯到三个县。"},{"word":"ancestress","structure":"ancestor + -ess (feminine)","meaning":"a female ancestor","meaningCN":"女祖先（-ess 表女性）","example":"The ancestress is remembered for founding the village school.","exampleCN":"这位女祖先因创办村校而被铭记。"},{"word":"ancestrally","structure":"ancestral + -ly (adverb)","meaning":"in a way that relates to ancestors","meaningCN":"在祖先方面；按祖先的方式（-ly 构成副词）","example":"The land was ancestrally held by the same clan.","exampleCN":"这片土地在祖先意义上由同一宗族持有。"},{"word":"ancestorial","structure":"ancestor + -ial (alternative relational adjective)","meaning":"relating to ancestors; a variant of ancestral","meaningCN":"祖先的（ancestral 的替代形容词形式）","example":"The older texts prefer ancestorial rights to ancestral rights.","exampleCN":"较早的文本更常用 ancestorial rights，而不是 ancestral rights。"},{"word":"antecedent","structure":"ante- (before) + ced- (go) + -ent (noun or adjective)","meaning":"a thing or person that comes before","meaningCN":"前事；先行者（ante- 前 + cedere 走 + -ent）","example":"The antecedent of the modern treaty was a verbal promise.","exampleCN":"现代条约的前身是一句口头承诺。"},{"word":"predecessor","structure":"prae- (before) + de- (away) + cedere (go)","meaning":"someone or something that came before another in an office or line","meaningCN":"前任；前身（prae- 前 + de- 离 + cedere 走）","example":"The predecessor of the current director served for twenty years.","exampleCN":"现任主管的前任任职二十年。"},{"word":"successor","structure":"sub- (after, near) + cedere (go)","meaning":"one who comes after another","meaningCN":"继任者；后继者（sub- 后 + cedere 走）","example":"The successor took office in the following spring.","exampleCN":"继任者在次年春天上任。"},{"word":"descendant","structure":"de- (down) + scandere (climb); not a cedere word","meaning":"a person or thing that comes from an earlier one","meaningCN":"后代；衍生物（de- 下 + scandere 爬；注意它不是 cedere 的同根词）","example":"The descendant of that tree still stands in the courtyard.","exampleCN":"那棵树的后代仍立在院子里。"},{"word":"ancient","structure":"Latin ante (before) + -anus, through Vulgar Latin *anteanus; not from antiquus","meaning":"belonging to the distant past","meaningCN":"古老的；古代的（ante 前 + -anus；并非来自 antiquus）","example":"The ancient wall follows the old city boundary.","exampleCN":"那道古墙沿着旧城边界延伸。"}],"latinEntries":[{"word":"ante","structure":"Latin preposition and adverb; PIE *ant- 'front'","meaning":"before, in front of","meaningCN":"在前；在……前面"},{"word":"cedere","structure":"Latin verb; PIE *ked- 'to go, yield'","meaning":"to go, yield","meaningCN":"走；让步"},{"word":"antecessor","structure":"ante + ced- + -or (agent noun)","meaning":"predecessor, fore-goer","meaningCN":"前任；先行者"},{"word":"scandere","structure":"Latin verb; source of descend and descendant, not of ancestor","meaning":"to climb","meaningCN":"爬；攀登（descend/descendant 的来源，不是 ancestor 的来源）"}]}},{"word":"ancestry","ipa_uk":"/ˈænsestri/","ipa_us":"/ˈænsestri/","definition_zh":"血统；世系；祖先的总称；家族出身；（生物）共同祖先关系","definition_en":"the whole line of people from whom someone descends, the background this line gives them, or the shared origin of a group or species","core_image":"一条从先人延伸到自己脚下的血脉长线，重点在整条线，而不是线上某一个人","scene":"她做了基因检测，报告把她的血统追溯到东欧一座小村庄。She takes a DNA test, and the report traces her ancestry back to a small village in eastern Europe.","sceneCN":"这里 ancestry 是「作为整体的血统世系」（第 1 个义项：把许多代先人看作一条完整血脉）；句意：她做了基因检测，报告把她的血统世系追溯到东欧的一座小村庄。场景要点：检测报告、染色体图、迁徙路线、小村庄的地图标记、手指点着报告上的一条线。","pos":[{"tag":"n.","zh":"血统；世系；祖先的总称；出身"}],"collocations":[{"phrase":"of Irish ancestry","zh":"有爱尔兰血统"},{"phrase":"trace one's ancestry","zh":"追溯某人的血统"},{"phrase":"shared ancestry","zh":"共同祖先；共同血统"},{"phrase":"genetic ancestry","zh":"遗传血统"},{"phrase":"mixed ancestry","zh":"混合血统"},{"phrase":"ancestry test","zh":"血统检测"},{"phrase":"common ancestry","zh":"共同来源；共同祖先"}],"forms":[{"label":"名词复数","form":"ancestries"}],"derivatives":[{"word":"ancestor","pos":"n.","zh":"祖先；原型"},{"word":"ancestral","pos":"adj.","zh":"祖先的；祖传的"},{"word":"ancestress","pos":"n.","zh":"女祖先"},{"word":"ancestrally","pos":"adv.","zh":"在祖先方面；按祖先的方式"}],"senses":[{"no":"01","title":"The whole line of descent","titleCN":"作为整体的血统世系","definition":"the complete line of people from whom a person or group is descended, considered as one whole","definitionCN":"某个人或群体所出自的、被当作一个整体的完整先人链条","example":"Her ancestry reaches back to fishing families on the northern coast.","exampleCN":"她的血统可以追溯到北方海岸的渔民家庭。","why":"-ry makes a collective noun: it gathers many ancestors into one line, so ancestry names the whole rather than any single forebear.","whyCN":"-ry 构成集合名词：它把许多祖先聚成一条线，因此 ancestry 命名的是整体，而不是某一位先人。"},{"no":"02","title":"Family background as identity","titleCN":"作为身份背景的家世","definition":"a person's social, national, or ethnic background as defined by their forebears","definitionCN":"由先人决定的个人社会、民族或族群背景","example":"The novelist wrote about her mixed ancestry with humor.","exampleCN":"这位小说家用幽默的笔调写自己混合的血统背景。","why":"Once the line is a possession, it becomes part of identity; ancestry then answers 'where do you come from?' rather than 'who was your great-grandfather?'","whyCN":"一旦这条线成为一种拥有物，它就变成身份的一部分；ancestry 于是回答“你从哪里来”，而不是“你的曾祖父是谁”。"},{"no":"03","title":"The traceable genealogical record","titleCN":"可追溯的谱系记录","definition":"the chain of descent that can be followed through documents, names, and records","definitionCN":"可以通过文件、姓名和记录逐环追查的血统链","example":"He spent ten years tracing his ancestry through parish registers.","exampleCN":"他花了十年时间通过教区登记簿追溯自己的世系。","why":"A line can be followed link by link; when the links are documented, ancestry becomes the traceable genealogy itself.","whyCN":"一条线可以一环一环地追下去；当这些环节有文献记录时，ancestry 就变成可追溯的谱系本身。"},{"no":"04","title":"Evolutionary common origin","titleCN":"演化上的共同来源","definition":"the earlier population or species from which a present organism is descended","definitionCN":"现存生物所由来的早期种群或物种","example":"The two bird species share a common ancestry in the southern continent.","exampleCN":"这两种鸟在南半球大陆上拥有共同祖先。","why":"Biology borrows the family tree and replaces named relatives with populations; shared ancestry is the branching point where two lines separate.","whyCN":"生物学借用了家族树，把有名字的亲属换成种群；共同血统就是两条谱系分开的那个分叉点。"},{"no":"05","title":"Inherited genetic material","titleCN":"遗传物质构成的血统","definition":"the inherited genetic material of an individual or population","definitionCN":"某个人或群体所继承的遗传物质","example":"The clinic uses ancestry to check for inherited risk variants.","exampleCN":"诊所利用血统信息检查遗传性风险变异。","why":"In modern genetics the abstract line is measured as DNA; ancestry becomes the sum of inherited variants, a testable property rather than a family story.","whyCN":"在现代遗传学里，抽象的血统线被测量为 DNA；ancestry 成为所继承变异的集合，是一种可检测的属性，而不是家族故事。"},{"no":"06","title":"Descent as a legal qualification","titleCN":"作为法律资格的血统","definition":"the fact of descent from a place or people, used to establish rights, citizenship, or status","definitionCN":"从某地或某民族传下的事实，用来确立权利、公民身份或地位","example":"Citizenship was granted on the basis of ancestry rather than birthplace.","exampleCN":"公民身份依据血统而非出生地授予。","why":"Law needs a rule that can be checked; descent from a national line becomes a formal qualification, so ancestry turns into evidence of belonging.","whyCN":"法律需要一条可核查的规则；从某国血统传下成为正式资格，ancestry 于是变成归属的证据。"},{"no":"07","title":"The source of a word, custom, or idea","titleCN":"词语、习俗或观念的渊源","definition":"the origin or line of development of a word, custom, or idea","definitionCN":"某个词语、习俗或观念的最初来源或发展线","example":"The ancestry of the proverb can be traced through three languages.","exampleCN":"这句谚语的渊源可以穿过三种语言追溯出来。","why":"Anything that develops can be given a line of predecessors; ancestry then means 'the chain of earlier sources' rather than biological descent.","whyCN":"任何会发展的事物都可以被安排一条前身线；ancestry 于是表示“更早来源的链条”，而不是生物血统。"},{"no":"08","title":"The pedigree of domesticated stock","titleCN":"家养动植物的谱系","definition":"the line of forebears of a domesticated animal or plant, especially as recorded by breeders","definitionCN":"家养动物或植物的先代链条，尤指育种者记录下来的谱系","example":"The breeder keeps careful records of the herd's ancestry.","exampleCN":"育种者仔细记录牛群的谱系。","why":"Selective breeding treats animals like families; the pedigree is literally an ancestry record, so the word applies to stock as well as people.","whyCN":"选育把动物当作家族来对待；血统记录字面上就是 ancestry record，因此这个词也适用于家畜，而不只适用于人。"},{"no":"09","title":"The ancestors taken together","titleCN":"被整体看待的祖先们","definition":"the ancestors of a person taken together, especially when they are addressed as a body in ceremony or literature","definitionCN":"把某人的祖先们聚在一起看待，尤指在仪式或文学中被作为一个整体称呼时","example":"The ceremony calls on the ancestry to witness the marriage.","exampleCN":"仪式召唤祖先们来见证这场婚礼。","why":"The collective noun can be personified: the line stands in for the dead as a group, so ancestry is occasionally used where ancestor(s) would be concrete.","whyCN":"这个集合名词可以被拟人化：整条线代表死者群体，因此 ancestry 偶尔会出现在本可以用具体 ancestor(s) 的地方。"}],"etymology":{"intro":{"en":"Ancestry is the collective and abstract noun beside ancestor, not a variant spelling of it. Old French ancesserie, built on ancestre with the suffix -erie, names the whole line or stock; English -ry keeps that collective force, and the spelling was later reshaped under the influence of ancestor. The base goes back to Latin antecessor 'fore-goer' (ante 'before' + cedere 'to go'). Ancient is a look-alike from ante + -anus, not from antiquus; descendant is from scandere 'to climb', not from cedere.","cn":"ancestry 是 ancestor 旁边的集合/抽象名词，不是它的拼写变体。古法语 ancesserie 在 ancestre 上加 -erie，指整条世系或整个血统；英语 -ry 保留这种集合义，后来拼写又受 ancestor 影响而调整。基础词可追溯到拉丁语 antecessor“先行者”（ante“前”+ cedere“走”）。ancient 是来自 ante + -anus 的形近词，并非来自 antiquus；descendant 来自 scandere“爬”，并非来自 cedere。"},"items":[{"era":"EARLY 14C.","en":"First recorded in English as auncestrie, 'series or line of ancestors, descent from ancestors'. The word names the line, not one person in it.","cn":"英语最早记录为 auncestrie，意为“祖先的序列或世系、从祖先传下”。这个词命名的是整条线，而不是线中的某个人。"},{"era":"OLD FRENCH","en":"From Old French ancesserie 'ancestry, ancestors, forefathers', formed on ancestre 'ancestor'. The French noun already had a collective sense.","cn":"来自古法语 ancesserie“血统、祖先、父辈”，由 ancestre“祖先”构成。这个法语名词本身已带集合义。"},{"era":"-RY / -ERIE","en":"The French suffix -erie (English -ry) forms nouns of state, collection, or place. Added to ancestre it does not name one forebear but the whole stock or line; English later respelled the word under the influence of ancestor.","cn":"法语后缀 -erie（英语 -ry）构成状态、集合或地点名词。加在 ancestre 上，它不指某一位先人，而指整个血统或世系；英语后来受 ancestor 影响改写了拼写。"},{"era":"LATE LATIN / LATIN","en":"ancestre goes back to Late Latin antecessor 'predecessor', literally 'fore-goer', from antecedere 'to precede' = ante 'before' + cedere 'to go'.","cn":"ancestre 可追溯到晚期拉丁语 antecessor“前任”，字面义“先行者”，来自 antecedere“走在前面”= ante“前”+ cedere“走”。"},{"era":"PIE","en":"ante is traced to PIE *ant- 'front, forehead' and cedere to *ked- 'to go, yield'. The reconstructions are standard, but the exact route through Late Latin is not fully certain.","cn":"ante 被追溯到原始印欧语 *ant-“前面、额头”，cedere 追溯到 *ked-“走、让步”。这些重构是通行的，但经过晚期拉丁语的具体路径并非完全确定。"},{"era":"MODERN ENGLISH","en":"Ancestry keeps the abstract or collective meaning, while ancestor is the countable person. It is not related to ancient as a derivative: ancient comes from ante + -anus, and antique is the word from antiquus. The opposite-direction cedere relative is successor, not descendant.","cn":"ancestry 保留抽象或集合义，而 ancestor 是可数的人。它不是 ancient 的派生词：ancient 来自 ante + -anus，来自 antiquus 的是 antique。反向的 cedere 同根词是 successor，不是 descendant。"}]},"similar":{"note":{"en":"The first group separates the person noun, the adjective, and the look-alike from ancestry; the second compares words about lines, origins, and inheritance.","cn":"第一组把人物名词、形容词和形近词同 ancestry 分开；第二组比较关于世系、来源与继承的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ancestor","ipa":"/ˈænsestə/","tag":"single person","definition":"one forebear. Ancestry is the whole line; ancestor is one countable link in it.","definitionCN":"一位先人。ancestry 是整条线；ancestor 是线中一个可数的环节。"},{"word":"ancestral","ipa":"/ænˈsestrəl/","tag":"adjective","definition":"relating to ancestors. It describes a thing or place; ancestry is the noun for the line itself.","definitionCN":"与祖先有关的。它描述某物或某地；ancestry 是表示这条线本身的名词。"},{"word":"ancient","ipa":"/ˈeɪnʃənt/","tag":"different formation","definition":"belonging to the distant past. It shares the *ant- 'before' root but is not a form of ancestry, and it does not come from antiquus.","definitionCN":"属于遥远过去的。它共享 *ant-“前”词根，但不是 ancestry 的形式，也不来自 antiquus。"},{"word":"ancestress","ipa":"/ˈænsestrəs/","tag":"feminine noun","definition":"a female ancestor. It is a derived person noun, not the collective line.","definitionCN":"女祖先。它是派生的人物名词，不是集合性的世系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"lineage","ipa":"/ˈlɪniɪdʒ/","tag":"traceable line","definition":"a direct line of descent from an ancestor, especially a documented or formal one. It often stresses noble or official descent, while ancestry is broader and more personal.","definitionCN":"从某位祖先传下的直系血统，尤指有记录或正式的血统。它常强调贵族或官方世系，而 ancestry 更宽泛、更个人化。"},{"word":"descent","ipa":"/dɪˈsent/","tag":"origin relation","definition":"the fact of coming from a particular ancestor or group. It is the relation viewed from the descendant's side; ancestry is the total stock behind that relation.","definitionCN":"出自某位祖先或某个群体的事实。它是从后代一方看的关系；ancestry 则是这一关系背后的全部血统储备。"},{"word":"genealogy","ipa":"/ˌdʒiːniˈælədʒi/","tag":"study or record","definition":"the study or record of family lines. It is the research or chart, while ancestry is the biological or social fact being researched.","definitionCN":"对家族世系的研究或记录。它指研究或谱表，而 ancestry 是被研究的生物或社会事实。"},{"word":"heritage","ipa":"/ˈherɪtɪdʒ/","tag":"what is passed down","definition":"the traditions, language, and property inherited from a group. It includes culture and things, while ancestry is specifically the line of people.","definitionCN":"从某个群体继承的传统、语言和财产。它包含文化与实物，而 ancestry 特指人的血统线。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: ancestor plus the French collective suffix -erie/-ry, the contrast with the countable ancestor, and the near words lineage, descent and genealogy.","cn":"只用真实成分与真实同族词：ancestor 加法语集合后缀 -erie/-ry，与可数 ancestor 的对比，以及 lineage、descent、genealogy 这组近义词。"},"normal":[{"en":"ancestry is ancestor + the French collective suffix -erie/-ry; the suffix gathers many ancestors into one line.","cn":"ancestry 是 ancestor 加法语集合后缀 -erie/-ry；这个后缀把许多祖先聚成一条线。"},{"en":"Ancestor names one person; ancestry names the whole stock or line, so the two are not interchangeable.","cn":"ancestor 指一个人；ancestry 指整个血统或世系，两者不能互换。"},{"en":"The spelling was reshaped by ancestor, which is why ancestry looks as if it contains the whole noun ancestor.","cn":"拼写受 ancestor 影响而调整，所以 ancestry 看起来像把整个 ancestor 包了进去。"},{"en":"Ancient is not the adjective of ancestry; the adjective is ancestral. Ancient comes from ante + -anus, while antique comes from antiquus.","cn":"ancient 不是 ancestry 的形容词；形容词是 ancestral。ancient 来自 ante + -anus，而 antique 来自 antiquus。"},{"en":"Lineage stresses a documented line, descent the relation from the descendant's side, and genealogy the study or chart; ancestry is the broad fact behind all three.","cn":"lineage 强调有记录的世系，descent 强调从后代一方看的关系，genealogy 指研究或谱表；ancestry 是三者背后的宽泛事实。"}],"abstract":[{"en":"Imagine a rope braided from many strands: each strand is an ancestor, the braided rope is ancestry.","cn":"想象一根由许多股编成的绳：每一股是一个 ancestor，编成的整根绳就是 ancestry。"},{"en":"A river delta: many upstream streams feed one channel; the streams are ancestors and their combined watershed is ancestry.","cn":"一片河口三角洲：上游许多溪流汇入一条水道；溪流是 ancestors，它们合起来的分水岭就是 ancestry。"},{"en":"A pedigree chart: one box is a person, but the connected chain of boxes is the ancestry.","cn":"一张谱系图：一个方框是一个人，而连起来的整串方框才是 ancestry。"}]},"examples":[{"en":"She discovered that her ancestry includes both farmers and sailors.","cn":"她发现自己的血统里既有农民也有水手。"},{"en":"Researchers use DNA to estimate shared ancestry among populations.","cn":"研究人员用 DNA 估计群体间的共同血统。"},{"en":"The law grants citizenship on the basis of ancestry.","cn":"这项法律依据血统授予公民身份。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「俺家谱」——‘俺’家的谱系一代代传下来 → ancestry 血统、世系（只借音，不表词源）","word":"ancestry"},"root":"古法语 ancesserie < ancestre < 拉丁语 antecessor“先行者”（ante 前 + cedere 走）；-ry/-erie 使具体先人变成“血统总体、世系”。","sensesIntro":{"en":"Nine senses of ancestry all treat descent as a whole: the line itself, the identity it gives, its traceable record, a species' branching point, its DNA, a legal qualification, a cultural source, a pedigree, and the ancestors personified.","cn":"ancestry 的九个义项都把血统当作整体来处理：这条线本身、它带来的身份、可追溯的记录、物种的分叉点、它的 DNA、法律资格、文化渊源、谱系记录，以及被拟人化的祖先群体。"},"semanticMap":{"core":{"en":"CORE IMAGE: the whole braided line of descent, seen as one thing rather than as separate people.","cn":"核心意象：一整条编合起来的血统线，被当作一个整体，而不是分开的许多人。"},"chain":["MANY ANCESTORS","ONE LINE","COLLECTIVE STOCK","TRACEABLE RECORD","SHARED ORIGIN","IDENTITY"],"branches":[{"senses":"01 · 09","en":"THE LINE AS A WHOLE: the abstract descent, and the same ancestors personified as a body.","cn":"作为整体的线：抽象的血统世系，以及被拟人化为群体的同一批祖先。"},{"senses":"02 · 06","en":"IDENTITY AND STATUS: background becomes personal identity, and descent becomes a legal qualification.","cn":"身份与地位：背景成为个人身份，血统成为法律资格。"},{"senses":"03 · 08","en":"RECORDED LINES: parish registers trace a family, and breeders' records trace a pedigree.","cn":"被记录的线：教区登记簿追溯家族，育种记录追溯谱系。"},{"senses":"04 · 05","en":"BIOLOGY: populations share a branching origin, and modern genetics measures that origin as DNA.","cn":"生物学：种群共享一个分叉来源，现代遗传学把这一来源测量为 DNA。"},{"senses":"07","en":"CULTURAL SOURCE: words, customs and ideas can have a chain of earlier sources too.","cn":"文化渊源：词语、习俗和观念也可以有一条更早来源的链条。"}]},"affixes":{"intro":{"en":"Ancestry is ancestre + the French suffix -erie, continued in English as -ry. The suffix is the key: it changes a countable person noun into a collective or state noun. The base ancestre is the same word that gives ancestor, and it goes back to Latin antecessor.","cn":"ancestry 是 ancestre 加法语后缀 -erie，在英语中延续为 -ry。关键就在这个后缀：它把可数的人物名词变成集合或状态名词。基础词 ancestre 与 ancestor 同源，可追溯到拉丁语 antecessor。"},"latinIntro":{"en":"The Latin base is antecessor 'fore-goer' from antecedere (ante 'before' + cedere 'to go'). Cedere also gives predecessor and successor, but not descendant, which belongs to scandere 'to climb'. The deepest *ant- and *ked- roots are reconstructed.","cn":"拉丁语基础是 antecessor“先行者”，来自 antecedere（ante“前”+ cedere“走”）。cedere 也构成 predecessor 和 successor，但不构成 descendant，后者属于 scandere“爬”。最深层的 *ant- 与 *ked- 词根是重构形式。"},"items":[{"word":"ancestry","structure":"ancestre + -erie / -ry (collective or state noun)","meaning":"the whole line of descent","meaningCN":"血统；世系（-ry 构成集合或状态名词）","example":"The census records are useful for studying ancestry.","exampleCN":"人口普查记录对研究血统很有用。"},{"word":"ancestor","structure":"ante- (before) + cedere (go), through Late Latin antecessor","meaning":"one who goes before; a forebear","meaningCN":"先行者；祖先（ante- 前 + cedere 走）","example":"Every ancestor in the chart has a birth record.","exampleCN":"谱系图中的每一位祖先都有出生记录。"},{"word":"ancestral","structure":"ancestor + -al (relational adjective)","meaning":"relating to ancestors","meaningCN":"祖先的；与先人有关的（-al 构成关系形容词）","example":"The ancestral house is now a small museum.","exampleCN":"那座祖宅现在是一座小博物馆。"},{"word":"ancestress","structure":"ancestor + -ess (feminine)","meaning":"a female ancestor","meaningCN":"女祖先（-ess 表女性）","example":"The ancestress left a diary that covers forty years.","exampleCN":"这位女祖先留下了一本跨越四十年的日记。"},{"word":"ancestrally","structure":"ancestral + -ly (adverb)","meaning":"in a way that relates to ancestors","meaningCN":"在祖先方面；按祖先的方式（-ly 构成副词）","example":"The family was ancestrally tied to the same valley.","exampleCN":"这个家族在血统上与同一座山谷相连。"},{"word":"antecedent","structure":"ante- (before) + ced- (go) + -ent","meaning":"something that comes before","meaningCN":"前事；先行者（ante- 前 + cedere 走 + -ent）","example":"The custom has an antecedent in an older harvest rite.","exampleCN":"这一习俗的前身是一种更古老的丰收仪式。"},{"word":"predecessor","structure":"prae- (before) + de- (away) + cedere (go)","meaning":"someone or something that came before","meaningCN":"前任；前身（prae- 前 + de- 离 + cedere 走）","example":"The predecessor of the archive was a private collection.","exampleCN":"这个档案馆的前身是一批私人收藏。"},{"word":"successor","structure":"sub- (after, near) + cedere (go)","meaning":"one who comes after another","meaningCN":"继任者；后继者（sub- 后 + cedere 走）","example":"The successor inherited the same record-keeping duty.","exampleCN":"继任者继承了他们同样的记录职责。"},{"word":"descendant","structure":"de- (down) + scandere (climb); not a cedere word","meaning":"a person or thing that comes from an earlier one","meaningCN":"后代；衍生物（de- 下 + scandere 爬；不是 cedere 同根词）","example":"The descendants of the first settlers still live nearby.","exampleCN":"最早定居者的后代仍住在附近。"},{"word":"ancient","structure":"Latin ante (before) + -anus, through Vulgar Latin *anteanus; not from antiquus","meaning":"belonging to the distant past","meaningCN":"古老的；古代的（ante 前 + -anus；并非来自 antiquus）","example":"The ancient records were copied onto new paper.","exampleCN":"那些古老的记录被抄到了新纸上。"}],"latinEntries":[{"word":"ante","structure":"Latin preposition and adverb; PIE *ant- 'front'","meaning":"before, in front of","meaningCN":"在前；在……前面"},{"word":"cedere","structure":"Latin verb; PIE *ked- 'to go, yield'","meaning":"to go, yield","meaningCN":"走；让步"},{"word":"antecessor","structure":"ante + ced- + -or (agent noun)","meaning":"predecessor, fore-goer","meaningCN":"前任；先行者"},{"word":"scandere","structure":"Latin verb; source of descend and descendant, not of ancestry","meaning":"to climb","meaningCN":"爬；攀登（descend/descendant 的来源，不是 ancestry 的来源）"}]}},{"word":"annually","ipa_uk":"/ˈænjuəli/","ipa_us":"/ˈænjuəli/","definition_zh":"每年地；一年一次地；按年度计算地；年复一年地","definition_en":"once a year, every year, or calculated over a period of one year","core_image":"日历上每年同一个格子被重新圈一次，整整十二个月走完一圈再回到原处","scene":"每年四月，公司都会发布年报。Every April the company publishes its annual report, and the auditors check the whole year's accounts annually.","sceneCN":"这里 annually 是「每年发布或更新」（第 4 个义项：每年出版、发布或更新一次）；句意：每年四月公司发布年报，审计师每年核对一遍全年的账目。场景要点：四月的日历、年报封面、审计师的印章、一整年的账册、圈出的同一天。","pos":[{"tag":"adv.","zh":"副词：每年地；一年一次地；按年度地"}],"collocations":[{"phrase":"held annually","zh":"每年举办"},{"phrase":"published annually","zh":"每年发布"},{"phrase":"paid annually","zh":"按年支付"},{"phrase":"audited annually","zh":"每年审计"},{"phrase":"occur annually","zh":"每年发生"},{"phrase":"grow annually","zh":"逐年增长"},{"phrase":"compounded annually","zh":"按年复利"}],"forms":[{"label":"副词形态","form":"annually（无屈折变化）"}],"derivatives":[{"word":"annual","pos":"adj.","zh":"每年的；按年度的"},{"word":"annual","pos":"n.","zh":"年刊；一年生植物"},{"word":"annualize","pos":"v.","zh":"按年折算；年化"},{"word":"annualized","pos":"adj.","zh":"年化的；按年折算的"},{"word":"annualization","pos":"n.","zh":"年化；按年折算"}],"senses":[{"no":"01","title":"Once a year on a fixed date","titleCN":"每年一次（固定日期）","definition":"once every year, on or around the same date","definitionCN":"每年一次，通常在同一天或前后几天","example":"The town festival is held annually in the first week of June.","exampleCN":"镇上的节庆每年六月的第一周举办。","why":"-ly turns the adjective annual ('yearly') into a manner or frequency adverb; the calendar gives the clearest unit, so the default sense is 'once a year'.","whyCN":"-ly 把形容词 annual（每年的）变成方式或频率副词；日历提供了最清楚的单位，因此默认义就是“一年一次”。"},{"no":"02","title":"Repeated every year","titleCN":"每年重复地","definition":"happening again each year as a recurring pattern, without emphasis on a particular date","definitionCN":"作为一种反复出现的模式每年再次发生，不强调具体日期","example":"These birds return annually to the same marsh.","exampleCN":"这些鸟每年都回到同一片沼泽。","why":"The year can be treated as a repeating cycle rather than a date; the adverb then marks recurrence itself, so 'annually' means 'year after year'.","whyCN":"“年”可以被当作一个循环，而不是一个日期；副词于是标记重复本身，annually 就表示“年复一年”。"},{"no":"03","title":"Measured over one year","titleCN":"按一个年度计量","definition":"measured or calculated over a period of one year","definitionCN":"以一年为周期来测量或计算","example":"The plant reports annually how much water it consumes.","exampleCN":"这家工厂按年度报告它的用水量。","why":"If a quantity is summed over a year, the adverb marks the accounting window rather than the event date; 'annually' becomes 'per year'.","whyCN":"如果一个数量按一年汇总，副词标记的是统计窗口而不是事件日期；annually 于是变成“每年/按年”。"},{"no":"04","title":"Published or issued each year","titleCN":"每年发布或更新","definition":"produced, published, renewed, or updated once each year as a regular item","definitionCN":"作为固定项目每年制作、出版、续订或更新一次","example":"The safety report is published annually in April.","exampleCN":"安全报告每年四月发布。","why":"Recurring documents create a rhythm; the yearly issue becomes the fixed point, so annually marks the release cycle of an object rather than a natural event.","whyCN":"重复出现的文件形成节奏；每年一期的发布成为固定点，因此 annually 标记的是出版物的发布周期，而不是自然事件。"},{"no":"05","title":"In a natural yearly cycle","titleCN":"处于自然年度周期中","definition":"in a cycle that repeats once a year, as with seasons, migration, or growth","definitionCN":"处于一年重复一次的周期中，如季节、迁徙或生长","example":"The river rises annually with the summer rains.","exampleCN":"这条河随夏季降雨每年上涨。","why":"Biological and physical time is organized by the year; the adverb attaches to the cycle itself, not to a human calendar decision.","whyCN":"生物与物理时间按年组织；这个副词附着在周期本身，而不是人的日历决定。"},{"no":"06","title":"Year over year","titleCN":"逐年的、同比的","definition":"in a comparison between one year and the next, especially of a rate of change","definitionCN":"在一年与下一年的比较中，尤指变化率","example":"The company's revenue has grown annually by about six percent.","exampleCN":"公司的收入每年增长约百分之六。","why":"A rate needs a time denominator. When the denominator is one year, annually describes the pace of change rather than a single event.","whyCN":"一个变化率需要时间分母。当分母是一年时，annually 描述变化的速度，而不是单个事件。"},{"no":"07","title":"With yearly compounding","titleCN":"按年复利地","definition":"with interest calculated and added to the principal once a year","definitionCN":"利息每年计算一次并计入本金","example":"Interest on the account is compounded annually.","exampleCN":"这个账户的利息按年复利计算。","why":"Finance needs to name the interval at which interest becomes principal; the yearly unit is the standard default, so annually marks the compounding period.","whyCN":"金融需要说明利息在什么间隔变成本金；以年为单位的间隔是标准默认值，所以 annually 标记复利周期。"},{"no":"08","title":"As a yearly routine or duty","titleCN":"作为年度例行或义务","definition":"as a regular yearly duty, review, inspection, or compliance step","definitionCN":"作为每年固定的职责、审查、检查或合规步骤","example":"All safety equipment is inspected annually.","exampleCN":"所有安全设备每年检查一次。","why":"Institutions turn recurrence into obligation; the adverb marks the compliance cycle, often with passive verbs such as audited, inspected, or reviewed.","whyCN":"机构把重复变成义务；副词标记合规周期，常与 audited、inspected、reviewed 等被动动词连用。"},{"no":"09","title":"On a yearly billing schedule","titleCN":"按年度计费或付款","definition":"paid, charged, or billed once a year rather than monthly or quarterly","definitionCN":"一年支付、收取或开票一次，而不是按月或按季","example":"The membership fee is billed annually.","exampleCN":"会员费按年开票。","why":"Payment schedules are named by their interval; annually specifies the billing rhythm and contrasts with monthly or quarterly.","whyCN":"付款计划按间隔命名；annually 说明开票节奏，并与 monthly、quarterly 形成对照。"}],"etymology":{"intro":{"en":"Annually is a transparent English derivative: annual + -ly, first recorded in the 1590s. Annual goes back through Old French annuel or Medieval Latin annualis to Latin annus 'year'. The main trap is not etymology but spelling: annul looks like annual minus one letter, yet it is ad- + nullus 'nothing' and contains no year at all. True annus relatives include anniversary, annals and annuity.","cn":"annually 是一个透明的英语派生词：annual + -ly，最早记录于 16 世纪 90 年代。annual 经古法语 annuel 或中世纪拉丁语 annualis 追溯到拉丁语 annus“年”。主要陷阱不在词源而在拼写：annul 看起来像少了一个字母的 annual，实际却是 ad- + nullus“无”，里面根本没有“年”。真正的 annus 同族词包括 anniversary、annals、annuity。"},"items":[{"era":"1590s","en":"First recorded as 'yearly, year by year, returning every year', formed within English from annual (adj.) + -ly (2).","cn":"最早记录为“每年地、年复一年地、每年返回”，是英语内部由 annual（形容词）+ -ly（第二类副词后缀）构成。"},{"era":"LATE 14C. / C. 1400","en":"Annual is recorded late 14c. as 'appointed by the year' and c.1400 as 'occurring or done once a year', from Old French annuel or directly from Medieval Latin annualis.","cn":"annual 在 14 世纪晚期记录为“按年指定的”，约 1400 年记录为“每年发生或做一次的”，来自古法语 annuel 或直接来自中世纪拉丁语 annualis。"},{"era":"LATIN","en":"annualis is the adjective of annus 'year', corresponding to Latin annalis. Annus is reconstructed to Proto-Italic *atno- and PIE *at-no- 'that which goes', from *at- 'to go', the year as a circuit.","cn":"annualis 是 annus“年”的形容词，对应于拉丁语 annalis。annus 被重构为原始意大利语 *atno- 和原始印欧语 *at-no-“行走之物”，来自 *at-“走”，把一年看作一圈行走。"},{"era":"PIE NOTE","en":"The 'year = a going around' reconstruction is standard but explicitly reconstructed; the step from 'go' to 'year' is plausible rather than directly attested in a text.","cn":"“年 = 走一圈”这一重构是通行的，但明确属于重构；从“走”到“年”的语义步骤是合理推测，而不是有文本直接证明。"},{"era":"-LY","en":"The adverbial -ly (2) comes from Old English -lice, Proto-Germanic *-liko-, literally 'in the manner of'. Added to annual it yields 'in a yearly manner', then 'once a year' or 'per year'.","cn":"副词后缀 -ly（第二类）来自古英语 -lice、原始日耳曼语 *-liko-，字面义为“以……的方式”。加在 annual 上得到“以每年的方式”，再引申为“一年一次”或“每年”。"},{"era":"MODERN ENGLISH","en":"Annually covers event frequency, annual totals and rates, and yearly compounding. Annual is not related to annul (ad- + nullus); true annus relatives include anniversary, annals, and annuity.","cn":"annually 覆盖事件频率、年度总量与比率、按年复利。annual 与 annul（ad- + nullus）无关；真正的 annus 同族词包括 anniversary、annals、annuity。"}]},"similar":{"note":{"en":"The first group separates the base adjective, the dangerous spelling twin, and two true annus relatives; the second compares frequency words that differ in precision.","cn":"第一组把基础形容词、危险的拼写双胞胎和两个真正的 annus 同族词分开；第二组比较精确度不同的频率词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"annual","ipa":"/ˈænjuəl/","tag":"base adjective","definition":"happening once a year or calculated by the year. It is the adjective; annually is the adverb formed from it.","definitionCN":"每年发生一次或按年计算的。它是形容词；annually 是由它构成的副词。"},{"word":"annul","ipa":"/əˈnʌl/","tag":"different root","definition":"to cancel or make void, from Latin ad- + nullus 'nothing'. It looks like annual but has no connection with 'year'.","definitionCN":"取消；宣告无效，来自拉丁语 ad- + nullus“无”。它形似 annual，却与“年”毫无关系。"},{"word":"anniversary","ipa":"/ˌænɪˈvɜːsəri/","tag":"same root","definition":"the yearly return of a date, from annus 'year' + vertere 'to turn'. It is a true annus relative, but a noun, not an adverb.","definitionCN":"某日期每年的回归，来自 annus“年”+ vertere“转”。它是真正的 annus 同族词，但属于名词，不是副词。"},{"word":"annuity","ipa":"/əˈnjuːəti/","tag":"same root","definition":"a fixed yearly payment, from Medieval Latin annuitas < annus 'year'. It shares the root but names a financial product.","definitionCN":"固定的年度付款，来自中世纪拉丁语 annuitas < annus“年”。它共享词根，但指的是金融产品。"}]},{"heading":"NEAR MEANING","entries":[{"word":"yearly","ipa":"/ˈjɪəli/","tag":"plain frequency","definition":"once a year or every year. It is the native synonym and can be adjective or adverb; annually is more formal and common in reports, finance, and schedules.","definitionCN":"一年一次或每年。它是本土同义词，可作形容词或副词；annually 更正式，更常用于报告、金融和日程。"},{"word":"per annum","ipa":"/pər ˈænəm/","tag":"rate basis","definition":"for each year, used especially after an amount or rate. It is a Latin phrase and marks a denominator, while annually can also mean a scheduled event.","definitionCN":"每年，尤用于金额或比率之后。它是拉丁短语，标记的是分母，而 annually 也可以表示按日程发生的事件。"},{"word":"periodically","ipa":"/ˌpɪəriˈɒdɪkli/","tag":"at intervals","definition":"at intervals that may be regular or not, not necessarily one year. It is broader and less precise than annually.","definitionCN":"以可能规律也可能不规律的间隔发生，不一定是每年。它比 annually 更宽泛、更不精确。"},{"word":"recurrently","ipa":"/rɪˈkʌrəntli/","tag":"repetition","definition":"happening again repeatedly, without fixing the interval. Annually specifies the interval; recurrently only says it returns.","definitionCN":"反复再次发生，但不固定间隔。annually 明确间隔为一年；recurrently 只表示它会回来。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: annual + -ly, Latin annus 'year', the annus family in anniversary, annals and annuity, and the false friend annul.","cn":"只用真实成分与真实同族词：annual + -ly、拉丁语 annus“年”、anniversary/annals/annuity 中的 annus 词族，以及假朋友 annul。"},"normal":[{"en":"annual + -ly: annual is the adjective 'yearly', and -ly makes the adverb 'in a yearly manner'.","cn":"annual + -ly：annual 是形容词“每年的”，-ly 把它变成副词“以每年的方式”。"},{"en":"annual goes back to Latin annus 'year', which also gives anniversary, annals and annuity.","cn":"annual 可追溯到拉丁语 annus“年”，同一词根也给出 anniversary、annals、annuity。"},{"en":"annul is ad- + nullus 'nothing', meaning 'make void'; it looks like annual but has no year in it.","cn":"annul 是 ad- + nullus“无”，意为“使无效”；它形似 annual，里面却没有“年”。"},{"en":"The adverbial -ly came from Old English -lice, meaning 'in the manner of', so annually is 'after the manner of a year'.","cn":"副词后缀 -ly 来自古英语 -lice，意为“以……的方式”，所以 annually 就是“以一年为方式”。"},{"en":"Fixed phrases sort the senses: held annually (event), paid annually (payment), compounded annually (finance).","cn":"固定搭配区分义项：held annually（事件）、paid annually（付款）、compounded annually（金融）。"}],"abstract":[{"en":"A calendar with one square circled every twelve months; annually is the act of circling the same square again.","cn":"一本日历，每隔十二个月就有一个格子被圈起来；annually 就是再次圈中同一个格子的动作。"},{"en":"A year is a loop: the adverb marks each completion of the loop, not a point inside it.","cn":"一年是一个环：这个副词标记的是每一次走完环，而不是环中的某一点。"},{"en":"A meter that is read once per loop: annually is the rhythm of the reading, whether the number rises or falls.","cn":"一块每圈读一次的仪表：annually 是读数的节奏，无论数字上升还是下降。"}]},"examples":[{"en":"The conference is held annually in the same hall.","cn":"这场会议每年都在同一个大厅举行。"},{"en":"The fee is paid annually rather than monthly.","cn":"这笔费用按年支付，而不是按月支付。"},{"en":"Rainfall in the region has increased annually over the past decade.","cn":"过去十年，该地区的降雨量逐年增加。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「一年里」——annually 读似‘安纽里’，一年里来一次 → 每年地（只借音，不表词源）","word":"annually"},"root":"annual + -ly；annual < 拉丁语 annualis < annus“年”，核心是“按年发生、以一年为周期”；与 annul（ad- + nullus“无”）形似而不同源。","sensesIntro":{"en":"Nine senses of annually all put one year into the sentence: a date returns, a pattern repeats, a total is measured, a document is issued, a natural cycle turns, a rate compares years, interest compounds, a duty recurs, or a bill falls due.","cn":"annually 的九个义项都在句子里放入“一年”这个单位：日期回归、模式重复、总量计量、文件发布、自然周期运转、比率逐年比较、利息复利、义务重复、账单到期。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same point on the calendar is reached again after one full circuit of the year.","cn":"核心意象：走完整整一圈十二个月后，再次到达日历上的同一点。"},"chain":["ONE YEAR","FULL CIRCUIT","RETURN","REPEAT","MEASURE","SCHEDULE"],"branches":[{"senses":"01 · 02","en":"REPETITION IN TIME: a fixed-date event and a general yearly recurrence are the two faces of the same circuit.","cn":"时间中的重复：固定日期的事件与泛泛的每年重现，是同一圈循环的两面。"},{"senses":"03 · 06","en":"MEASUREMENT: a yearly total uses the year as a window, and a year-over-year rate uses it as a denominator.","cn":"计量：年度总量把一年当窗口，同比变化率把一年当分母。"},{"senses":"04 · 08","en":"INSTITUTIONAL RHYTHM: documents are issued and duties are performed on a yearly cycle.","cn":"机构节奏：文件按年发布，职责按年履行。"},{"senses":"05","en":"NATURAL CYCLE: seasons, migration and floods repeat on a yearly rhythm that no office decides.","cn":"自然周期：季节、迁徙和洪水按年度节奏重复，不由任何机构决定。"},{"senses":"07 · 09","en":"MONEY: interest compounds and bills fall due at yearly intervals.","cn":"金钱：利息按年复利，账单按年到期。"}]},"affixes":{"intro":{"en":"Annually is annual + -ly. Both parts are living English: annual is an adjective borrowed from Latin annualis, and -ly is the standard adverb ending. The Latin base annus 'year' also reaches English through anniversary, annals and annuity; annul, despite its shape, comes from nullus 'nothing'.","cn":"annually 是 annual + -ly。两部分都是活的英语成分：annual 是借自拉丁语 annualis 的形容词，-ly 是标准副词后缀。拉丁语基础 annus“年”也通过 anniversary、annals、annuity 进入英语；annul 尽管形状相似，却来自 nullus“无”。"},"latinIntro":{"en":"Latin annus 'year' gives the adjective annualis and the yearly-record noun annales. The deeper Proto-Italic *atno- and PIE *at-no- 'that which goes' are reconstructions, not attested forms.","cn":"拉丁语 annus“年”给出形容词 annualis 和表示年度记录的名词 annales。更深层的原始意大利语 *atno- 与原始印欧语 *at-no-“行走之物”是重构形式，并非有证形式。"},"items":[{"word":"annually","structure":"annual + -ly (adverb of manner or frequency)","meaning":"once a year; year by year; per year","meaningCN":"每年地；一年一次地；按年度地（-ly 构成副词）","example":"The prize is awarded annually to one young scientist.","exampleCN":"该奖项每年授予一位年轻科学家。"},{"word":"annual","structure":"Latin annus (year) + -al, through Latin annualis","meaning":"yearly; calculated by the year","meaningCN":"每年的；按年度的（annus 年 + -al）","example":"The annual budget was approved in December.","exampleCN":"年度预算在十二月获得批准。"},{"word":"anniversary","structure":"annus (year) + vertere (turn) + -ary","meaning":"the yearly return of a date","meaningCN":"周年纪念（annus 年 + vertere 转）","example":"They celebrate their anniversary every autumn.","exampleCN":"他们每年秋天庆祝结婚纪念日。"},{"word":"annals","structure":"annus (year) + -ales (yearly records)","meaning":"a yearly record of events; historical records","meaningCN":"编年史；年鉴（annus 年 + 年度记录）","example":"The event is mentioned only in the monastery's annals.","exampleCN":"这件事只在修道院的编年史中被提到。"},{"word":"annuity","structure":"annus (year) + -ity (noun of state or payment)","meaning":"a fixed yearly payment","meaningCN":"年金；年度付款（annus 年 + -ity）","example":"The retired teacher lives on a small annuity.","exampleCN":"这位退休教师靠一笔小额年金生活。"},{"word":"biennial","structure":"bi- (two) + annus (year) + -al","meaning":"happening every two years, or lasting two years","meaningCN":"两年一次的；持续两年的（bi- 二 + annus 年）","example":"The biennial exhibition returns next summer.","exampleCN":"这个双年展明年夏天回归。"},{"word":"semiannual","structure":"semi- (half) + annual","meaning":"happening twice a year, once in each half-year","meaningCN":"半年一次的；一年两次的（semi- 半 + annual）","example":"The semiannual review takes place in June and December.","exampleCN":"半年一次的审查在六月和十二月进行。"},{"word":"-ly","structure":"Old English -lice < Proto-Germanic *-liko- 'in the manner of'","meaning":"adverbial suffix forming 'in a ... manner'","meaningCN":"副词后缀，表示“以……的方式”","example":"The suffix -ly turns annual into annually.","exampleCN":"后缀 -ly 把 annual 变成 annually。"},{"word":"annul","structure":"ad- (to) + nullus (nothing), a false friend of annual","meaning":"to cancel or make void","meaningCN":"取消；使无效（形近但不同源）","example":"The court annulled the marriage in 1998.","exampleCN":"法院于 1998 年宣告这桩婚姻无效。"},{"word":"annulment","structure":"annul + -ment (noun of action)","meaning":"the act of declaring something invalid","meaningCN":"宣告无效；取消（annul + -ment）","example":"The annulment of the contract took two years.","exampleCN":"这份合同的撤销花了两年。"}],"latinEntries":[{"word":"annus","structure":"Latin noun; reconstructed from Proto-Italic *atno-","meaning":"year","meaningCN":"年"},{"word":"annualis","structure":"annus + -alis (adjective)","meaning":"yearly, annual","meaningCN":"每年的；年度的"},{"word":"annales","structure":"annus + -ales (noun, 'yearly records')","meaning":"yearly records, chronicles","meaningCN":"年度记录；编年史"}]}},{"word":"anomaly","ipa_uk":"/əˈnɒməli/","ipa_us":"/əˈnɑːməli/","definition_zh":"异常；反常；反常的事物；异常现象；（统计）离群值；（天文）近点角","definition_en":"something that deviates from a rule or pattern, the state of such deviation, or a technical departure measured in science and statistics","core_image":"一排整齐平放的砖里，有一块凸起歪斜，眼睛立刻被它绊住","scene":"天文学家在轨道数据里发现一个无法解释的异常，它偏离了计算出的位置。The astronomers find an anomaly in the orbital data: one point sits far from the calculated path.","sceneCN":"这里 anomaly 是「科学观测中无法解释的异常」（第 3 个义项：不符合既有模型的观测或数据）；句意：天文学家在轨道数据里发现一个异常：有一个点偏离了计算出的路径。场景要点：轨道曲线、偏离轨迹的数据点、红色标记、望远镜、写满数字的记录纸。","pos":[{"tag":"n.","zh":"异常；反常；反常的事物；异常现象"}],"collocations":[{"phrase":"statistical anomaly","zh":"统计异常值"},{"phrase":"congenital anomaly","zh":"先天性异常"},{"phrase":"market anomaly","zh":"市场异象"},{"phrase":"anomaly detection","zh":"异常检测"},{"phrase":"a puzzling anomaly","zh":"令人困惑的异常"},{"phrase":"true anomaly","zh":"真近点角"},{"phrase":"anomaly in the data","zh":"数据中的异常"}],"forms":[{"label":"名词复数","form":"anomalies"}],"derivatives":[{"word":"anomalous","pos":"adj.","zh":"异常的；不合规则的"},{"word":"anomalously","pos":"adv.","zh":"异常地；不合规则地"},{"word":"anomalousness","pos":"n.","zh":"异常性；不合规则"}],"senses":[{"no":"01","title":"A departure from the common rule","titleCN":"偏离常规的事物","definition":"something that deviates from what is usual, expected, or governed by a rule","definitionCN":"偏离通常、预期或受规则支配之事的事物","example":"The test results contained one anomaly that no theory could explain.","exampleCN":"测试结果里有一个任何理论都无法解释的异常。","why":"Greek anomalia began as 'unevenness'; a thing that does not lie level with the rest of its class stands out as a departure. The noun names both the gap and the thing in it.","whyCN":"希腊语 anomalia 最初意为“不平整”；一个不能与同类齐平的事物就会凸显为偏离。这个名词既命名那道缝隙，也命名缝隙里的东西。"},{"no":"02","title":"The state of being irregular","titleCN":"不规则的状态","definition":"the quality or state of being irregular or inconsistent with a pattern","definitionCN":"不规则、或与某种模式不一致的性质或状态","example":"The anomaly of the situation was that everyone obeyed a rule no one could state.","exampleCN":"这种局面的反常之处在于：人人都遵守一条谁也说不出的规则。","why":"The abstract -ia/-y noun can name a condition rather than a concrete object; irregularity itself becomes the referent.","whyCN":"抽象的 -ia/-y 名词可以命名一种状况，而不是具体物体；不规则性本身成为了所指。"},{"no":"03","title":"An unexplained scientific observation","titleCN":"无法解释的科学观测","definition":"an observation or measurement that does not fit an established model","definitionCN":"不符合既有模型的观测或测量结果","example":"A tiny anomaly in the orbit suggested a hidden moon.","exampleCN":"轨道上一个小小的异常暗示着一颗隐藏的卫星。","why":"Science is built on regular models; a reading that refuses the model becomes a named object of investigation, so anomaly means a datum that must be explained.","whyCN":"科学建立在规律模型之上；拒绝服从模型的读数会成为被命名的调查对象，因此 anomaly 指一个必须被解释的数据。"},{"no":"04","title":"A congenital or structural medical deviation","titleCN":"先天性或结构性的医学异常","definition":"a congenital or structural deviation from usual anatomy or development","definitionCN":"与通常解剖结构或发育过程不同的先天或结构性偏离","example":"The ultrasound revealed a cardiac anomaly.","exampleCN":"超声检查发现了一处心脏异常。","why":"Medicine applies the rule-deviation sense to the body: a structure that does not follow the usual developmental pattern is an anomaly, often neutral rather than a disease.","whyCN":"医学把“偏离规则”的义项用到身体上：不按通常发育模式生长的结构就是 anomaly，它常是中性的，并不等于疾病。"},{"no":"05","title":"A statistical outlier","titleCN":"统计上的离群值","definition":"a data point or pattern that lies far outside the expected distribution","definitionCN":"远远落在预期分布之外的数据点或模式","example":"The statistician removed the anomaly before fitting the model.","exampleCN":"统计学家在拟合模型之前先剔除了那个异常值。","why":"Statistics gives 'expected' a precise form; whatever falls outside the distribution is an anomaly, and the word becomes a technical label for outliers.","whyCN":"统计学把“预期”变成精确形式；落在分布之外的东西就是 anomaly，这个词于是成为离群值的技术标签。"},{"no":"06","title":"A market anomaly","titleCN":"市场异象","definition":"a price or return pattern that contradicts an accepted market model","definitionCN":"与公认市场模型相矛盾的价格或收益模式","example":"The January effect is a well-known market anomaly.","exampleCN":"一月效应是一个众所周知的市场异象。","why":"Financial models assume a rule; a repeatable exception is called an anomaly because it should not exist under the model yet persists.","whyCN":"金融模型预设一条规则；可重复的例外被称为 anomaly，因为按模型它本不该存在，却持续出现。"},{"no":"07","title":"The astronomical anomaly angle","titleCN":"天文学上的近点角","definition":"the angular distance of a body from its perihelion, or the corresponding orbital parameter","definitionCN":"天体离近日点的角距离，或相应的轨道参数","example":"The satellite's true anomaly changes as it moves along the ellipse.","exampleCN":"卫星沿椭圆运动时，它的真近点角不断变化。","why":"This is a specialized astronomical sense: unequal motion along an orbit echoes the original 'unevenness', and astronomy kept the Greek word for the measured angle.","whyCN":"这是一个专门的天文义项：沿轨道的非匀速运动呼应了最初的“不平整”，天文学保留了希腊词来指这个被测量的角。"},{"no":"08","title":"A grammatical or logical irregularity","titleCN":"语法或逻辑上的不规则","definition":"an irregular form or a statement that breaks an expected grammatical or logical pattern","definitionCN":"打破预期语法或逻辑模式的不规则形式或陈述","example":"The plural 'children' is an anomaly from the point of view of the -s rule.","exampleCN":"从 -s 规则的角度看，复数 children 是一个不规则形式。","why":"Grammar and logic are systems of rules; an item that cannot be generated by the rule is an anomaly, whether it is a word form or a contradiction.","whyCN":"语法和逻辑都是规则系统；无法由规则生成的项目就是 anomaly，无论它是一个词形还是一个矛盾。"},{"no":"09","title":"A person who does not fit the group","titleCN":"不合群体规范的异类","definition":"a person or institution that does not fit the norms of its group","definitionCN":"不符合所属群体规范的人或机构","example":"As the only vegetarian in the hunting club, he was treated as an anomaly.","exampleCN":"作为狩猎俱乐部里唯一的素食者，他被当作一个异类。","why":"The rule-deviation sense extends to people: someone whose behavior does not match the group's pattern is perceived as an exception, sometimes with a stigma.","whyCN":"“偏离规则”的义项可以延伸到人：行为不符合群体模式的人会被看作例外，有时还带有污名。"}],"etymology":{"intro":{"en":"Anomaly is a Greek loan, not a Latin negative of normal. Greek an- 'not' + homalos 'even' (from homos 'same') gives 'not even, not level with the rest'. The noun suffix -ia/-y turns the quality into a state or a thing. Normal is from Latin norma 'carpenter's square', an unrelated word; abnormal is a later reshaping of anormal under norma's influence. Do not parse anomaly as a + normal.","cn":"anomaly 是希腊语借词，不是 normal 的拉丁否定形式。希腊语 an-“不”+ homalos“平的”（来自 homos“同一”）给出“不平、与其余不齐”。名词后缀 -ia/-y 把性质变成状态或事物。normal 来自拉丁语 norma“木匠曲尺”，是完全无关的词；abnormal 是后来在 norma 影响下对 anormal 的改写。不要把 anomaly 拆成 a + normal。"},"items":[{"era":"1570s","en":"First recorded in English as 'unevenness', a literal borrowing of the Greek noun.","cn":"英语最早记录为“不平整”，是对希腊语名词的字面借用。"},{"era":"1660S","en":"The sense 'deviation from the common rule' appears; from 1722 the word also names 'something abnormal or irregular'.","cn":"“偏离共同规则”的义项出现；从 1722 年起，这个词也指“某种反常或不规则的事物”。"},{"era":"GREEK","en":"Latin anomalia < Greek anomalia 'inequality', an abstract noun from anomalos 'uneven, irregular'.","cn":"拉丁语 anomalia < 希腊语 anomalia“不平等”，是由 anomalos“不平整、不规则”构成的抽象名词。"},{"era":"GREEK COMPOUND","en":"anomalos = an- 'not' + homalos 'even, level'. homalos is built on homos 'one and the same', from PIE *sem- 'one, together'. The image is a surface that is not level with its neighbours.","cn":"anomalos = an-“不”+ homalos“平的、水平的”。homalos 由 homos“同一”构成，后者来自原始印欧语 *sem-“一、共同”。意象是一块与邻近部分不齐平的表面。"},{"era":"SEMANTIC SHIFT","en":"From physical unevenness the word moves to any departure from a rule or type, and then to the thing that departs. The -y noun names both the deviation and the deviant case.","cn":"这个词从物理上的不平整，转向任何对规则或类型的偏离，再转向偏离的事物本身。-y 名词既命名偏离，也命名偏离的个案。"},{"era":"MODERN ENGLISH","en":"Anomaly is the noun, anomalous the adjective, anomalously the adverb. There is no norma in it. Abnormal is historically connected but was reshaped by Medieval Latin anormalus under the influence of norma, which is why its spelling looks Latin rather than Greek.","cn":"anomaly 是名词，anomalous 是形容词，anomalously 是副词。它里面没有 norma。abnormal 在历史上与它有关，但受 norma 影响被中世纪拉丁语 anormalus 改写，所以拼写看起来像拉丁语而不是希腊语。"}]},"similar":{"note":{"en":"The first group separates the adjective and adverb from the noun, and marks normal as a false base; the second compares words for deviations of different kinds.","cn":"第一组把形容词、副词同名词分开，并指出 normal 是假词基；第二组比较不同类型的“偏离”用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"anomalous","ipa":"/əˈnɒmələs/","tag":"adjective","definition":"deviating from a rule or class pattern. It describes the thing; anomaly names it or the deviation itself.","definitionCN":"偏离规则或同类模式的。它描述事物；anomaly 命名该事物或偏离本身。"},{"word":"anomalously","ipa":"/əˈnɒmələsli/","tag":"adverb","definition":"in a way that deviates from the rule. It modifies a verb or adjective, while anomaly is a noun.","definitionCN":"以偏离规则的方式。它修饰动词或形容词，而 anomaly 是名词。"},{"word":"normal","ipa":"/ˈnɔːməl/","tag":"different root","definition":"conforming to a standard or usual pattern, from Latin norma 'carpenter's square'. It is unrelated to anomaly and must not be read as its positive base.","definitionCN":"符合标准或通常模式的，来自拉丁语 norma“木匠曲尺”。它与 anomaly 无关，不能当作它的肯定词基。"},{"word":"abnormal","ipa":"/æbˈnɔːməl/","tag":"reshaped relative","definition":"deviating from the normal, often in an unhealthy or unacceptable way. It began as anormal, an altered borrowing of Greek anomalos under the influence of norma, so the history is tangled rather than a simple negation.","definitionCN":"偏离正常的，常带不健康或不可接受的意味。它最初是 anormal，是在 norma 影响下对希腊语 anomalos 的改写借词，因此其历史是纠缠的，而不是简单的否定。"}]},{"heading":"NEAR MEANING","entries":[{"word":"aberration","ipa":"/ˌæbəˈreɪʃn/","tag":"temporary deviation","definition":"a deviation from what is normal or expected, often temporary, optical, or psychological. It stresses a departure from a path, while anomaly stresses failure to fit a rule or class.","definitionCN":"对正常或预期状态的偏离，常是暂时的、光学的或心理的。它强调偏离路径，而 anomaly 强调不符合规则或类别。"},{"word":"irregularity","ipa":"/ɪˌreɡjuˈlærəti/","tag":"lack of regularity","definition":"the state of not being regular, or an irregular thing. It is broader and can describe shape or timing; anomaly is typically a case that contradicts a model.","definitionCN":"不规则的状态，或不规则的事物。它更宽泛，可描述形状或时间；anomaly 通常是违背某个模型的个案。"},{"word":"outlier","ipa":"/ˈaʊtlaɪə/","tag":"statistical","definition":"a value far from the rest of a data set. It is the statistics term for one kind of anomaly, not a general word for rule-breaking.","definitionCN":"远离数据集其余部分的值。它是统计学对某类 anomaly 的术语，而不是泛指违反规则的词。"},{"word":"deviation","ipa":"/ˌdiːviˈeɪʃn/","tag":"departure","definition":"the act or amount of departing from a standard. It names the gap or movement; anomaly often names the thing that sits in the gap.","definitionCN":"偏离标准的动作或幅度。它命名差距或移动；anomaly 常命名位于差距中的那个事物。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Greek an- 'not' + homalos 'even' (from homos 'same'), the noun suffix -y, the adjective anomalous, and the false resemblance to normal.","cn":"只用真实成分与真实同族词：希腊语 an-“不”+ homalos“平的”（来自 homos“同一”）、名词后缀 -y、形容词 anomalous，以及与 normal 的假相似。"},"normal":[{"en":"Greek an- 'not' + homalos 'even' (from homos 'same') gives the literal sense 'not even, not level with the rest'.","cn":"希腊语 an-“不”+ homalos“平的”（来自 homos“同一”）给出字面义“不平、与其余不齐”。"},{"en":"The noun suffix -ia/-y turns 'uneven' into 'unevenness' and then into 'the uneven thing itself'.","cn":"名词后缀 -ia/-y 把“不平的”变成“不平整”，再变成“不平整的那个事物”。"},{"en":"The same Greek root gives anomalous, the adjective; anomaly is the noun.","cn":"同一希腊词根给出形容词 anomalous；anomaly 是名词。"},{"en":"There is no normal in anomaly: normal comes from Latin norma 'carpenter's square'. The resemblance is misleading.","cn":"anomaly 里没有 normal：normal 来自拉丁语 norma“木匠曲尺”。这种相似是误导。"},{"en":"Technical collocations mark branches: statistical anomaly, congenital anomaly, market anomaly, true anomaly (astronomy).","cn":"技术搭配标记分支：statistical anomaly、congenital anomaly、market anomaly、true anomaly（天文学）。"}],"abstract":[{"en":"A row of tiles laid flat: one tile stands slightly proud of the surface, and the eye catches it at once. That proud tile is the anomaly.","cn":"一排铺平的砖：有一块微微凸出表面，眼睛立刻注意到它。那块凸起的砖就是 anomaly。"},{"en":"A ruler laid on a supposedly flat table: the gap under the edge is the deviation, and the word can name either the gap or the thing causing it.","cn":"把尺子放在一张本应平整的桌上：尺边下的缝隙就是偏离，这个词既能命名缝隙，也能命名造成缝隙的东西。"},{"en":"A model train running on a track: one wheel that does not match the gauge makes the car jump; the mismatch is the anomaly, not the whole railway.","cn":"一辆在轨道上跑的模型火车：一个轮子不合轨距，车厢就会颠一下；不合之处才是 anomaly，而不是整条铁路。"}]},"examples":[{"en":"The satellite's orbit showed a small anomaly that led to a new moon being found.","cn":"卫星轨道出现一个小异常，最终导致发现了一颗新卫星。"},{"en":"The doctor found a congenital anomaly in the infant's heart.","cn":"医生在婴儿心脏上发现了一处先天性异常。"},{"en":"The statistician flagged the anomaly before running the model.","cn":"统计学家在运行模型前标记了那个异常值。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「俺 no 麻利」——别人都麻利，就它不麻利 → anomaly 反常、异常（只借音，不表词源）","word":"anomaly"},"root":"希腊语 anomalia“不规则”< anomalos“不平整”（an- 不 + homalos 平的 < homos 同一）；核心是“偏离同类规则的凹凸”，与 normal（norma 曲尺）无关。","sensesIntro":{"en":"Nine senses of anomaly move from a general departure to a state, a scientific reading, a medical structure, a statistical outlier, a market exception, an orbital angle, a grammatical irregularity, and a person out of place.","cn":"anomaly 的九个义项从一般偏离出发，走向状态、科学读数、医学结构、统计离群值、市场例外、轨道角、语法不规则，以及一个与群体不合的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: one item that is not level with the rest of its row.","cn":"核心意象：一个与同排其余部分不齐平的项。"},"chain":["EVEN SURFACE","NOT LEVEL","DEVIATION","ODD CASE","TECHNICAL VALUE","OUTLIER"],"branches":[{"senses":"01 · 02","en":"THE BASIC RELATION: a thing departs from a rule, and the departure can also be named as a state.","cn":"基本关系：一个事物偏离规则，而这种偏离也可以被命名为一种状态。"},{"senses":"03 · 05 · 08","en":"SCIENCE, STATISTICS AND LOGIC: a reading, an outlier, or a form that the model cannot generate.","cn":"科学、统计与逻辑：模型无法生成的读数、离群值或形式。"},{"senses":"04","en":"MEDICINE: a structure that does not follow the usual developmental pattern.","cn":"医学：不按通常发育模式形成的结构。"},{"senses":"06 · 07","en":"SPECIALIZED MEASURES: a market exception and the astronomical angle that first gave the word its technical sense.","cn":"专门测量：市场例外，以及最早赋予这个词技术义的天文角度。"},{"senses":"09","en":"SOCIAL: a person whose behavior does not fit the group's norms.","cn":"社会：行为不符合群体规范的人。"}]},"affixes":{"intro":{"en":"Anomaly is not built from an English prefix and root; it is a Greek compound borrowed whole. an- 'not' + homalos 'even' (from homos 'same') + the abstract noun ending -ia, which English shortens to -y. The adjective anomalous adds Latin -ous to the Greek stem, while normal belongs to Latin norma and is unrelated.","cn":"anomaly 不是由英语前缀和词根构成的，而是整体借入的希腊语复合词。an-“不”+ homalos“平的”（来自 homos“同一”）+ 抽象名词词尾 -ia，英语将其缩短为 -y。形容词 anomalous 在希腊词干上加拉丁 -ous，而 normal 属于拉丁语 norma，与它无关。"},"latinIntro":{"en":"The word reached English through Latin anomalia, but the compound is Greek. Latin contributes the adjective ending -ous in anomalous and the reshaped form anormalus behind abnormal; it does not contribute the root. Normal and norma are a separate Latin family.","cn":"这个词经拉丁语 anomalia 进入英语，但复合词本身是希腊语的。拉丁语贡献的是 anomalous 中的形容词词尾 -ous，以及 abnormal 背后被改写的 anormalus；它没有贡献词根。normal 与 norma 是另一支拉丁词族。"},"items":[{"word":"anomaly","structure":"Greek anomalia (abstract noun), borrowed through Latin","meaning":"unevenness; deviation from a rule","meaningCN":"不平整；对规则的偏离（希腊语抽象名词）","example":"The anomaly was visible in the first month of data.","exampleCN":"这个异常在第一个月的数据里就显现出来。"},{"word":"anomalos","structure":"an- (not) + homalos (even)","meaning":"uneven, irregular","meaningCN":"不平整的；不规则的（an- 不 + homalos 平的）","example":"The Greek adjective anomalos underlies both anomaly and anomalous.","exampleCN":"希腊语形容词 anomalos 是 anomaly 与 anomalous 的共同基础。"},{"word":"an-","structure":"Greek privative prefix 'not, without'","meaning":"not, without","meaningCN":"不；无（希腊语否定前缀）","example":"The an- in anomalos is the Greek negative, not the Latin in-.","exampleCN":"anomalos 中的 an- 是希腊语否定前缀，不是拉丁语 in-。"},{"word":"homalos","structure":"Greek adjective from homos 'same'","meaning":"even, level","meaningCN":"平的；水平的（来自 homos“同一”）","example":"homalos describes a surface that is level with its neighbours.","exampleCN":"homalos 描述与邻近部分齐平的表面。"},{"word":"homos","structure":"Greek adjective; PIE *sem- 'one, together'","meaning":"one and the same","meaningCN":"同一的；相同的","example":"homos is the source of many Greek-derived words about sameness.","exampleCN":"homos 是许多表示“相同”的希腊派生词的来源。"},{"word":"anomalous","structure":"Greek anomalos + Latin -ous (having the nature of)","meaning":"deviating from a rule or class pattern","meaningCN":"异常的；不合规则的（希腊词干 + 拉丁 -ous）","example":"The anomalous reading was checked twice.","exampleCN":"那个异常读数被检查了两次。"},{"word":"anomalously","structure":"anomalous + -ly (adverb)","meaning":"in a deviating manner","meaningCN":"异常地；不合规则地（-ly 构成副词）","example":"The particle behaved anomalously at low temperature.","exampleCN":"该粒子在低温下表现出异常行为。"},{"word":"anomalousness","structure":"anomalous + -ness (noun of quality)","meaning":"the quality of being anomalous","meaningCN":"异常性；不合规则的性质（-ness 构成性质名词）","example":"The anomalousness of the result prompted a second experiment.","exampleCN":"结果的异常性促使他们做了第二次实验。"},{"word":"abnormal","structure":"anormal (altered from Greek anomalos) reshaped under Latin norma","meaning":"deviating from the normal, often suggesting harm","meaningCN":"异常的；反常的（常含不良意味；拼写受 norma 影响）","example":"The abnormal reading was sent to the lab for review.","exampleCN":"那个异常读数被送到实验室复核。"},{"word":"normal","structure":"Latin normalis < norma 'carpenter's square, rule'","meaning":"conforming to a standard","meaningCN":"正常的；符合标准的（来自 norma 曲尺、规则）","example":"The normal range is printed beside each test value.","exampleCN":"每个检测值旁边都印着正常范围。"}],"latinEntries":[{"word":"anomalia","structure":"Latin borrowing of Greek anomalia","meaning":"unevenness, irregularity","meaningCN":"不平整；不规则"},{"word":"anomalus","structure":"Late Latin borrowing of Greek anomalos","meaning":"uneven, irregular","meaningCN":"不平整的；不规则的"},{"word":"norma","structure":"Latin noun of uncertain origin; 'carpenter's square, rule'","meaning":"rule, pattern, standard","meaningCN":"规则；模式；标准（与 anomaly 无关的对照词）"}]}},{"word":"anomalous","ipa_uk":"/əˈnɒmələs/","ipa_us":"/əˈnɑːmələs/","definition_zh":"异常的；反常的；不合规则的；不合同类模式的","definition_en":"deviating from a general rule or from the pattern shared by other members of a class","core_image":"同一批模具压出的零件中，有一个尺寸不合规，无法与其余零件装配齐平","scene":"同一批零件里有一个尺寸不合规，质检员把它单独挑出来。One part in the batch has an anomalous size, so the inspector picks it out and puts it in a separate box.","sceneCN":"这里 anomalous 是「不合同类模式的」（第 2 个义项：与同类其他成员共享的模式不一致）；句意：同一批零件里有一个尺寸异常，质检员把它挑出来放进单独的盒子。场景要点：流水线上的同批零件、卡尺、标红的尺寸、单独的收纳盒、质检员的手。","pos":[{"tag":"adj.","zh":"异常的；反常的；不合规则的"}],"collocations":[{"phrase":"anomalous result","zh":"异常结果"},{"phrase":"anomalous behavior","zh":"反常行为"},{"phrase":"anomalous data","zh":"异常数据"},{"phrase":"anomalous position","zh":"异常位置；不合常理的位置"},{"phrase":"anomalous expansion","zh":"反常膨胀（如水的特性）"},{"phrase":"anomalous finding","zh":"异常发现"},{"phrase":"anomalous situation","zh":"反常局面"}],"forms":[{"label":"比较级（更多用 more 构成）","form":"more anomalous"},{"label":"最高级（更多用 most 构成）","form":"most anomalous"}],"derivatives":[{"word":"anomaly","pos":"n.","zh":"异常；反常的事物"},{"word":"anomalously","pos":"adv.","zh":"异常地；不合规则地"},{"word":"anomalousness","pos":"n.","zh":"异常性；不合规则"}],"senses":[{"no":"01","title":"Not conforming to a general rule","titleCN":"不符合一般规则的","definition":"deviating from what is usual or from a general rule","definitionCN":"偏离通常情况或一般规则的","example":"The committee received an anomalous report of a bird nesting in winter.","exampleCN":"委员会收到一份反常的报告，说有一种鸟在冬天筑巢。","why":"The adjective describes the member that fails the rule; -ous means 'having the nature of', so anomalous = having the nature of a deviation.","whyCN":"这个形容词描述那个不服从规则的成员；-ous 意为“具有……的性质”，所以 anomalous 就是“具有偏离性质的”。"},{"no":"02","title":"Not fitting the pattern of its class","titleCN":"不合同类模式的","definition":"not matching the pattern shared by other members of the same class or type","definitionCN":"与同类其他成员共享的模式不一致","example":"An anomalous mineral in the sample did not match the surrounding rock.","exampleCN":"样本里有一种异常矿物，与周围岩石并不匹配。","why":"The Greek image is 'not even with its neighbours'. The word stresses mismatch within a class, not mere rarity.","whyCN":"希腊语意象是“与邻居不齐平”。这个词强调类别内部的不匹配，而不是单纯的罕见。"},{"no":"03","title":"Inconsistent with a scientific model","titleCN":"与科学模型不一致的","definition":"inconsistent with an established scientific model or expected result","definitionCN":"与既有科学模型或预期结果不一致的","example":"The probe sent back anomalous readings before it failed.","exampleCN":"探测器在失灵前发回了异常读数。","why":"When a measurement does not fit the model, the adjective marks the reading as suspect; the noun anomaly names the reading itself.","whyCN":"当测量不符合模型时，形容词把读数标记为可疑；名词 anomaly 则命名读数本身。"},{"no":"04","title":"Departing from normal anatomy","titleCN":"偏离正常解剖结构的","definition":"describing a structure or development that departs from the usual anatomical pattern","definitionCN":"描述偏离通常解剖模式的结构或发育","example":"The scan showed an anomalous blood vessel near the heart.","exampleCN":"扫描显示心脏附近有一根异常血管。","why":"Medicine uses the class-pattern sense for anatomy: the vessel is anomalous because it does not follow the usual branching pattern.","whyCN":"医学把“类别模式”义用于解剖：这根血管之所以是 anomalous，是因为它不按通常的分支模式生长。"},{"no":"05","title":"Outside the expected distribution","titleCN":"落在预期分布之外的","definition":"lying outside the expected distribution or pattern in a data set","definitionCN":"在数据集中落在预期分布或模式之外的","example":"An anomalous cluster of cases appeared in the northern district.","exampleCN":"北部地区出现了一组异常病例。","why":"Statistics makes 'expected' numerical; a point far from the distribution is anomalous, and the adjective often precedes 'result' or 'data'.","whyCN":"统计学把“预期”变成数值；远离分布的点就是 anomalous，这个形容词常放在 result 或 data 之前。"},{"no":"06","title":"Unusual against social norms","titleCN":"违反社会规范而显得反常的","definition":"unusual in a way that does not fit the norms of a group or situation","definitionCN":"不寻常到不符合某个群体或情境规范的程度","example":"His anomalous silence during the meeting worried his colleagues.","exampleCN":"他在会上反常的沉默让同事们担心。","why":"Social norms are rules too; behavior that does not match them is described as anomalous, often suggesting something is wrong or unexplained.","whyCN":"社会规范也是规则；不符合规范的行为会被描述为 anomalous，通常暗示出了什么问题或有什么无法解释。"},{"no":"07","title":"Contradicting a market model","titleCN":"与市场模型相矛盾的","definition":"producing a return or pattern that contradicts an accepted market model","definitionCN":"产生与公认市场模型相矛盾的收益或模式","example":"The fund was built to profit from anomalous pricing between two markets.","exampleCN":"这只基金旨在从两个市场之间的异常定价中获利。","why":"Finance treats market models as rules; a persistent exception is anomalous, whether it is a price gap or a seasonal effect.","whyCN":"金融把市场模型当作规则；持续存在的例外就是 anomalous，无论它表现为价格差还是季节性效应。"},{"no":"08","title":"Irregular in linguistic form","titleCN":"语言形式上不规则的","definition":"not following the regular inflection or sound pattern of a language","definitionCN":"不遵循某种语言的规则屈折或语音模式","example":"The anomalous plural was memorized as a single exception.","exampleCN":"那个不规则复数被当作单个例外记住了。","why":"A language's regular forms are generated by rules; an irregular form is anomalous because it does not share the class pattern, though native speakers use it easily.","whyCN":"语言的规则形式由规则生成；不规则形式之所以是 anomalous，是因为它不共享类别模式，尽管母语者用起来毫不费力。"},{"no":"09","title":"Inconsistent with a logical system","titleCN":"与逻辑体系不一致的","definition":"not consistent with an accepted principle or with the rest of a system","definitionCN":"与公认原则或体系其余部分不一致的","example":"The hypothesis was rejected because it left an anomalous set of facts unexplained.","exampleCN":"这个假说被否定了，因为它留下一组无法解释的反常事实。","why":"In logic and philosophy, a fact that will not fit the system is anomalous; the word names the friction between a case and its governing rule.","whyCN":"在逻辑和哲学中，无法嵌入体系的事实就是 anomalous；这个词命名个案与其统辖规则之间的摩擦。"}],"etymology":{"intro":{"en":"Anomalous is the adjective from the same Greek stem as anomaly: Greek anomalos 'uneven, irregular' (an- 'not' + homalos 'even', from homos 'same'). It reached English in the 1640s through Late Latin anomalus, with the English adjective ending -ous. The core is 'deviating from the rule of its class', not 'rare'. Normal comes from Latin norma and is unrelated; abnormal is a reshaped borrowing of the same Greek word, altered under norma's influence.","cn":"anomalous 是与 anomaly 同出希腊词干的形容词：希腊语 anomalos“不平整、不规则”（an-“不”+ homalos“平的”，后者来自 homos“同一”）。它于 17 世纪 40 年代经晚期拉丁语 anomalus 进入英语，并带英语形容词词尾 -ous。核心是“偏离同类规则”，而不是“罕见”。normal 来自拉丁语 norma，与之无关；abnormal 是同一希腊词在 norma 影响下被改写的借词。"},"items":[{"era":"1640S","en":"First recorded as 'deviating from a general rule', borrowed through Late Latin anomalus from Greek anomalos.","cn":"最早记录为“偏离一般规则的”，经晚期拉丁语 anomalus 借自希腊语 anomalos。"},{"era":"LATE LATIN","en":"anomalus is the Latinized form of Greek anomalos 'uneven, irregular'; it keeps the Greek negative an-, not Latin in- or ab-.","cn":"anomalus 是希腊语 anomalos“不平整、不规则”的拉丁化形式；它保留希腊语否定前缀 an-，而不是拉丁语 in- 或 ab-。"},{"era":"GREEK","en":"anomalos = an- 'not' + homalos 'even, level'. homalos is built on homos 'same', from PIE *sem- 'one, together'.","cn":"anomalos = an-“不”+ homalos“平的、水平的”。homalos 由 homos“同一”构成，后者来自原始印欧语 *sem-“一、共同”。"},{"era":"ENGLISH -OUS","en":"The adjective ending -ous comes from Old French -ous and Latin -osus; added to anomalus it gives 'having the nature of the uneven or irregular'. The noun anomaly was already in English.","cn":"形容词词尾 -ous 来自古法语 -ous 和拉丁语 -osus；加在 anomalus 上得到“具有不平整或不规则性质的”。名词 anomaly 当时已进入英语。"},{"era":"SEMANTIC","en":"The core is not 'rare' but 'not conforming to the same measure as the class'. A member that fails the pattern is anomalous; the pattern itself may be perfectly ordinary.","cn":"核心不是“罕见”，而是“不与同类共用同一尺度”。不满足模式的成员是 anomalous；模式本身可能完全普通。"},{"era":"MODERN ENGLISH","en":"Anomalous result, data and behavior are the common collocations. Normal is unrelated (norma); abnormal was reshaped by norma. Anomalous kept the Greek shape and the meaning 'deviating from the rule of its class'.","cn":"anomalous result、data、behavior 是常见搭配。normal 与之无关（norma）；abnormal 受 norma 影响而被改写。anomalous 保留了希腊语外形和“偏离同类规则”的含义。"}]},"similar":{"note":{"en":"The first group separates the noun and adverb from the adjective and marks normal as a false base; the second compares near synonyms by what kind of 'not normal' they mean.","cn":"第一组把名词、副词同形容词分开，并指出 normal 是假词基；第二组按“不正常”的具体类型区分近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"anomaly","ipa":"/əˈnɒməli/","tag":"noun","definition":"a deviation or the thing that deviates. It is the noun; anomalous is the adjective that describes such a thing.","definitionCN":"偏离，或偏离的事物。它是名词；anomalous 是描述这类事物的形容词。"},{"word":"anomalously","ipa":"/əˈnɒmələsli/","tag":"adverb","definition":"in a deviating manner. It modifies an action, while anomalous modifies a noun.","definitionCN":"以偏离的方式。它修饰动作，而 anomalous 修饰名词。"},{"word":"normal","ipa":"/ˈnɔːməl/","tag":"different root","definition":"usual or conforming to a standard, from norma 'carpenter's square'. It is not the positive base of anomalous.","definitionCN":"通常的或符合标准的，来自 norma“木匠曲尺”。它不是 anomalous 的肯定词基。"},{"word":"abnormal","ipa":"/æbˈnɔːməl/","tag":"near synonym, different history","definition":"deviating from the normal and often suggesting harm. It is historically a reshaped borrowing of Greek anomalos, not a clean negative of normal.","definitionCN":"偏离正常的，常暗示有害。它在历史上是对希腊语 anomalos 的改写借词，不是 normal 的干净否定形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"atypical","ipa":"/ˌeɪˈtɪpɪkl/","tag":"not typical","definition":"not representative of its type. It stresses rarity or unrepresentativeness, while anomalous stresses failure to conform to a rule or class pattern.","definitionCN":"不能代表其类型的。它强调罕见或不具代表性，而 anomalous 强调不符合规则或类别模式。"},{"word":"aberrant","ipa":"/əˈberənt/","tag":"straying","definition":"departing from an accepted standard, often in behavior or biology. It carries a stronger sense of going astray than anomalous.","definitionCN":"偏离公认标准的，常用于行为或生物学。它比 anomalous 带有更强的“走入歧途”意味。"},{"word":"irregular","ipa":"/ɪˈreɡjələ/","tag":"shape or timing","definition":"not regular in form, spacing, or occurrence. It can describe a pattern; anomalous usually describes a case that contradicts the pattern.","definitionCN":"在形状、间隔或发生上不规则的。它可以描述一个模式；anomalous 通常描述违背该模式的个案。"},{"word":"exceptional","ipa":"/ɪkˈsepʃənl/","tag":"unusual, often positive","definition":"unusually good or unusually different. It often carries approval, whereas anomalous is neutral or suspicious.","definitionCN":"异常地好或异常地不同。它常带有赞许意味，而 anomalous 是中性的或带怀疑的。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Greek anomalos, the adjective ending -ous, the noun anomaly, and the false resemblance to normal from norma.","cn":"只用真实成分与真实同族词：希腊语 anomalos、形容词词尾 -ous、名词 anomaly，以及与 norma 来的 normal 之间的假相似。"},"normal":[{"en":"Greek anomalos 'not even' + Latin -ous 'having the nature of': anomalous means 'having the nature of a deviation'.","cn":"希腊语 anomalos“不平的”+ 拉丁 -ous“具有……性质的”：anomalous 意为“具有偏离性质的”。"},{"en":"anomaly is the noun, anomalous the adjective, anomalously the adverb; the endings do the grammar, not the meaning.","cn":"anomaly 是名词，anomalous 是形容词，anomalously 是副词；词尾负责语法，不改变核心含义。"},{"en":"Do not read a + normal: normal is from norma 'carpenter's square', a different root.","cn":"不要读成 a + normal：normal 来自 norma“木匠曲尺”，是不同词根。"},{"en":"abnormal began as anormal, a borrowing of Greek anomalos altered under the influence of norma; its history is tangled, so treat it as a near synonym, not a clean negative.","cn":"abnormal 最初是 anormal，是希腊语 anomalos 在 norma 影响下被改写的借词；它的历史是纠缠的，所以应把它当作近义词，而不是干净的否定形式。"},{"en":"Common collocations: anomalous result, anomalous data, anomalous behavior; each points to a case that fails the class pattern.","cn":"常见搭配：anomalous result、anomalous data、anomalous behavior；每一个都指向不符合类别模式的个案。"}],"abstract":[{"en":"A set of identical keys cut from one pattern: one key will not turn the lock because its teeth are not even with the others. It is anomalous.","cn":"一组按同一模板切出的钥匙：有一把插不进锁，因为它的齿与其余不齐。它就是 anomalous。"},{"en":"A flock of birds all flying in one direction: one bird keeps a different angle; the adjective describes that bird, not the flock.","cn":"一群鸟都朝一个方向飞：有一只保持不同角度；这个形容词描述的是那只鸟，而不是整群。"},{"en":"A printed page with one letter in a different font: the letter is anomalous because it does not share the rule of the page, even though it is readable.","cn":"一页印刷文字里有一个字母用了不同字体：这个字母是 anomalous，因为它不共享整页的规则，尽管它完全可读。"}]},"examples":[{"en":"The experiment produced an anomalous result that the team repeated three times.","cn":"实验产生了一个异常结果，团队重复了三次。"},{"en":"Water's anomalous expansion makes ice float.","cn":"水的反常膨胀使冰浮在水面上。"},{"en":"His anomalous silence made the others uneasy.","cn":"他反常的沉默让其他人不安。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「安 no 马勒斯」——‘俺 no 麻利’还偏要乱来 → anomalous 异常的、不合规的（只借音，不表词源）","word":"anomalous"},"root":"希腊语 anomalos“不平整、不规则”（an- 不 + homalos 平的）+ 拉丁形容词词尾 -ous；核心是“偏离同类规则”，与 normal（norma）无关。","sensesIntro":{"en":"Nine senses of anomalous all describe a case that fails a pattern: a general rule, its class, a scientific model, anatomy, a distribution, social norms, a market model, a language's inflection, or a logical system.","cn":"anomalous 的九个义项都描述一个不满足模式的个案：一般规则、所属类别、科学模型、解剖结构、数据分布、社会规范、市场模型、语言屈折或逻辑体系。"},"semanticMap":{"core":{"en":"CORE IMAGE: a member that is not level with the pattern shared by its class.","cn":"核心意象：一个与同类共享模式不齐平的成员。"},"chain":["SHARED PATTERN","NOT EVEN","MISMATCH","SUSPECT CASE","UNEXPLAINED","EXCEPTION"],"branches":[{"senses":"01 · 02","en":"THE CORE: failing a general rule and failing the specific pattern of one's class.","cn":"核心：不服从一般规则，也不符合所属类别的具体模式。"},{"senses":"03 · 05","en":"MODELS AND DATA: a reading or cluster that the model or distribution cannot accommodate.","cn":"模型与数据：模型或分布无法容纳的读数或集群。"},{"senses":"04","en":"ANATOMY: a structure that departs from the usual developmental pattern.","cn":"解剖：偏离通常发育模式的结构。"},{"senses":"06 · 09","en":"NORMS AND LOGIC: behavior or a fact that will not fit the group's norms or the system's principles.","cn":"规范与逻辑：无法嵌入群体规范或体系原则的行为或事实。"},{"senses":"07 · 08","en":"SPECIALIZED RULES: market models and linguistic inflection patterns each define what counts as anomalous.","cn":"专门规则：市场模型与语言屈折模式各自界定什么算 anomalous。"}]},"affixes":{"intro":{"en":"Anomalous is Late Latin anomalus (from Greek anomalos) + the English adjective ending -ous. The Greek compound is an- 'not' + homalos 'even' (from homos 'same'); -ous adds 'having the nature of'. The noun anomaly is the same stem with -y. Normal belongs to Latin norma and is not the base.","cn":"anomalous 是晚期拉丁语 anomalus（来自希腊语 anomalos）+ 英语形容词词尾 -ous。希腊语复合词是 an-“不”+ homalos“平的”（来自 homos“同一”）；-ous 加上“具有……性质”。名词 anomaly 是同一词干加 -y。normal 属于拉丁语 norma，并不是它的词基。"},"latinIntro":{"en":"Latin anomalus is only a Latinized Greek adjective; the compound's parts are Greek. Latin supplies the adjective ending -ous. The separate Latin family norma -> normalis -> normal is the source of the word that anomaly is mistakenly thought to negate.","cn":"拉丁语 anomalus 只是希腊语形容词的拉丁化形式；复合词的各部分是希腊语的。拉丁语提供形容词词尾 -ous。另一支拉丁词族 norma -> normalis -> normal，才是人们误以为 anomaly 所要否定的那个词的来源。"},"items":[{"word":"anomalous","structure":"Late Latin anomalus (from Greek anomalos) + -ous","meaning":"having the nature of a deviation from rule","meaningCN":"具有偏离规则性质的；异常的（-ous 构成形容词）","example":"The anomalous signal disappeared after the antenna was moved.","exampleCN":"天线移动后，那个异常信号消失了。"},{"word":"anomaly","structure":"Greek anomalia (abstract noun), borrowed through Latin","meaning":"a deviation; the thing that deviates","meaningCN":"偏离；偏离的事物（希腊语抽象名词）","example":"The anomaly was logged and sent to the team.","exampleCN":"这个异常被记录并发送给了团队。"},{"word":"anomalos","structure":"an- (not) + homalos (even)","meaning":"uneven, irregular","meaningCN":"不平整的；不规则的（an- 不 + homalos 平的）","example":"anomalos is the Greek source of both anomalous and anomaly.","exampleCN":"anomalos 是 anomalous 与 anomaly 的共同希腊语来源。"},{"word":"an-","structure":"Greek privative prefix 'not, without'","meaning":"not, without","meaningCN":"不；无（希腊语否定前缀）","example":"The an- here is Greek, not the Latin in-.","exampleCN":"这里的 an- 是希腊语前缀，不是拉丁语 in-。"},{"word":"homalos","structure":"Greek adjective from homos 'same'","meaning":"even, level","meaningCN":"平的；水平的（来自 homos“同一”）","example":"A homalos surface is level with its neighbours.","exampleCN":"homalos 的表面与邻近部分齐平。"},{"word":"homos","structure":"Greek adjective; PIE *sem- 'one, together'","meaning":"one and the same","meaningCN":"同一的；相同的","example":"homos underlies several Greek words about sameness.","exampleCN":"homos 是若干表示“相同”的希腊词的词根。"},{"word":"anomalously","structure":"anomalous + -ly (adverb)","meaning":"in a deviating manner","meaningCN":"异常地；不合规则地（-ly 构成副词）","example":"The metal expanded anomalously when cooled.","exampleCN":"这种金属冷却时反常地膨胀。"},{"word":"anomalousness","structure":"anomalous + -ness (noun of quality)","meaning":"the quality of being anomalous","meaningCN":"异常性；不合规则的性质（-ness 构成性质名词）","example":"The anomalousness of the pattern attracted notice.","exampleCN":"这个模式的异常性引起了注意。"},{"word":"abnormal","structure":"anormal (altered from Greek anomalos) reshaped under Latin norma","meaning":"deviating from the normal, often suggesting harm","meaningCN":"异常的；反常的（常含不良意味；拼写受 norma 影响）","example":"The abnormal result was checked against the reference range.","exampleCN":"那个异常结果被对照参考范围核查。"},{"word":"normal","structure":"Latin normalis < norma 'carpenter's square, rule'","meaning":"conforming to a standard","meaningCN":"正常的；符合标准的（来自 norma 曲尺、规则）","example":"The normal reading falls inside the printed range.","exampleCN":"正常读数落在印出的范围之内。"}],"latinEntries":[{"word":"anomalus","structure":"Late Latin borrowing of Greek anomalos","meaning":"uneven, irregular","meaningCN":"不平整的；不规则的"},{"word":"anomalia","structure":"Latin borrowing of Greek anomalia","meaning":"unevenness, irregularity","meaningCN":"不平整；不规则"},{"word":"norma","structure":"Latin noun of uncertain origin; 'carpenter's square, rule'","meaning":"rule, pattern, standard","meaningCN":"规则；模式；标准（与 anomalous 无关的对照词）"}]}}]);
